use serde::{Deserialize, Serialize};
use std::fmt;

use crate::expression::Expression;
use crate::machine::MachineDefinition;

/// Top-level command AST node.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum Command {
    /// DEFINE MACHINE ...
    DefineMachine(MachineDefinition),
    /// SPAWN Machine { data }
    Spawn(SpawnCommand),
    /// TRANSITION instance TO state
    Transition(TransitionCommand),
    /// TRY TRANSITION instance TO state
    TryTransition(TransitionCommand),
    /// TRANSITION ALL Machine WHERE ... TO state
    BatchTransition(BatchTransitionCommand),
    /// ALTER MACHINE ...
    AlterMachine(AlterMachineCommand),
}

impl fmt::Display for Command {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Command::DefineMachine(m) => write!(f, "DEFINE {}", m),
            Command::Spawn(s) => write!(f, "SPAWN {}", s.machine),
            Command::Transition(t) => write!(
                f,
                "TRANSITION {} {} TO {}",
                t.machine, t.instance_id, t.to_state
            ),
            Command::TryTransition(t) => {
                write!(
                    f,
                    "TRY TRANSITION {} {} TO {}",
                    t.machine, t.instance_id, t.to_state
                )
            }
            Command::BatchTransition(b) => {
                write!(f, "TRANSITION ALL {} TO {}", b.machine, b.to_state)
            }
            Command::AlterMachine(a) => write!(f, "ALTER MACHINE {}", a.machine),
        }
    }
}

/// A top-level SMQL statement — either a command or a query.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum Statement {
    Command(Command),
    Query(crate::query::Query),
}

/// SPAWN command — create a new instance.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SpawnCommand {
    pub machine: String,
    pub data: Vec<(String, Expression)>,
    /// Optional: immediately transition after spawn
    pub then_transition: Option<String>,
    /// Is this a batch spawn?
    pub batch: bool,
    /// For batch spawn, list of data sets
    pub batch_data: Vec<Vec<(String, Expression)>>,
    /// Parent instance ID (for child spawn in composition)
    pub parent_id: Option<String>,
    /// Parent machine name (for child spawn in composition)
    pub parent_machine: Option<String>,
}

impl SpawnCommand {
    pub fn new(machine: String, data: Vec<(String, Expression)>) -> Self {
        Self {
            machine,
            data,
            then_transition: None,
            batch: false,
            batch_data: Vec::new(),
            parent_id: None,
            parent_machine: None,
        }
    }
}

/// TRANSITION command — move an instance to a new state.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TransitionCommand {
    pub machine: String,
    pub instance_id: String,
    pub to_state: String,
    /// WITH { field: value, ... } — data mutations
    pub with_data: Vec<(String, Expression)>,
    /// MEMO "text" — human-readable note
    pub memo: Option<String>,
    /// AS actor — specify who is performing
    pub as_actor: Option<String>,
    /// THROUGH [state1, state2, ...] — multi-hop transition
    pub through: Vec<String>,
    /// OR STAY — apply mutations even if guard fails
    pub or_stay: bool,
    /// CASCADE — also transition all children to terminal states
    pub cascade: bool,
}

impl TransitionCommand {
    pub fn new(machine: String, instance_id: String, to_state: String) -> Self {
        Self {
            machine,
            instance_id,
            to_state,
            with_data: Vec::new(),
            memo: None,
            as_actor: None,
            through: Vec::new(),
            or_stay: false,
            cascade: false,
        }
    }
}

/// Batch TRANSITION command — transition multiple instances.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct BatchTransitionCommand {
    pub machine: String,
    pub filter: Expression,
    pub to_state: String,
    pub with_data: Vec<(String, Expression)>,
    pub memo: Option<String>,
    pub as_actor: Option<String>,
}

/// ALTER MACHINE command — modify an existing machine definition.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AlterMachineCommand {
    pub machine: String,
    pub operations: Vec<AlterOperation>,
}

/// Individual alter operations.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum AlterOperation {
    /// ADD STATE state_name
    AddState(String),
    /// REMOVE STATE state_name MIGRATE TO target_state
    RemoveState { state: String, migrate_to: String },
    /// ADD TRANSITION from -> to { ... }
    AddTransition(crate::machine::TransitionDefinition),
    /// REMOVE TRANSITION from -> to
    RemoveTransition { from: String, to: String },
    /// MODIFY TRANSITION from -> to { ... }
    ModifyTransition(crate::machine::TransitionDefinition),
    /// ADD DATA field_definition
    AddData {
        field: crate::types::DataFieldDefinition,
        backfill: Option<Expression>,
    },
    /// REMOVE DATA field_name
    RemoveData(String),
    /// BACKFILL field = expression
    Backfill { field: String, value: Expression },
}

use serde::{Deserialize, Serialize};
use std::fmt;

use crate::span::Span;

/// The top-level error type for all SMQL operations.
#[derive(Debug, Clone, thiserror::Error, Serialize, Deserialize)]
pub enum SmqlError {
    #[error("Parse error: {message}")]
    ParseError {
        message: String,
        span: Option<Span>,
        hint: Option<String>,
    },

    #[error("Validation error: {message}")]
    ValidationError {
        message: String,
        field: Option<String>,
        hint: Option<String>,
    },

    #[error("Transition denied: {0}")]
    TransitionDenied(TransitionDeniedError),

    #[error("Guard failed: {message}")]
    GuardFailed {
        message: String,
        guard_expr: String,
        actual_value: Option<String>,
        hint: Option<String>,
    },

    #[error("Spawn rejected: {message}")]
    SpawnRejected {
        message: String,
        field: Option<String>,
        hint: Option<String>,
    },

    #[error("Query error: {message}")]
    QueryError {
        message: String,
        hint: Option<String>,
    },

    #[error("Storage error: {message}")]
    StorageError { message: String, retryable: bool },

    #[error("Timeout error: {message}")]
    TimeoutError {
        message: String,
        instance_id: Option<String>,
        state: Option<String>,
    },

    #[error("Not found: {entity_type} '{id}'")]
    NotFound { entity_type: String, id: String },

    #[error("Conflict: {message}")]
    Conflict {
        message: String,
        hint: Option<String>,
    },

    #[error("Internal error: {message}")]
    Internal { message: String },
}

impl SmqlError {
    pub fn parse(message: impl Into<String>) -> Self {
        SmqlError::ParseError {
            message: message.into(),
            span: None,
            hint: None,
        }
    }

    pub fn parse_with_span(message: impl Into<String>, span: Span) -> Self {
        SmqlError::ParseError {
            message: message.into(),
            span: Some(span),
            hint: None,
        }
    }

    pub fn validation(message: impl Into<String>) -> Self {
        SmqlError::ValidationError {
            message: message.into(),
            field: None,
            hint: None,
        }
    }

    pub fn not_found(entity_type: impl Into<String>, id: impl Into<String>) -> Self {
        SmqlError::NotFound {
            entity_type: entity_type.into(),
            id: id.into(),
        }
    }

    pub fn storage(message: impl Into<String>) -> Self {
        SmqlError::StorageError {
            message: message.into(),
            retryable: false,
        }
    }

    pub fn internal(message: impl Into<String>) -> Self {
        SmqlError::Internal {
            message: message.into(),
        }
    }
}

/// Structured error for denied transitions, including all guard failures.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TransitionDeniedError {
    pub instance_id: String,
    pub from_state: String,
    pub to_state: String,
    pub guard_failures: Vec<GuardFailure>,
    pub hint: Option<String>,
}

impl fmt::Display for TransitionDeniedError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "Transition {} -> {} denied for instance {}",
            self.from_state, self.to_state, self.instance_id
        )?;
        if !self.guard_failures.is_empty() {
            write!(f, ":")?;
            for failure in &self.guard_failures {
                write!(f, "\n  - {}", failure)?;
            }
        }
        if let Some(hint) = &self.hint {
            write!(f, "\n  Hint: {}", hint)?;
        }
        Ok(())
    }
}

/// A single guard failure with context.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GuardFailure {
    pub guard_expr: String,
    pub actual_value: Option<String>,
    pub expected: Option<String>,
    pub hint: Option<String>,
}

impl fmt::Display for GuardFailure {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Guard '{}' failed", self.guard_expr)?;
        if let Some(actual) = &self.actual_value {
            write!(f, " (got: {})", actual)?;
        }
        if let Some(expected) = &self.expected {
            write!(f, " (expected: {})", expected)?;
        }
        if let Some(hint) = &self.hint {
            write!(f, " — {}", hint)?;
        }
        Ok(())
    }
}

/// Convenience result type.
pub type SmqlResult<T> = Result<T, SmqlError>;

use serde::{Deserialize, Serialize};
use std::fmt;

use crate::span::Span;
use crate::value::{SmqlDuration, Value};

/// Expressions used in guards, WHERE clauses, and MUTATE clauses.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Expression {
    pub kind: ExpressionKind,
    pub span: Option<Span>,
}

impl Expression {
    pub fn new(kind: ExpressionKind) -> Self {
        Self { kind, span: None }
    }

    pub fn with_span(kind: ExpressionKind, span: Span) -> Self {
        Self {
            kind,
            span: Some(span),
        }
    }
}

/// The core expression types.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum ExpressionKind {
    // Literals
    Literal(Value),
    DurationLiteral(SmqlDuration),

    // Field access
    /// Simple field reference: `priority`, `assignee`
    FieldAccess(Vec<String>),
    /// SELF keyword — refers to current instance
    SelfRef,
    /// ACTOR keyword — refers to the actor performing the transition
    ActorRef,
    /// ACTOR.field or SELF.field with path
    QualifiedAccess {
        root: Box<Expression>,
        path: Vec<String>,
    },

    // Binary operations
    BinaryOp {
        left: Box<Expression>,
        op: BinaryOperator,
        right: Box<Expression>,
    },

    // Unary operations
    UnaryOp {
        op: UnaryOperator,
        operand: Box<Expression>,
    },

    // Function calls
    FunctionCall {
        name: String,
        args: Vec<Expression>,
    },

    // State predicates
    /// STATE IS <state_name>
    StateIs(String),
    /// STATE IN { state1, state2, ... }
    StateIn(Vec<String>),

    // Null checks
    /// field IS SET
    IsSet(Box<Expression>),
    /// field IS NOT SET / IS NULL
    IsNotSet(Box<Expression>),

    // Set membership
    /// expr IN { val1, val2, ... }
    InSet {
        expr: Box<Expression>,
        values: Vec<Expression>,
    },
    /// expr IN (string_val1, string_val2, ...)
    InList {
        expr: Box<Expression>,
        values: Vec<Expression>,
    },

    // Collection predicates
    /// ALL(collection, predicate)
    All {
        collection: Box<Expression>,
        predicate: Box<Expression>,
    },
    /// ANY(collection, predicate)
    Any {
        collection: Box<Expression>,
        predicate: Box<Expression>,
    },
    /// COUNT(collection) or COUNT()
    Count(Option<Box<Expression>>),

    // Signal predicate (for transition guards)
    /// SIGNAL FROM Machine WHERE condition
    SignalFrom {
        machine: String,
        condition: Box<Expression>,
    },

    // Pattern matching
    /// PATTERN(regex_string)
    Pattern(String),
}

/// Binary operators.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum BinaryOperator {
    // Comparison
    Eq,
    NotEq,
    Lt,
    Gt,
    LtEq,
    GtEq,
    // Arithmetic
    Add,
    Sub,
    Mul,
    Div,
    // Logical
    And,
    Or,
}

impl fmt::Display for BinaryOperator {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            BinaryOperator::Eq => write!(f, "=="),
            BinaryOperator::NotEq => write!(f, "!="),
            BinaryOperator::Lt => write!(f, "<"),
            BinaryOperator::Gt => write!(f, ">"),
            BinaryOperator::LtEq => write!(f, "<="),
            BinaryOperator::GtEq => write!(f, ">="),
            BinaryOperator::Add => write!(f, "+"),
            BinaryOperator::Sub => write!(f, "-"),
            BinaryOperator::Mul => write!(f, "*"),
            BinaryOperator::Div => write!(f, "/"),
            BinaryOperator::And => write!(f, "AND"),
            BinaryOperator::Or => write!(f, "OR"),
        }
    }
}

/// Unary operators.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum UnaryOperator {
    Not,
    Neg,
}

impl fmt::Display for UnaryOperator {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            UnaryOperator::Not => write!(f, "NOT"),
            UnaryOperator::Neg => write!(f, "-"),
        }
    }
}

impl fmt::Display for Expression {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match &self.kind {
            ExpressionKind::Literal(v) => write!(f, "{}", v),
            ExpressionKind::DurationLiteral(d) => write!(f, "{}", d),
            ExpressionKind::FieldAccess(path) => write!(f, "{}", path.join(".")),
            ExpressionKind::SelfRef => write!(f, "SELF"),
            ExpressionKind::ActorRef => write!(f, "ACTOR"),
            ExpressionKind::QualifiedAccess { root, path } => {
                write!(f, "{}.{}", root, path.join("."))
            }
            ExpressionKind::BinaryOp { left, op, right } => {
                write!(f, "({} {} {})", left, op, right)
            }
            ExpressionKind::UnaryOp { op, operand } => write!(f, "({} {})", op, operand),
            ExpressionKind::FunctionCall { name, args } => {
                let arg_strs: Vec<String> = args.iter().map(|a| a.to_string()).collect();
                write!(f, "{}({})", name, arg_strs.join(", "))
            }
            ExpressionKind::StateIs(state) => write!(f, "STATE IS {}", state),
            ExpressionKind::StateIn(states) => write!(f, "STATE IN {{{}}}", states.join(", ")),
            ExpressionKind::IsSet(expr) => write!(f, "{} IS SET", expr),
            ExpressionKind::IsNotSet(expr) => write!(f, "{} IS NOT SET", expr),
            ExpressionKind::InSet { expr, values } => {
                let val_strs: Vec<String> = values.iter().map(|v| v.to_string()).collect();
                write!(f, "{} IN {{{}}}", expr, val_strs.join(", "))
            }
            ExpressionKind::InList { expr, values } => {
                let val_strs: Vec<String> = values.iter().map(|v| v.to_string()).collect();
                write!(f, "{} IN ({})", expr, val_strs.join(", "))
            }
            ExpressionKind::All {
                collection,
                predicate,
            } => write!(f, "ALL({}, {})", collection, predicate),
            ExpressionKind::Any {
                collection,
                predicate,
            } => write!(f, "ANY({}, {})", collection, predicate),
            ExpressionKind::Count(expr) => match expr {
                Some(e) => write!(f, "COUNT({})", e),
                None => write!(f, "COUNT()"),
            },
            ExpressionKind::SignalFrom { machine, condition } => {
                write!(f, "SIGNAL FROM {} WHERE {}", machine, condition)
            }
            ExpressionKind::Pattern(regex) => write!(f, "PATTERN({})", regex),
        }
    }
}

