use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fmt;

use crate::expression::Expression;
use crate::types::DataFieldDefinition;
use crate::value::SmqlDuration;

/// A complete machine definition, parsed from DEFINE MACHINE.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MachineDefinition {
    pub name: String,
    pub data: Vec<DataFieldDefinition>,
    pub states: Vec<StateDefinition>,
    pub initial_state: String,
    pub terminal_states: Vec<String>,
    pub transitions: Vec<TransitionDefinition>,
    pub children: Vec<ChildDefinition>,
    pub parent: Option<String>,
    pub hooks: Vec<HookDefinition>,
    pub roles: Vec<RoleDefinition>,
    pub version: u64,
    pub metadata: BTreeMap<String, String>,
}

impl MachineDefinition {
    pub fn new(name: String, initial_state: String) -> Self {
        Self {
            name,
            data: Vec::new(),
            states: Vec::new(),
            initial_state,
            terminal_states: Vec::new(),
            transitions: Vec::new(),
            children: Vec::new(),
            parent: None,
            hooks: Vec::new(),
            roles: Vec::new(),
            version: 1,
            metadata: BTreeMap::new(),
        }
    }
}

impl fmt::Display for MachineDefinition {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "MACHINE {} (v{})", self.name, self.version)
    }
}

/// A state within a machine.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct StateDefinition {
    pub name: String,
    pub metadata: BTreeMap<String, String>,
}

impl StateDefinition {
    pub fn new(name: String) -> Self {
        Self {
            name,
            metadata: BTreeMap::new(),
        }
    }
}

impl fmt::Display for StateDefinition {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.name)
    }
}

/// Source of a transition — can be a specific state, ANY, or a group.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum TransitionSource {
    /// A specific named state.
    State(String),
    /// ANY state (wildcard), with optional exceptions.
    Any { except: Vec<String> },
    /// A named group of states.
    Group(String),
}

impl fmt::Display for TransitionSource {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TransitionSource::State(s) => write!(f, "{}", s),
            TransitionSource::Any { except } => {
                if except.is_empty() {
                    write!(f, "ANY")
                } else {
                    write!(f, "ANY EXCEPT FROM {{{}}}", except.join(", "))
                }
            }
            TransitionSource::Group(g) => write!(f, "GROUP({})", g),
        }
    }
}

/// A transition definition between states.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TransitionDefinition {
    pub from: TransitionSource,
    pub to: String,
    pub guards: Vec<Expression>,
    pub actions: Vec<Action>,
    pub mutates: Vec<MutateClause>,
    pub timeout: Option<TimeoutClause>,
    pub memo: Option<String>,
}

impl TransitionDefinition {
    pub fn new(from: TransitionSource, to: String) -> Self {
        Self {
            from,
            to,
            guards: Vec::new(),
            actions: Vec::new(),
            mutates: Vec::new(),
            timeout: None,
            memo: None,
        }
    }
}

impl fmt::Display for TransitionDefinition {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} -> {}", self.from, self.to)
    }
}

/// Timeout clause on a transition: after duration, auto-transition to target.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TimeoutClause {
    pub duration: SmqlDuration,
    pub target_state: String,
}

impl fmt::Display for TimeoutClause {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "TIMEOUT: {} -> {}", self.duration, self.target_state)
    }
}

/// A mutation clause within a transition (MUTATE : field = expr).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MutateClause {
    pub field: String,
    pub value: Expression,
}

impl fmt::Display for MutateClause {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} = {}", self.field, self.value)
    }
}

/// Actions that fire on transitions.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum Action {
    /// NOTIFY(target, event_name)
    Notify { target: Expression, event: String },
    /// LOG(message_template)
    Log(String),
    /// EMIT(event_name, payload)
    Emit {
        event: String,
        payload: Option<Expression>,
    },
    /// WEBHOOK(url, payload)
    Webhook {
        url: String,
        payload: Option<Expression>,
    },
    /// SPAWN child machine
    SpawnChild {
        machine: String,
        data: Vec<(String, Expression)>,
    },
    /// SIGNAL PARENT TO state
    SignalParent { target_state: String },
}

impl fmt::Display for Action {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Action::Notify { target, event } => write!(f, "NOTIFY({}, \"{}\")", target, event),
            Action::Log(msg) => write!(f, "LOG(\"{}\")", msg),
            Action::Emit { event, .. } => write!(f, "EMIT(\"{}\")", event),
            Action::Webhook { url, .. } => write!(f, "WEBHOOK(\"{}\")", url),
            Action::SpawnChild { machine, .. } => write!(f, "SPAWN {}", machine),
            Action::SignalParent { target_state } => {
                write!(f, "SIGNAL PARENT TO {}", target_state)
            }
        }
    }
}

/// Child machine relationship definition.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ChildDefinition {
    pub name: String,
    pub machine: String,
    pub cardinality: ChildCardinality,
}

/// Cardinality of child relationships.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum ChildCardinality {
    /// LIST(Machine) -> optional MIN/MAX constraints
    List { min: Option<u64>, max: Option<u64> },
    /// OPTIONAL(Machine) — zero or one
    Optional,
    /// Single required child
    Required,
}

impl fmt::Display for ChildCardinality {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ChildCardinality::List { min, max } => {
                write!(f, "LIST")?;
                match (min, max) {
                    (Some(lo), Some(hi)) => write!(f, "({}..{})", lo, hi),
                    (Some(lo), None) => write!(f, "({}+)", lo),
                    (None, Some(hi)) => write!(f, "(..{})", hi),
                    (None, None) => Ok(()),
                }
            }
            ChildCardinality::Optional => write!(f, "OPTIONAL"),
            ChildCardinality::Required => write!(f, "REQUIRED"),
        }
    }
}

/// Hook definitions (ON SPAWN, BEFORE EACH TRANSITION, etc.)
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct HookDefinition {
    pub trigger: HookTrigger,
    pub actions: Vec<Action>,
}

/// When a hook fires.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum HookTrigger {
    OnSpawn,
    BeforeEachTransition,
    AfterEachTransition,
    OnEnter(String),
    OnExit(String),
    OnDwell {
        state: String,
        duration: SmqlDuration,
    },
}

impl fmt::Display for HookTrigger {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            HookTrigger::OnSpawn => write!(f, "ON SPAWN"),
            HookTrigger::BeforeEachTransition => write!(f, "BEFORE EACH TRANSITION"),
            HookTrigger::AfterEachTransition => write!(f, "AFTER EACH TRANSITION"),
            HookTrigger::OnEnter(state) => write!(f, "ON ENTER {}", state),
            HookTrigger::OnExit(state) => write!(f, "ON EXIT {}", state),
            HookTrigger::OnDwell { state, duration } => {
                write!(f, "ON DWELL({}, > {})", state, duration)
            }
        }
    }
}

/// Role-based access control definition.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RoleDefinition {
    pub name: String,
    pub permissions: Vec<RolePermission>,
}

/// Permissions within a role.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum RolePermission {
    CanSpawn,
    CanTransition(Vec<String>),
    CanQuery,
    CanAlter,
}

use serde::{Deserialize, Serialize};
use std::fmt;

use crate::expression::Expression;
use crate::types::{AggregateFunction, SortClause};

/// Top-level query AST node.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum Query {
    /// GET Machine instance_id
    Get(GetQuery),
    /// FIND Machine WHERE ...
    Find(FindQuery),
    /// AGGREGATE Machine ...
    Aggregate(AggregateQuery),
    /// TRAIL OF instance_id
    Trail(TrailQuery),
    /// PATHS FROM Machine WHERE ...
    Paths(PathsQuery),
    /// FUNNEL Machine THROUGH [states]
    Funnel(FunnelQuery),
    /// COMPARE PATHS Machine SEGMENT BY field
    ComparePaths(ComparePathsQuery),
}

impl fmt::Display for Query {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Query::Get(q) => write!(f, "GET {} {}", q.machine, q.instance_id),
            Query::Find(q) => write!(f, "FIND {}", q.machine),
            Query::Aggregate(q) => write!(f, "AGGREGATE {}", q.machine),
            Query::Trail(q) => write!(f, "TRAIL OF {}", q.instance_id),
            Query::Paths(q) => write!(f, "PATHS FROM {}", q.machine),
            Query::Funnel(q) => write!(f, "FUNNEL {}", q.machine),
            Query::ComparePaths(q) => write!(f, "COMPARE PATHS {}", q.machine),
        }
    }
}

/// GET query — retrieve a single instance by ID.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct GetQuery {
    pub machine: String,
    pub instance_id: String,
}

/// FIND query — search for instances matching criteria.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FindQuery {
    pub machine: String,
    pub filter: Option<Expression>,
    pub sort: Vec<SortClause>,
    pub limit: Option<u64>,
    pub offset: Option<u64>,
    /// Cursor-based pagination: return instances with ID > after.
    #[serde(default)]
    pub after: Option<String>,
}

/// AGGREGATE query — compute aggregations over instances.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AggregateQuery {
    pub machine: String,
    pub measures: Vec<MeasureClause>,
    pub filter: Option<Expression>,
    pub group_by: Vec<GroupByClause>,
}

/// A MEASURE clause in an AGGREGATE query.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MeasureClause {
    pub function: AggregateFunction,
    pub field: Option<String>,
    pub alias: Option<String>,
}

/// GROUP BY clause — can be a field or time bucket.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum GroupByClause {
    Field(String),
    State,
    TimeBucket { field: String, interval: String },
}

/// TRAIL query — retrieve transition history.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TrailQuery {
    pub machine: Option<String>,
    pub instance_id: String,
    pub filter: Option<TrailFilter>,
}

/// Filters for trail queries.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TrailFilter {
    pub actor: Option<String>,
    pub from_state: Option<String>,
    pub to_state: Option<String>,
    pub since: Option<Expression>,
    pub until: Option<Expression>,
}

/// PATHS query — analyze state sequences from trail data.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PathsQuery {
    pub machine: String,
    pub filter: Option<Expression>,
    pub limit: Option<u64>,
}

/// FUNNEL query — conversion analysis through ordered states.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FunnelQuery {
    pub machine: String,
    pub states: Vec<String>,
    pub filter: Option<Expression>,
}

/// COMPARE PATHS query — segment path analysis.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ComparePathsQuery {
    pub machine: String,
    pub segment_by: String,
    pub filter: Option<Expression>,
}

use serde::{Deserialize, Serialize};

/// Source location span for error reporting.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    pub fn new(start: usize, end: usize) -> Self {
        Self { start, end }
    }

    pub fn merge(self, other: Span) -> Span {
        Span {
            start: self.start.min(other.start),
            end: self.end.max(other.end),
        }
    }
}

impl std::fmt::Display for Span {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}..{}", self.start, self.end)
    }
}

#[cfg(test)]
mod types_tests {
    use crate::types::*;

    #[test]
    fn type_definition_display() {
        assert_eq!(TypeDefinition::Text.to_string(), "TEXT");
        assert_eq!(TypeDefinition::Int.to_string(), "INT");
        assert_eq!(TypeDefinition::Float.to_string(), "FLOAT");
        assert_eq!(TypeDefinition::Bool.to_string(), "BOOL");
        assert_eq!(TypeDefinition::Uuid.to_string(), "UUID");
        assert_eq!(TypeDefinition::Date.to_string(), "DATE");
        assert_eq!(TypeDefinition::DateTime.to_string(), "DATETIME");
        assert_eq!(TypeDefinition::Duration.to_string(), "DURATION");
        assert_eq!(TypeDefinition::Blob.to_string(), "BLOB");
        assert_eq!(TypeDefinition::Json.to_string(), "JSON");
    }

    #[test]
    fn type_definition_enum_display() {
        let e = TypeDefinition::Enum(vec!["low".into(), "medium".into(), "high".into()]);
        assert_eq!(e.to_string(), "ENUM(low, medium, high)");
    }

    #[test]
    fn type_definition_ref_display() {
        let r = TypeDefinition::Ref("Agent".into());
        assert_eq!(r.to_string(), "REF(Agent)");
    }

    #[test]
    fn type_definition_money_display() {
        let m = TypeDefinition::Money("USD".into());
        assert_eq!(m.to_string(), "MONEY(USD)");
    }

    #[test]
    fn type_definition_nested_display() {
        let l = TypeDefinition::List(Box::new(TypeDefinition::Text));
        assert_eq!(l.to_string(), "LIST(TEXT)");

        let s = TypeDefinition::Set(Box::new(TypeDefinition::Int));
        assert_eq!(s.to_string(), "SET(INT)");

        let m = TypeDefinition::Map(
            Box::new(TypeDefinition::Text),
            Box::new(TypeDefinition::Int),
        );
        assert_eq!(m.to_string(), "MAP(TEXT, INT)");
    }

    #[test]
    fn type_definition_clone_eq() {
        let t1 = TypeDefinition::Enum(vec!["a".into(), "b".into()]);
        let t2 = t1.clone();
        assert_eq!(t1, t2);

        let t3 = TypeDefinition::Text;
        assert_ne!(t1, t3);
    }

    #[test]
    fn type_definition_serde() {
        let t = TypeDefinition::List(Box::new(TypeDefinition::Ref("Machine".into())));
        let json = serde_json::to_string(&t).unwrap();
        let t2: TypeDefinition = serde_json::from_str(&json).unwrap();
        assert_eq!(t, t2);
    }

    #[test]
    fn constraint_display() {
        assert_eq!(Constraint::Required.to_string(), "REQUIRED");
        assert_eq!(Constraint::Optional.to_string(), "OPTIONAL");
        assert_eq!(Constraint::Max(200).to_string(), "MAX(200)");
        assert_eq!(Constraint::Min(1).to_string(), "MIN(1)");
        assert_eq!(Constraint::Range(1, 5).to_string(), "RANGE(1, 5)");
        assert_eq!(Constraint::Unique.to_string(), "UNIQUE");
        assert_eq!(
            Constraint::Pattern("^[A-Z]+$".into()).to_string(),
            "PATTERN(^[A-Z]+$)"
        );
    }

    #[test]
    fn default_value_display_all_variants() {
        assert_eq!(DefaultValue::String("hello".into()).to_string(), "\"hello\"");
        assert_eq!(DefaultValue::Int(42).to_string(), "42");
        assert_eq!(DefaultValue::Float(3.14).to_string(), "3.14");
        assert_eq!(DefaultValue::Bool(true).to_string(), "true");
        assert_eq!(DefaultValue::EmptySet.to_string(), "{}");
        assert_eq!(DefaultValue::EmptyList.to_string(), "[]");
        assert_eq!(DefaultValue::EmptyMap.to_string(), "{}");
        assert_eq!(DefaultValue::Null.to_string(), "NULL");
    }

    #[test]
    fn data_field_definition_no_constraints() {
        let field = DataFieldDefinition {
            name: "name".into(),
            field_type: TypeDefinition::Text,
            constraints: vec![],
        };
        assert_eq!(field.to_string(), "name : TEXT");
    }

    #[test]
    fn data_field_definition_multiple_constraints() {
        let field = DataFieldDefinition {
            name: "score".into(),
            field_type: TypeDefinition::Int,
            constraints: vec![
                Constraint::Required,
                Constraint::Min(0),
                Constraint::Max(100),
            ],
        };
        assert_eq!(
            field.to_string(),
            "score : INT -> REQUIRED, MIN(0), MAX(100)"
