        }
    }
}

use chrono::{DateTime, NaiveDate, Utc};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fmt;
use std::time::Duration as StdDuration;

/// Runtime values in SMQL. Used for instance data, expression evaluation, and query results.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum Value {
    Text(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Uuid(uuid::Uuid),
    Date(NaiveDate),
    DateTime(DateTime<Utc>),
    Duration(SmqlDuration),
    List(Vec<Value>),
    Set(Vec<Value>),
    Map(BTreeMap<String, Value>),
    Ref(String, String), // (machine_name, instance_id)
    Money(i64, String),  // (amount_in_minor_units, currency)
    Blob(Vec<u8>),
    Json(serde_json::Value),
    Null,
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Value::Text(s) => write!(f, "\"{}\"", s),
            Value::Int(v) => write!(f, "{}", v),
            Value::Float(v) => write!(f, "{}", v),
            Value::Bool(v) => write!(f, "{}", v),
            Value::Uuid(v) => write!(f, "{}", v),
            Value::Date(v) => write!(f, "{}", v),
            Value::DateTime(v) => write!(f, "{}", v.to_rfc3339()),
            Value::Duration(d) => write!(f, "{}", d),
            Value::List(items) => {
                let strs: Vec<String> = items.iter().map(|v| v.to_string()).collect();
                write!(f, "[{}]", strs.join(", "))
            }
            Value::Set(items) => {
                let strs: Vec<String> = items.iter().map(|v| v.to_string()).collect();
                write!(f, "{{{}}}", strs.join(", "))
            }
            Value::Map(entries) => {
                let strs: Vec<String> = entries
                    .iter()
                    .map(|(k, v)| format!("{}: {}", k, v))
                    .collect();
                write!(f, "{{{}}}", strs.join(", "))
            }
            Value::Ref(machine, id) => write!(f, "{}#{}", machine, id),
            Value::Money(amount, currency) => {
                let major = amount / 100;
                let minor = (amount % 100).abs();
                write!(f, "{}.{:02} {}", major, minor, currency)
            }
            Value::Blob(data) => write!(f, "<blob {} bytes>", data.len()),
            Value::Json(v) => write!(f, "{}", v),
            Value::Null => write!(f, "NULL"),
        }
    }
}

/// SMQL duration type — represents durations like 24h, 7d, 30m.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SmqlDuration {
    pub seconds: u64,
}

impl SmqlDuration {
    pub fn from_seconds(s: u64) -> Self {
        Self { seconds: s }
    }

    pub fn from_minutes(m: u64) -> Self {
        Self { seconds: m * 60 }
    }

    pub fn from_hours(h: u64) -> Self {
        Self { seconds: h * 3600 }
    }

    pub fn from_days(d: u64) -> Self {
        Self { seconds: d * 86400 }
    }

    pub fn to_std(&self) -> StdDuration {
        StdDuration::from_secs(self.seconds)
    }
}

impl fmt::Display for SmqlDuration {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let s = self.seconds;
        if s == 0 {
            return write!(f, "0s");
        }
        let days = s / 86400;
        let hours = (s % 86400) / 3600;
        let minutes = (s % 3600) / 60;
        let secs = s % 60;

        let mut parts = Vec::new();
        if days > 0 {
            parts.push(format!("{}d", days));
        }
        if hours > 0 {
            parts.push(format!("{}h", hours));
        }
        if minutes > 0 {
            parts.push(format!("{}m", minutes));
        }
        if secs > 0 {
            parts.push(format!("{}s", secs));
        }
        write!(f, "{}", parts.join(""))
    }
}

impl PartialOrd for SmqlDuration {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for SmqlDuration {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.seconds.cmp(&other.seconds)
    }
}

// SMQL Catalog — Machine definitions, schema registry

mod validation;

#[cfg(test)]
mod tests;

use dashmap::DashMap;
use serde::{Deserialize, Serialize};
use smql_ast::machine::MachineDefinition;
use smql_ast::{SmqlError, SmqlResult};
use std::sync::Arc;

pub use validation::{validate_machine, ValidationWarning};

/// In-memory registry of machine definitions.
/// Thread-safe via DashMap for concurrent access.
#[derive(Clone)]
pub struct MachineCatalog {
    machines: Arc<DashMap<String, MachineEntry>>,
}

/// A versioned machine entry in the catalog.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MachineEntry {
    pub definition: MachineDefinition,
    pub version: u64,
    pub history: Vec<MachineDefinition>,
}

impl MachineCatalog {
    pub fn new() -> Self {
        Self {
            machines: Arc::new(DashMap::new()),
        }
    }

    /// Register a new machine definition.
    /// Validates the definition before storing it.
    /// Returns any warnings from validation.
    pub fn register(&self, definition: MachineDefinition) -> SmqlResult<Vec<ValidationWarning>> {
        let warnings = validate_machine(&definition, self)?;

        let name = definition.name.clone();
        let version = definition.version;
        let entry = MachineEntry {
            definition,
            version,
            history: Vec::new(),
        };

        self.machines.insert(name, entry);
        Ok(warnings)
    }

    /// Register without validation (for bootstrapping / testing).
    pub fn register_unchecked(&self, definition: MachineDefinition) {
        let name = definition.name.clone();
        let version = definition.version;
        self.machines.insert(
            name,
            MachineEntry {
                definition,
                version,
                history: Vec::new(),
            },
        );
    }

    /// Retrieve a machine definition by name.
    pub fn get(&self, name: &str) -> SmqlResult<MachineDefinition> {
        self.machines
            .get(name)
            .map(|entry| entry.definition.clone())
            .ok_or_else(|| SmqlError::not_found("Machine", name))
    }

    /// Check if a machine exists.
    pub fn contains(&self, name: &str) -> bool {
        self.machines.contains_key(name)
    }

    /// Unregister a machine.
    pub fn unregister(&self, name: &str) -> SmqlResult<MachineDefinition> {
        self.machines
            .remove(name)
            .map(|(_, entry)| entry.definition)
            .ok_or_else(|| SmqlError::not_found("Machine", name))
    }

    /// List all machine names.
    pub fn list(&self) -> Vec<String> {
        self.machines.iter().map(|e| e.key().clone()).collect()
    }

    /// Get the current version of a machine.
    pub fn version(&self, name: &str) -> SmqlResult<u64> {
        self.machines
            .get(name)
            .map(|entry| entry.version)
            .ok_or_else(|| SmqlError::not_found("Machine", name))
    }

    /// Update a machine definition (increments version, preserves history).
    pub fn update(&self, definition: MachineDefinition) -> SmqlResult<Vec<ValidationWarning>> {
        let name = definition.name.clone();

        let warnings = validate_machine(&definition, self)?;

        self.machines.alter(&name, |_, mut entry| {
            entry.history.push(entry.definition.clone());
            entry.version += 1;
            entry.definition = definition.clone();
            entry
        });

        if !self.machines.contains_key(&name) {
            return Err(SmqlError::not_found("Machine", &name));
        }

        Ok(warnings)
    }

    /// Serialize the catalog to JSON for persistence.
    pub fn serialize(&self) -> SmqlResult<String> {
        let entries: Vec<MachineEntry> = self.machines.iter().map(|e| e.value().clone()).collect();
        serde_json::to_string_pretty(&entries).map_err(|e| SmqlError::internal(e.to_string()))
    }

    /// Deserialize and load a catalog from JSON.
    pub fn deserialize(json: &str) -> SmqlResult<Self> {
        let entries: Vec<MachineEntry> =
            serde_json::from_str(json).map_err(|e| SmqlError::internal(e.to_string()))?;
        let catalog = Self::new();
        for entry in entries {
            catalog
                .machines
                .insert(entry.definition.name.clone(), entry);
        }
        Ok(catalog)
    }
}

impl Default for MachineCatalog {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod catalog_tests {
    use crate::MachineCatalog;
    use smql_ast::machine::*;

    fn simple_machine(name: &str) -> MachineDefinition {
        let mut m = MachineDefinition::new(name.into(), "init".into());
        m.states = vec![
            StateDefinition::new("init".into()),
            StateDefinition::new("done".into()),
        ];
        m.terminal_states = vec!["done".into()];
        m.transitions = vec![TransitionDefinition::new(
            TransitionSource::State("init".into()),
            "done".into(),
        )];
        m
    }

    #[test]
    fn register_and_get() {
        let catalog = MachineCatalog::new();
        let m = simple_machine("TestMachine");
        catalog.register(m.clone()).unwrap();

        let retrieved = catalog.get("TestMachine").unwrap();
        assert_eq!(retrieved.name, "TestMachine");
        assert_eq!(retrieved.states.len(), 2);
    }

    #[test]
    fn get_nonexistent() {
        let catalog = MachineCatalog::new();
        let result = catalog.get("NonExistent");
        assert!(result.is_err());
    }

    #[test]
    fn contains() {
        let catalog = MachineCatalog::new();
        let m = simple_machine("Exists");
        catalog.register(m).unwrap();

        assert!(catalog.contains("Exists"));
        assert!(!catalog.contains("Missing"));
    }

    #[test]
    fn unregister() {
        let catalog = MachineCatalog::new();
        let m = simple_machine("ToRemove");
        catalog.register(m).unwrap();

        let removed = catalog.unregister("ToRemove").unwrap();
        assert_eq!(removed.name, "ToRemove");
        assert!(!catalog.contains("ToRemove"));
    }

    #[test]
    fn unregister_nonexistent() {
        let catalog = MachineCatalog::new();
        let result = catalog.unregister("Nope");
        assert!(result.is_err());
    }

    #[test]
    fn list_machines() {
        let catalog = MachineCatalog::new();
        catalog.register(simple_machine("A")).unwrap();
        catalog.register(simple_machine("B")).unwrap();

        let mut names = catalog.list();
        names.sort();
        assert_eq!(names, vec!["A", "B"]);
    }

    #[test]
    fn version() {
        let catalog = MachineCatalog::new();
        let m = simple_machine("Versioned");
        catalog.register(m.clone()).unwrap();
        assert_eq!(catalog.version("Versioned").unwrap(), 1);
    }

    #[test]
    fn update_increments_version() {
        let catalog = MachineCatalog::new();
        let m = simple_machine("Updatable");
        catalog.register(m.clone()).unwrap();

        let mut updated = m.clone();
        updated.states.push(StateDefinition::new("middle".into()));
        updated.transitions.push(TransitionDefinition::new(
            TransitionSource::State("init".into()),
            "middle".into(),
        ));
        catalog.update(updated).unwrap();

        assert_eq!(catalog.version("Updatable").unwrap(), 2);
        let def = catalog.get("Updatable").unwrap();
        assert_eq!(def.states.len(), 3);
    }

    #[test]
    fn serialize_deserialize() {
        let catalog = MachineCatalog::new();
        catalog.register(simple_machine("Machine1")).unwrap();
        catalog.register(simple_machine("Machine2")).unwrap();

        let json = catalog.serialize().unwrap();
        let restored = MachineCatalog::deserialize(&json).unwrap();

        assert!(restored.contains("Machine1"));
        assert!(restored.contains("Machine2"));
    }
}

