use smql_ast::machine::{MachineDefinition, TransitionSource};
use smql_ast::{SmqlError, SmqlResult};
use std::collections::{HashSet, VecDeque};

use crate::MachineCatalog;

/// A non-fatal warning from validation.
#[derive(Debug, Clone)]
pub struct ValidationWarning {
    pub message: String,
}

/// Validate a machine definition, returning errors for invalid definitions
/// and warnings for suspicious but legal definitions.
pub fn validate_machine(
    machine: &MachineDefinition,
    catalog: &MachineCatalog,
) -> SmqlResult<Vec<ValidationWarning>> {
    let mut warnings = Vec::new();
    let state_names: HashSet<&str> = machine.states.iter().map(|s| s.name.as_str()).collect();

    // 3.2.1: Initial state must be in STATES set
    if !machine.initial_state.is_empty() && !state_names.contains(machine.initial_state.as_str()) {
        return Err(SmqlError::ValidationError {
            message: format!(
                "Initial state '{}' is not in the STATES set",
                machine.initial_state
            ),
            field: Some("initial_state".into()),
            hint: Some(format!(
                "Add '{}' to STATES or choose one of: {}",
                machine.initial_state,
                state_names_display(&state_names)
            )),
        });
    }

    // 3.2.2: Terminal states must be in STATES set
    for ts in &machine.terminal_states {
        if !state_names.contains(ts.as_str()) {
            return Err(SmqlError::ValidationError {
                message: format!("Terminal state '{}' is not in the STATES set", ts),
                field: Some("terminal_states".into()),
                hint: Some(format!(
                    "Add '{}' to STATES or choose from: {}",
                    ts,
                    state_names_display(&state_names)
                )),
            });
        }
    }

    // 3.2.3: All transition sources/targets must be in STATES set
    for transition in &machine.transitions {
        match &transition.from {
            TransitionSource::State(s) => {
                if !state_names.contains(s.as_str()) {
                    return Err(SmqlError::ValidationError {
                        message: format!(
                            "Transition source state '{}' is not in the STATES set",
                            s
                        ),
                        field: Some("transitions".into()),
                        hint: Some(format!("Add '{}' to STATES", s)),
                    });
                }
            }
            TransitionSource::Any { except } => {
                for ex in except {
                    if !state_names.contains(ex.as_str()) {
                        return Err(SmqlError::ValidationError {
                            message: format!("EXCEPT FROM state '{}' is not in the STATES set", ex),
                            field: Some("transitions".into()),
                            hint: Some(format!("Add '{}' to STATES", ex)),
                        });
                    }
                }
            }
            TransitionSource::Group(_) => {
                // Groups are resolved at runtime
            }
        }

        if !state_names.contains(transition.to.as_str()) {
            return Err(SmqlError::ValidationError {
                message: format!(
                    "Transition target state '{}' is not in the STATES set",
                    transition.to
                ),
                field: Some("transitions".into()),
                hint: Some(format!("Add '{}' to STATES", transition.to)),
            });
        }

        // 3.2.10: Timeout target states must be valid
        if let Some(timeout) = &transition.timeout {
            if !state_names.contains(timeout.target_state.as_str()) {
                return Err(SmqlError::ValidationError {
                    message: format!(
                        "Timeout target state '{}' is not in the STATES set",
                        timeout.target_state
                    ),
                    field: Some("transitions".into()),
                    hint: Some(format!("Add '{}' to STATES", timeout.target_state)),
                });
            }
        }
    }

    // 3.2.4: No transitions FROM terminal states (warn)
    let terminal_set: HashSet<&str> = machine.terminal_states.iter().map(|s| s.as_str()).collect();
    for transition in &machine.transitions {
        if let TransitionSource::State(s) = &transition.from {
            if terminal_set.contains(s.as_str()) {
                warnings.push(ValidationWarning {
                    message: format!(
                        "Transition from terminal state '{}' to '{}' — terminal states typically have no outgoing transitions",
                        s, transition.to
                    ),
                });
            }
        }
    }

    // 3.2.5: All states must be reachable from initial state (warn on unreachable)
    if !machine.initial_state.is_empty() {
        let reachable = compute_reachable_states(machine);
        for state in &machine.states {
            if !reachable.contains(state.name.as_str()) {
                warnings.push(ValidationWarning {
                    message: format!(
                        "State '{}' is unreachable from the initial state '{}'",
                        state.name, machine.initial_state
                    ),
                });
            }
        }
    }

    // 3.2.6: Detect dead-end states (non-terminal states with no outgoing transitions)
    let states_with_outgoing = compute_states_with_outgoing(machine, &state_names);
    // Also account for ANY wildcards which provide outgoing for all states
    let has_any_wildcard = machine
        .transitions
        .iter()
        .any(|t| matches!(&t.from, TransitionSource::Any { .. }));

    for state in &machine.states {
        if !terminal_set.contains(state.name.as_str())
            && !states_with_outgoing.contains(state.name.as_str())
            && !has_any_wildcard
        {
            warnings.push(ValidationWarning {
                message: format!(
                    "State '{}' is a dead-end: it is not terminal and has no outgoing transitions",
                    state.name
                ),
            });
        }
    }

    // 3.2.8: REF targets must reference registered machines
    for field in &machine.data {
        if let smql_ast::types::TypeDefinition::Ref(target) = &field.field_type {
            if !catalog.contains(target) && target != &machine.name {
                warnings.push(ValidationWarning {
                    message: format!(
                        "Data field '{}' references machine '{}' which is not registered (may be registered later)",
                        field.name, target
                    ),
                });
            }
        }
    }

    // 3.2.9: CHILDREN machines must exist in catalog
    for child in &machine.children {
        if !catalog.contains(&child.machine) && child.machine != machine.name {
            warnings.push(ValidationWarning {
                message: format!(
                    "Child '{}' references machine '{}' which is not registered (may be registered later)",
                    child.name, child.machine
                ),
            });
        }
    }

    Ok(warnings)
}

/// Compute all states reachable from the initial state via BFS.
fn compute_reachable_states(machine: &MachineDefinition) -> HashSet<&str> {
    let mut reachable = HashSet::new();
    let mut queue = VecDeque::new();
    reachable.insert(machine.initial_state.as_str());
    queue.push_back(machine.initial_state.as_str());

    while let Some(current) = queue.pop_front() {
        for transition in &machine.transitions {
            let matches = match &transition.from {
                TransitionSource::State(s) => s == current,
                TransitionSource::Any { except } => !except.iter().any(|e| e == current),
                TransitionSource::Group(_) => false,
            };

            if matches && !reachable.contains(transition.to.as_str()) {
                reachable.insert(transition.to.as_str());
                queue.push_back(transition.to.as_str());
            }
        }
    }

    reachable
}

/// Compute set of states that have at least one explicit outgoing transition.
fn compute_states_with_outgoing<'a>(
    machine: &'a MachineDefinition,
    state_names: &HashSet<&'a str>,
) -> HashSet<&'a str> {
    let mut result = HashSet::new();
    for transition in &machine.transitions {
        match &transition.from {
            TransitionSource::State(s) => {
                if let Some(&name) = state_names.get(s.as_str()) {
                    result.insert(name);
                }
            }
            TransitionSource::Any { except } => {
                // ANY gives outgoing to all states except those in except list
                for &state in state_names {
                    if !except.iter().any(|e| e == state) {
                        result.insert(state);
                    }
                }
            }
            TransitionSource::Group(_) => {}
        }
    }
    result
}

fn state_names_display(names: &HashSet<&str>) -> String {
    let mut sorted: Vec<&str> = names.iter().copied().collect();
    sorted.sort();
    sorted.join(", ")
}

use clap::{Parser, Subcommand};
use smql_storage::Storage;
use std::sync::Arc;

#[derive(Parser)]
#[command(name = "smql")]
#[command(about = "SMQL Engine — State Machine Query Language")]
#[command(version = "0.1.0")]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand)]
enum Commands {
    /// Start the SMQL HTTP server
    Serve {
        /// Address to bind to
        #[arg(short, long, default_value = "127.0.0.1:4200")]
        bind: String,

        /// Storage backend: "memory" or a filesystem path for RocksDB
        #[arg(short, long, default_value = "memory")]
        storage: String,
    },

    /// Start an interactive REPL
    Repl {
        /// Storage backend: "memory" or a filesystem path for RocksDB
        #[arg(short, long, default_value = "memory")]
        storage: String,
    },

    /// Execute a single SMQL statement from a string
    Exec {
        /// The SMQL statement to execute
        statement: String,

        /// Storage backend: "memory" or a filesystem path for RocksDB
        #[arg(short, long, default_value = "memory")]
        storage: String,
    },

    /// Execute SMQL from a file
    Run {
        /// Path to the .smql file
        file: String,

        /// Storage backend: "memory" or a filesystem path for RocksDB
        #[arg(short, long, default_value = "memory")]
        storage: String,
    },

    /// Generate typed Rust code from .smql machine definitions
    Codegen {
        /// Input .smql files or directory
        #[arg(short, long)]
        input: Vec<String>,

        /// Output directory for generated code
        #[arg(short, long, default_value = "src/generated")]
        output: String,

        /// Target language (only "rust" supported)
        #[arg(short, long, default_value = "rust")]
        lang: String,
    },
}

fn create_storage(arg: &str) -> Arc<dyn Storage> {
    if arg == "memory" {
        return Arc::new(smql_storage::MemoryStorage::new());
    }

    #[cfg(feature = "rocksdb")]
    {
        match smql_storage::RocksDBStorage::open(arg) {
            Ok(s) => Arc::new(s),
            Err(e) => {
                eprintln!("Failed to open RocksDB at '{}': {}", arg, e);
                std::process::exit(1);
            }
        }
    }

    #[cfg(not(feature = "rocksdb"))]
    {
        eprintln!(
            "RocksDB storage requested ('{}') but the 'rocksdb' feature is not enabled.\n\
             Rebuild with: cargo build --features rocksdb",
            arg
        );
        std::process::exit(1);
    }
}

#[tokio::main]
async fn main() {
    let cli = Cli::parse();

    match cli.command {
        Some(Commands::Serve { bind, storage }) => {
            tracing_subscriber::fmt()
                .json()
                .with_target(true)
                .with_env_filter(
                    tracing_subscriber::EnvFilter::try_from_default_env()
                        .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
                )
                .init();
            let st = create_storage(&storage);
            let server = smql_server::SmqlServer::with_storage(st);
            if let Err(e) = server.serve(&bind).await {
                eprintln!("Server error: {}", e);
                std::process::exit(1);
            }
        }

        Some(Commands::Exec { statement, storage }) => {
            let st = create_storage(&storage);
            run_statements(&statement, st).await;
        }

        Some(Commands::Run { file, storage }) => {
            let st = create_storage(&storage);
            match std::fs::read_to_string(&file) {
                Ok(content) => {
                    run_statements(&content, st).await;
                }
                Err(e) => {
                    eprintln!("Cannot read file {}: {}", file, e);
                    std::process::exit(1);
                }
            }
        }

        Some(Commands::Codegen {
            input,
            output,
            lang,
        }) => {
            if lang != "rust" {
                eprintln!("Unsupported language '{}'. Only 'rust' is supported.", lang);
                std::process::exit(1);
            }

            // Collect .smql files from input paths
            let mut smql_files = Vec::new();
            for path in &input {
                let meta = match std::fs::metadata(path) {
                    Ok(m) => m,
                    Err(e) => {
                        eprintln!("Cannot access '{}': {}", path, e);
                        std::process::exit(1);
                    }
                };
                if meta.is_dir() {
                    match std::fs::read_dir(path) {
                        Ok(entries) => {
                            for entry in entries.flatten() {
                                let p = entry.path();
                                if p.extension().is_some_and(|ext| ext == "smql") {
                                    smql_files.push(p.to_string_lossy().to_string());
                                }
                            }
                        }
                        Err(e) => {
                            eprintln!("Cannot read directory '{}': {}", path, e);
                            std::process::exit(1);
                        }
                    }
                } else {
                    smql_files.push(path.clone());
                }
            }

            if smql_files.is_empty() {
                eprintln!("No .smql files found in input paths");
                std::process::exit(1);
            }

            let file_refs: Vec<&str> = smql_files.iter().map(|s| s.as_str()).collect();
            let generator = match smql_codegen::CodeGenerator::from_files(&file_refs) {
                Ok(g) => g,
                Err(e) => {
                    eprintln!("Codegen error: {}", e);
                    std::process::exit(1);
                }
            };

            // Generate output
            if let Err(e) = std::fs::create_dir_all(&output) {
                eprintln!("Cannot create output directory '{}': {}", output, e);
                std::process::exit(1);
            }

            let files = generator.generate_rust();
            for file in &files {
                let full_path = format!("{}/{}", output, file.path);
                if let Err(e) = std::fs::write(&full_path, &file.content) {
                    eprintln!("Cannot write '{}': {}", full_path, e);
                    std::process::exit(1);
                }
                println!("Generated: {}", full_path);
            }

            // Also write a mod.rs
            let mod_content: String = files
                .iter()
                .map(|f| {
                    let mod_name = f.path.trim_end_matches(".rs");
                    format!("pub mod {};", mod_name)
                })
                .collect::<Vec<_>>()
                .join("\n");
            let mod_path = format!("{}/mod.rs", output);
            if let Err(e) = std::fs::write(
                &mod_path,
                format!("// Auto-generated by smql-codegen\n{}\n", mod_content),
            ) {
                eprintln!("Cannot write '{}': {}", mod_path, e);
                std::process::exit(1);
            }
            println!("Generated: {}", mod_path);
            println!("Done. {} file(s) generated.", files.len() + 1);
        }

        Some(Commands::Repl { storage }) => {
            let st = create_storage(&storage);
            smql_cli::repl::run_repl_with_storage(st).await;
        }

        None => {
            smql_cli::repl::run_repl().await;
        }
    }
}

/// Resolve $N references (1-indexed) in instance_id fields to spawned IDs.
fn resolve_ref(id: &str, spawned_ids: &[String]) -> String {
    if let Some(num_str) = id.strip_prefix('$') {
        if let Ok(n) = num_str.parse::<usize>() {
            if n >= 1 && n <= spawned_ids.len() {
                return spawned_ids[n - 1].clone();
            }
            eprintln!(
                "Warning: ${} not yet spawned (only {} spawns so far)",
                n,
                spawned_ids.len()
            );
        }
    }
    id.to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn resolve_ref_dollar_1() {
        let spawned = vec!["ABC123".to_string(), "DEF456".to_string()];
        assert_eq!(resolve_ref("$1", &spawned), "ABC123");
        assert_eq!(resolve_ref("$2", &spawned), "DEF456");
    }

    #[test]
    fn resolve_ref_no_dollar() {
        let spawned = vec!["ABC".to_string()];
        assert_eq!(resolve_ref("plain_id", &spawned), "plain_id");
    }

    #[test]
    fn resolve_ref_out_of_range() {
        let spawned = vec!["ABC".to_string()];
        // $5 is out of range — should return "$5" as-is (with warning printed)
        assert_eq!(resolve_ref("$5", &spawned), "$5");
    }

    #[test]
    fn resolve_ref_zero_index() {
        let spawned = vec!["ABC".to_string()];
        // $0 is not valid (1-indexed) — n >= 1 check fails
        assert_eq!(resolve_ref("$0", &spawned), "$0");
    }

    #[test]
    fn resolve_ref_non_numeric() {
        let spawned = vec!["ABC".to_string()];
        // $abc is not parseable as usize
        assert_eq!(resolve_ref("$abc", &spawned), "$abc");
    }

    #[test]
    fn resolve_ref_empty_spawned() {
        let spawned: Vec<String> = vec![];
        assert_eq!(resolve_ref("$1", &spawned), "$1");
    }

    #[test]
    fn create_storage_memory() {
        let storage = create_storage("memory");
        // Just verify it returns successfully
        assert!(std::sync::Arc::strong_count(&storage) >= 1);
    }
}

async fn run_statements(input: &str, storage: Arc<dyn Storage>) {
    use smql_ast::command::{Command, Statement};

    let catalog = std::sync::Arc::new(smql_catalog::MachineCatalog::new());
    let engine = smql_engine_core::Engine::new(catalog, storage);
    engine.wire_callback();

    let stmts = match smql_parser::parse(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("Parse error: {}", e);
            std::process::exit(1);
        }
    };

    let mut spawned_ids: Vec<String> = Vec::new();

    for stmt in stmts {
        match stmt {
            Statement::Command(cmd) => match cmd {
                Command::Spawn(spawn_cmd) => match engine.spawn(&spawn_cmd).await {
                    Ok(result) => {
                        let id = result.instance.id.to_string();
                        println!(
                            "Spawned {} instance: {} (state: {})",
                            result.instance.machine, id, result.instance.state
                        );
                        spawned_ids.push(id);
                    }
                    Err(e) => eprintln!("Error: {}", e),
                },
                Command::Transition(mut t_cmd) => {
                    t_cmd.instance_id = resolve_ref(&t_cmd.instance_id, &spawned_ids);
                    smql_cli::repl::execute_command_public(Command::Transition(t_cmd), &engine)
                        .await;
                }
                Command::TryTransition(mut t_cmd) => {
                    t_cmd.instance_id = resolve_ref(&t_cmd.instance_id, &spawned_ids);
                    smql_cli::repl::execute_command_public(Command::TryTransition(t_cmd), &engine)
                        .await;
                }
                other => {
                    smql_cli::repl::execute_command_public(other, &engine).await;
                }
            },
            Statement::Query(mut query) => {
                // Resolve $N in instance_id fields for GET and TRAIL queries
                match &mut query {
                    smql_ast::query::Query::Get(ref mut g) => {
                        g.instance_id = resolve_ref(&g.instance_id, &spawned_ids);
                    }
                    smql_ast::query::Query::Trail(ref mut t) => {
                        t.instance_id = resolve_ref(&t.instance_id, &spawned_ids);
                    }
                    _ => {}
                }
                smql_cli::repl::execute_query_public(query, &engine).await;
            }
        }
    }
}

use rustyline::error::ReadlineError;
use rustyline::DefaultEditor;
use smql_ast::command::{Command, Statement};
use smql_catalog::MachineCatalog;
use smql_engine_core::engine::Engine;
use smql_engine_core::query::QueryResult;
use smql_storage::{MemoryStorage, Storage};
use std::sync::Arc;

/// Run the SMQL REPL with a custom storage backend.
pub async fn run_repl_with_storage(storage: Arc<dyn Storage>) {
    let catalog = Arc::new(MachineCatalog::new());
    let engine = Engine::new(catalog, storage);
    engine.wire_callback();
    run_repl_inner(engine).await;
}

/// Run the SMQL REPL (Read-Eval-Print Loop).
pub async fn run_repl() {
    let catalog = Arc::new(MachineCatalog::new());
    let storage = Arc::new(MemoryStorage::new());
    let engine = Engine::new(catalog, storage);
    engine.wire_callback();
    run_repl_inner(engine).await;
}

async fn run_repl_inner(engine: Engine) {
    println!("SMQL Engine v0.1.0 — Interactive REPL");
    println!("Type SMQL statements or .help for commands. Press Ctrl+D to exit.\n");

    let mut rl = DefaultEditor::new().expect("Failed to create editor");
    let mut multiline_buf = String::new();

    loop {
        let prompt = if multiline_buf.is_empty() {
            "smql> "
        } else {
            "  ... "
        };

        match rl.readline(prompt) {
            Ok(line) => {
                let trimmed = line.trim();

                // Dot commands
                if multiline_buf.is_empty() && trimmed.starts_with('.') {
                    handle_dot_command(trimmed, &engine);
                    continue;
                }

                // Empty line
                if trimmed.is_empty() {
                    if !multiline_buf.is_empty() {
                        // Execute accumulated multiline input
                        let input = std::mem::take(&mut multiline_buf);
                        let _ = rl.add_history_entry(&input);
                        execute_input(&input, &engine).await;
                    }
                    continue;
                }

                // Accumulate multiline input
                if !multiline_buf.is_empty() {
                    multiline_buf.push(' ');
                }
                multiline_buf.push_str(trimmed);

                // Check if the statement looks complete (ends with a semicolon or is a full statement)
                if trimmed.ends_with(';') || is_complete_statement(&multiline_buf) {
                    let input = std::mem::take(&mut multiline_buf);
                    let input = input.trim_end_matches(';').to_string();
                    let _ = rl.add_history_entry(&input);
                    execute_input(&input, &engine).await;
                }
            }
            Err(ReadlineError::Interrupted) => {
                multiline_buf.clear();
                println!("^C");
            }
            Err(ReadlineError::Eof) => {
                println!("Bye!");
                break;
            }
            Err(err) => {
                eprintln!("Error: {:?}", err);
                break;
            }
        }
    }
}

fn handle_dot_command(cmd: &str, engine: &Engine) {
    match cmd {
        ".help" | ".h" => {
            println!("Available commands:");
            println!("  .help          Show this help message");
            println!("  .machines      List registered machines");
            println!("  .quit          Exit the REPL");
            println!();
            println!("SMQL statements:");
            println!("  DEFINE MACHINE name {{ ... }}");
            println!("  SPAWN Machine {{ field: value }}");
            println!("  TRANSITION Machine instance_id TO state");
            println!("  GET Machine instance_id");
            println!("  FIND Machine WHERE condition");
            println!("  TRAIL OF instance_id");
            println!("  AGGREGATE Machine MEASURE COUNT()");
        }
        ".machines" | ".m" => {
            let names = engine.catalog.list();
            if names.is_empty() {
                println!("No machines registered.");
            } else {
                println!("Registered machines:");
                for name in names {
                    println!("  - {}", name);
                }
            }
        }
        ".quit" | ".q" | ".exit" => {
            println!("Bye!");
            std::process::exit(0);
        }
        _ => {
            eprintln!("Unknown command: {}", cmd);
        }
    }
}

fn is_complete_statement(input: &str) -> bool {
    // A simple heuristic: check if braces and parens are balanced
    let brace_opens = input.chars().filter(|c| *c == '{').count();
    let brace_closes = input.chars().filter(|c| *c == '}').count();
    let paren_opens = input.chars().filter(|c| *c == '(').count();
    let paren_closes = input.chars().filter(|c| *c == ')').count();
    brace_opens == brace_closes && paren_opens == paren_closes
}

async fn execute_input(input: &str, engine: &Engine) {
    let statements = match smql_parser::parse(input) {
        Ok(stmts) => stmts,
        Err(e) => {
            eprintln!("Parse error: {}", e);
            return;
        }
    };

    for stmt in statements {
        match stmt {
            Statement::Command(cmd) => execute_command(cmd, engine).await,
            Statement::Query(query) => execute_query(query, engine).await,
        }
    }
}

/// Execute a command and print results. Public for use from CLI subcommands.
pub async fn execute_command_public(cmd: Command, engine: &Engine) {
    execute_command(cmd, engine).await;
}

/// Execute a query and print results. Public for use from CLI subcommands.
pub async fn execute_query_public(query: smql_ast::query::Query, engine: &Engine) {
    execute_query(query, engine).await;
}

async fn execute_command(cmd: Command, engine: &Engine) {
    match cmd {
        Command::DefineMachine(def) => {
            let name = def.name.clone();
            match engine.catalog.register(def) {
                Ok(warnings) => {
                    println!("Machine '{}' defined.", name);
                    for w in warnings {
                        println!("  Warning: {}", w.message);
                    }
                }
                Err(e) => eprintln!("Error: {}", e),
            }
        }

        Command::Spawn(spawn_cmd) => match engine.spawn(&spawn_cmd).await {
            Ok(result) => {
                println!(
                    "Spawned {} instance: {} (state: {})",
                    result.instance.machine, result.instance.id, result.instance.state
                );
            }
            Err(e) => eprintln!("Error: {}", e),
        },

        Command::Transition(t_cmd) => match engine.transition(&t_cmd).await {
            Ok(result) => {
                println!(
                    "Transitioned {} -> {} (instance: {})",
                    result.from_state, result.to_state, result.instance.id
                );
            }
            Err(e) => eprintln!("Error: {}", e),
        },

        Command::TryTransition(t_cmd) => match engine.try_transition(&t_cmd).await {
            Ok(Some(result)) => {
                println!(
                    "Transitioned {} -> {} (instance: {})",
                    result.from_state, result.to_state, result.instance.id
                );
            }
            Ok(None) => {
                println!("Transition not applied (guard conditions not met).");
            }
            Err(e) => eprintln!("Error: {}", e),
        },

        Command::BatchTransition(batch_cmd) => match engine.batch_transition(&batch_cmd).await {
            Ok(result) => {
                println!(
                    "Batch transition: {} matched, {} transitioned, {} failed.",
                    result.matched, result.transitioned, result.failures.len()
                );
                for f in &result.failures {
                    println!("  FAILED {}: {}", f.instance_id, f.error);
                }
            }
            Err(e) => eprintln!("Error: {}", e),
        },

        Command::AlterMachine(alter_cmd) => match engine.execute_alter_machine(&alter_cmd).await {
            Ok(result) => {
                println!(
                    "Machine '{}' altered (v{}, {} operation(s), {} instance(s) migrated).",
                    result.machine,
                    result.new_version,
                    result.operations_applied,
                    result.instances_migrated
                );
                for w in &result.warnings {
                    println!("  Warning: {}", w);
                }
            }
            Err(e) => eprintln!("Error: {}", e),
        },
    }
}

async fn execute_query(query: smql_ast::query::Query, engine: &Engine) {
    match engine.execute_query(&query).await {
        Ok(result) => print_query_result(result),
        Err(e) => eprintln!("Query error: {}", e),
    }
}

fn print_query_result(result: QueryResult) {
    match result {
        QueryResult::Instance(inst) => {
            println!("Instance: {} ({})", inst.id, inst.machine);
            println!("  State: {}", inst.state);
            println!("  Version: {}", inst.version);
            println!("  Created: {}", inst.created_at);
            for (k, v) in &inst.data {
                println!("  {}: {}", k, v);
            }
        }

        QueryResult::Instances(insts) => {
            println!("{} instance(s) found:", insts.len());
            for inst in &insts {
                println!(
                    "  {} | state: {} | {}",
                    inst.id,
                    inst.state,
                    inst.data
                        .iter()
                        .map(|(k, v)| format!("{}={}", k, v))
                        .collect::<Vec<_>>()
                        .join(", ")
                );
            }
        }

        QueryResult::Trail(entries) => {
            println!("{} trail entries:", entries.len());
            for entry in &entries {
                println!(
                    "  [{}] {} -> {} ({})",
                    entry.sequence,
                    entry.from_state,
                    entry.to_state,
                    entry.timestamp.format("%Y-%m-%d %H:%M:%S")
                );
                if let Some(actor) = &entry.actor {
                    println!("       Actor: {}", actor);
                }
                if let Some(memo) = &entry.memo {
                    println!("       Memo: {}", memo);
                }
            }
        }

        QueryResult::Aggregate(rows) => {
            println!("{} group(s):", rows.len());
            for row in &rows {
                if !row.group_key.is_empty() {
                    let group_str = row
                        .group_key
                        .iter()
                        .map(|(k, v)| format!("{}={}", k, v))
                        .collect::<Vec<_>>()
                        .join(", ");
                    print!("  [{}]", group_str);
                } else {
                    print!("  [all]");
                }
                for (k, v) in &row.measures {
                    print!(" {}={}", k, v);
                }
                println!();
            }
        }

        QueryResult::Paths(paths) => {
            println!("{} unique path(s):", paths.len());
            for p in &paths {
                println!("  {} -> count: {}", p.path.join(" -> "), p.count);
            }
        }

        QueryResult::Funnel(funnel) => {
            println!("Funnel analysis:");
            for stage in &funnel.stages {
                println!(
                    "  {} : {} ({:.1}%)",
                    stage.state,
                    stage.count,
                    stage.conversion_rate * 100.0
                );
            }
        }

        QueryResult::ComparePaths(compare) => {
            println!(
                "Path comparison (segmented by '{}'):",
                compare.segment_by
            );
            for seg in &compare.segments {
                println!("  [{}]", seg.segment_value);
                for p in &seg.paths {
                    println!("    {} -> count: {}", p.path.join(" -> "), p.count);
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn is_complete_statement_balanced_braces() {
        assert!(is_complete_statement(
            "DEFINE MACHINE Foo { STATES { open } }"
        ));
    }

    #[test]
    fn is_complete_statement_unbalanced_braces() {
        assert!(!is_complete_statement(
            "DEFINE MACHINE Foo { STATES { open }"
        ));
    }

    #[test]
    fn is_complete_statement_balanced_parens() {
        assert!(is_complete_statement("AGGREGATE Machine MEASURE COUNT()"));
    }

    #[test]
    fn is_complete_statement_unbalanced_parens() {
        assert!(!is_complete_statement("AGGREGATE Machine MEASURE COUNT("));
    }

    #[test]
    fn is_complete_statement_no_braces_or_parens() {
        assert!(is_complete_statement("TRANSITION Machine id TO closed"));
    }

    #[test]
    fn is_complete_statement_empty_string() {
        assert!(is_complete_statement(""));
    }

    #[test]
    fn is_complete_statement_mixed_balanced() {
        assert!(is_complete_statement(
            "DEFINE MACHINE Foo { HOOKS { ON SPAWN { EMIT(\"created\") } } }"
        ));
    }

    #[test]
    fn is_complete_statement_mixed_unbalanced_brace() {
        assert!(!is_complete_statement(
            "DEFINE MACHINE Foo { HOOKS { ON SPAWN { EMIT(\"created\") }"
        ));
    }

    #[test]
    fn is_complete_statement_mixed_unbalanced_paren() {
        assert!(!is_complete_statement(
            "AGGREGATE Machine MEASURE AVG(price"
