use thiserror::Error;

#[derive(Debug, Error)]
pub enum CodegenError {
    #[error("Parse error: {0}")]
    Parse(String),

    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),

    #[error("No machines found in input")]
    NoMachines,

    #[error("Unsupported type: {0}")]
    UnsupportedType(String),
}

pub type CodegenResult<T> = Result<T, CodegenError>;

use smql_ast::machine::MachineDefinition;

use crate::error::{CodegenError, CodegenResult};
use crate::rust_gen;

/// A generated output file with path and content.
#[derive(Debug, Clone)]
pub struct GeneratedFile {
    pub path: String,
    pub content: String,
}

/// Code generator that reads .smql files and produces Rust source.
pub struct CodeGenerator {
    machines: Vec<MachineDefinition>,
}

impl CodeGenerator {
    /// Create a generator from raw SMQL source text.
    pub fn from_source(source: &str) -> CodegenResult<Self> {
        let machines =
            smql_parser::parse_machines(source).map_err(|e| CodegenError::Parse(e.to_string()))?;
        if machines.is_empty() {
            return Err(CodegenError::NoMachines);
        }
        Ok(Self { machines })
    }

    /// Create a generator from .smql files on disk.
    pub fn from_files(paths: &[&str]) -> CodegenResult<Self> {
        let mut machines = Vec::new();
        for path in paths {
            let source = std::fs::read_to_string(path)?;
            let parsed = smql_parser::parse_machines(&source)
                .map_err(|e| CodegenError::Parse(format!("{}: {}", path, e)))?;
            machines.extend(parsed);
        }
        if machines.is_empty() {
            return Err(CodegenError::NoMachines);
        }
        Ok(Self { machines })
    }

    /// Generate Rust source code. Returns one GeneratedFile per machine.
    pub fn generate_rust(&self) -> Vec<GeneratedFile> {
        self.machines
            .iter()
            .map(|def| {
                let module_name = rust_gen::to_snake_case(&def.name);
                GeneratedFile {
                    path: format!("{}.rs", module_name),
                    content: rust_gen::generate_machine_module(def),
                }
            })
            .collect()
    }

    /// Generate a single combined file with all machines as modules.
    pub fn generate_combined_rust(&self) -> String {
        let mut out = String::new();
        out.push_str("// Auto-generated by smql-codegen. Do not edit.\n\n");
        for def in &self.machines {
            out.push_str(&rust_gen::generate_machine_module(def));
            out.push('\n');
        }
        out
    }

    /// Get the parsed machine definitions.
    pub fn machines(&self) -> &[MachineDefinition] {
        &self.machines
    }
}

//! SMQL Codegen — generates typed Rust code from `.smql` machine definitions.

pub mod error;
pub mod generator;
pub mod rust_gen;
pub mod type_map;

pub use error::CodegenError;
pub use generator::{CodeGenerator, GeneratedFile};

use smql_ast::machine::MachineDefinition;
use smql_ast::types::{Constraint, TypeDefinition};

use crate::type_map;

/// Generate Rust source code for a single machine definition.
pub fn generate_machine_module(def: &MachineDefinition) -> String {
    let mut out = String::new();

    let mod_name = to_snake_case(&def.name);
    let struct_name = to_pascal_case(&def.name);

    out.push_str(&format!("pub mod {} {{\n", mod_name));
    out.push_str("    use serde::{Deserialize, Serialize};\n\n");

    // Generate inline enums for ENUM fields
    for field in &def.data {
        if let TypeDefinition::Enum(variants) = &field.field_type {
            let enum_name = field_enum_name(&struct_name, &field.name);
            out.push_str(&generate_field_enum(&enum_name, variants));
        }
    }

    // Generate state enum
    out.push_str(&generate_state_enum(def));

    // Generate data struct
    out.push_str(&generate_data_struct(def));

    // Generate machine marker struct + SmqlMachine impl
    out.push_str(&generate_machine_marker(def));

    out.push_str("}\n");
    out
}

fn generate_field_enum(name: &str, variants: &[String]) -> String {
    let mut out = String::new();
    out.push_str("    #[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]\n");
    out.push_str(&format!("    pub enum {} {{\n", name));
    for v in variants {
        let variant = to_pascal_case(v);
        out.push_str(&format!(
            "        #[serde(rename = \"{}\")]\n        {},\n",
            v, variant
        ));
    }
    out.push_str("    }\n\n");
    out
}

fn generate_state_enum(def: &MachineDefinition) -> String {
    let mut out = String::new();
    out.push_str("    #[derive(Debug, Clone, PartialEq)]\n    pub enum State {\n");
    for state in &def.states {
        out.push_str(&format!("        {},\n", to_pascal_case(&state.name)));
    }
    out.push_str("    }\n\n");

    // SmqlState impl
    out.push_str("    impl State {\n");

    // from_str
    out.push_str("        pub fn from_name(s: &str) -> Option<Self> {\n");
    out.push_str("            match s {\n");
    for state in &def.states {
        out.push_str(&format!(
            "                \"{}\" => Some(Self::{}),\n",
            state.name,
            to_pascal_case(&state.name)
        ));
    }
    out.push_str("                _ => None,\n");
    out.push_str("            }\n");
    out.push_str("        }\n\n");

    // as_str
    out.push_str("        pub fn as_str(&self) -> &str {\n");
    out.push_str("            match self {\n");
    for state in &def.states {
        out.push_str(&format!(
            "                Self::{} => \"{}\",\n",
            to_pascal_case(&state.name),
            state.name
        ));
    }
    out.push_str("            }\n");
    out.push_str("        }\n\n");

    // is_terminal
    out.push_str("        pub fn is_terminal(&self) -> bool {\n");
    out.push_str("            matches!(self, ");
    let terminals: Vec<String> = def
        .terminal_states
        .iter()
        .map(|s| format!("Self::{}", to_pascal_case(s)))
        .collect();
    if terminals.is_empty() {
        out.push_str("_ if false => true");
    } else {
        out.push_str(&terminals.join(" | "));
    }
    out.push_str(")\n");
    out.push_str("        }\n");
    out.push_str("    }\n\n");
    out
}

fn generate_data_struct(def: &MachineDefinition) -> String {
    let mut out = String::new();
    let struct_name = to_pascal_case(&def.name);
    let data_name = format!("{}Data", struct_name);

    out.push_str(&format!(
        "    #[derive(Debug, Clone, Serialize, Deserialize)]\n    pub struct {} {{\n",
        data_name
    ));

    for field in &def.data {
        let is_optional = field
            .constraints
            .iter()
            .any(|c| matches!(c, Constraint::Optional));

        let rust_type = if let TypeDefinition::Enum(_) = &field.field_type {
            field_enum_name(&struct_name, &field.name)
        } else {
            type_map::smql_type_to_rust(&field.field_type)
        };

        let final_type = if is_optional {
            format!("Option<{}>", rust_type)
        } else {
            rust_type
        };

        out.push_str(&format!("        pub {}: {},\n", field.name, final_type));
    }

    out.push_str("    }\n\n");
    out
}

fn generate_machine_marker(def: &MachineDefinition) -> String {
    let mut out = String::new();
    let struct_name = to_pascal_case(&def.name);
    let data_name = format!("{}Data", struct_name);

    out.push_str(&format!("    pub struct {};\n\n", struct_name));

    out.push_str(&format!("    impl {} {{\n", struct_name));
    out.push_str(&format!(
        "        pub const MACHINE_NAME: &'static str = \"{}\";\n",
        def.name
    ));
    out.push_str(&format!("        pub type Data = {};\n", data_name));
    out.push_str("        pub type MachineState = State;\n");
    out.push_str("    }\n");
    out
}

/// Convert a string to PascalCase.
/// Handles snake_case (in_progress → InProgress), already-PascalCase (SupportTicket → SupportTicket),
/// and lowercase (open → Open).
pub fn to_pascal_case(s: &str) -> String {
    if s.contains('_') || s.contains('-') || s.contains(' ') {
        // Split on separators and capitalize each part
        s.split(['_', '-', ' '])
            .filter(|part| !part.is_empty())
            .map(|part| {
                let mut chars = part.chars();
                match chars.next() {
                    None => String::new(),
                    Some(first) => {
                        let mut result = first.to_uppercase().to_string();
                        result.extend(chars);
                        result
                    }
                }
            })
            .collect()
    } else if s.chars().next().is_some_and(|c| c.is_lowercase()) {
        // Simple lowercase word: capitalize first letter
        let mut chars = s.chars();
        match chars.next() {
            None => String::new(),
            Some(first) => {
                let mut result = first.to_uppercase().to_string();
                result.extend(chars);
                result
            }
        }
    } else {
        // Already PascalCase or mixed case: return as-is
        s.to_string()
    }
}

/// Convert a string to snake_case.
pub fn to_snake_case(s: &str) -> String {
    let mut result = String::new();
    for (i, ch) in s.chars().enumerate() {
        if ch.is_uppercase() {
            if i > 0 {
                result.push('_');
            }
            result.extend(ch.to_lowercase());
        } else if ch == '-' || ch == ' ' {
            result.push('_');
        } else {
            result.push(ch);
        }
    }
    result
}

/// Generate the enum name for a field's ENUM type.
fn field_enum_name(machine_pascal: &str, field_name: &str) -> String {
    format!("{}{}", machine_pascal, to_pascal_case(field_name))
}

use smql_ast::types::TypeDefinition;

/// Map an SMQL type to a Rust type string.
pub fn smql_type_to_rust(ty: &TypeDefinition) -> String {
    match ty {
        TypeDefinition::Text => "String".to_string(),
        TypeDefinition::Int => "i64".to_string(),
        TypeDefinition::Float => "f64".to_string(),
        TypeDefinition::Bool => "bool".to_string(),
        TypeDefinition::Uuid => "String".to_string(),
        TypeDefinition::Date => "String".to_string(),
        TypeDefinition::DateTime => "String".to_string(),
        TypeDefinition::Duration => "String".to_string(),
        TypeDefinition::Enum(_) => "String".to_string(), // replaced with generated enum name
        TypeDefinition::Ref(_) => "String".to_string(),
        TypeDefinition::List(inner) => format!("Vec<{}>", smql_type_to_rust(inner)),
        TypeDefinition::Set(inner) => format!("Vec<{}>", smql_type_to_rust(inner)),
        TypeDefinition::Map(k, v) => {
            format!(
                "std::collections::BTreeMap<{}, {}>",
                smql_type_to_rust(k),
                smql_type_to_rust(v)
            )
        }
        TypeDefinition::Blob => "Vec<u8>".to_string(),
        TypeDefinition::Money(_) => "(i64, String)".to_string(),
        TypeDefinition::Json => "serde_json::Value".to_string(),
    }
}

/// Map an SMQL type to a Rust type string, using a generated enum name for ENUM fields.
pub fn smql_type_to_rust_with_enum(ty: &TypeDefinition, enum_name: &str) -> String {
    match ty {
        TypeDefinition::Enum(_) => enum_name.to_string(),
        other => smql_type_to_rust(other),
    }
}

use smql_ast::command::{AlterMachineCommand, AlterOperation};
use smql_ast::machine::{MachineDefinition, StateDefinition, TransitionSource};
use smql_ast::types::Constraint;
use smql_ast::value::Value;
use smql_ast::{SmqlError, SmqlResult};
use smql_storage::instance::Mutation;

use crate::engine::Engine;
use crate::eval::{eval_expr, EvalContext};

/// Result of an ALTER MACHINE operation.
#[derive(Debug, Clone)]
pub struct AlterResult {
    pub machine: String,
    pub new_version: u64,
    pub operations_applied: usize,
    pub instances_migrated: u64,
    pub warnings: Vec<String>,
}

impl Engine {
    /// Execute an ALTER MACHINE command.
    ///
    /// This applies schema changes to the machine definition in the catalog
    /// and performs any necessary data migrations on existing instances.
    pub async fn execute_alter_machine(
        &self,
        cmd: &AlterMachineCommand,
    ) -> SmqlResult<AlterResult> {
        // Load current machine definition
        let mut machine_def = self.catalog.get(&cmd.machine)?;
        let mut warnings = Vec::new();
        let mut total_migrated = 0u64;

        // Validate and apply each operation sequentially.
        // Each operation is validated against the current (mutated) definition.
        for op in &cmd.operations {
            self.validate_alter_operation(&machine_def, op)?;
            let migrated = self
                .apply_alter_operation(&mut machine_def, op, &mut warnings)
                .await?;
            total_migrated += migrated;
        }

        // Update the catalog (increments version, preserves history)
        let catalog_warnings = self.catalog.update(machine_def.clone())?;
        for w in catalog_warnings {
            warnings.push(w.message);
        }

        let new_version = self.catalog.version(&cmd.machine)?;

        Ok(AlterResult {
            machine: cmd.machine.clone(),
            new_version,
            operations_applied: cmd.operations.len(),
            instances_migrated: total_migrated,
            warnings,
        })
    }

    /// Validate a single alter operation against the current machine definition.
    fn validate_alter_operation(
        &self,
        machine_def: &MachineDefinition,
        op: &AlterOperation,
    ) -> SmqlResult<()> {
        match op {
            AlterOperation::AddState(name) => {
                if machine_def.states.iter().any(|s| s.name == *name) {
                    return Err(SmqlError::ValidationError {
                        field: None,
                        message: format!(
                            "State '{}' already exists in machine '{}'",
                            name, machine_def.name
                        ),
                        hint: None,
                    });
                }
            }

            AlterOperation::RemoveState { state, migrate_to } => {
                if !machine_def.states.iter().any(|s| s.name == *state) {
                    return Err(SmqlError::ValidationError {
                        field: None,
                        message: format!(
                            "State '{}' does not exist in machine '{}'",
                            state, machine_def.name
                        ),
                        hint: None,
                    });
                }
                if !machine_def.states.iter().any(|s| s.name == *migrate_to) {
                    return Err(SmqlError::ValidationError {
                        field: None,
                        message: format!(
                            "Migration target state '{}' does not exist in machine '{}'",
                            migrate_to, machine_def.name
                        ),
                        hint: None,
                    });
                }
                if *state == machine_def.initial_state {
                    return Err(SmqlError::ValidationError {
                        field: None,
                        message: format!(
                            "Cannot remove initial state '{}' from machine '{}'",
                            state, machine_def.name
                        ),
                        hint: Some("Change the initial state first".to_string()),
                    });
                }
                if *state == *migrate_to {
                    return Err(SmqlError::ValidationError {
                        field: None,
                        message: format!("Cannot migrate state '{}' to itself", state),
                        hint: None,
                    });
                }
            }

            AlterOperation::AddTransition(t) => {
                let from_name = match &t.from {
                    TransitionSource::State(s) => Some(s.as_str()),
                    TransitionSource::Any { .. } => None,
                    TransitionSource::Group(_) => None,
                };
                if let Some(from) = from_name {
                    if !machine_def.states.iter().any(|s| s.name == from) {
                        return Err(SmqlError::ValidationError {
                            field: None,
                            message: format!("Transition source state '{}' does not exist", from),
                            hint: None,
                        });
                    }
                }
                if !machine_def.states.iter().any(|s| s.name == t.to) {
                    return Err(SmqlError::ValidationError {
                        field: None,
                        message: format!("Transition target state '{}' does not exist", t.to),
                        hint: None,
                    });
                }
            }

            AlterOperation::RemoveTransition { from, to } => {
                let exists = machine_def.transitions.iter().any(|t| {
                    t.to == *to
                        && match &t.from {
                            TransitionSource::State(s) => s == from,
                            _ => false,
                        }
                });
                if !exists {
                    return Err(SmqlError::ValidationError {
                        field: None,
                        message: format!("No transition from '{}' to '{}' exists", from, to),
                        hint: None,
                    });
                }
            }

            AlterOperation::ModifyTransition(t) => {
                let from_name = match &t.from {
                    TransitionSource::State(s) => s.clone(),
                    TransitionSource::Any { .. } => "ANY".to_string(),
                    TransitionSource::Group(g) => g.clone(),
                };
                let exists = machine_def.transitions.iter().any(|existing| {
                    existing.to == t.to
                        && match (&existing.from, &t.from) {
                            (TransitionSource::State(a), TransitionSource::State(b)) => a == b,
                            (TransitionSource::Any { .. }, TransitionSource::Any { .. }) => true,
                            _ => false,
                        }
                });
                if !exists {
                    return Err(SmqlError::ValidationError {
                        field: None,
                        message: format!(
                            "No transition from '{}' to '{}' exists to modify",
                            from_name, t.to
                        ),
                        hint: None,
                    });
                }
            }

            AlterOperation::AddData { field, backfill } => {
                if machine_def.data.iter().any(|d| d.name == field.name) {
                    return Err(SmqlError::ValidationError {
                        field: None,
                        message: format!(
                            "Data field '{}' already exists in machine '{}'",
                            field.name, machine_def.name
                        ),
                        hint: None,
                    });
                }
                // Warn if required and no default or backfill
                let is_required = field
                    .constraints
                    .iter()
                    .any(|c| matches!(c, Constraint::Required));
                let has_default = field
                    .constraints
                    .iter()
                    .any(|c| matches!(c, Constraint::Default(_)));
                if is_required && !has_default && backfill.is_none() {
                    return Err(SmqlError::ValidationError {
                        field: Some(field.name.clone()),
                        message: format!(
                            "Adding REQUIRED field '{}' without DEFAULT or BACKFILL expression",
                            field.name
                        ),
                        hint: Some("Add a DEFAULT value or BACKFILL expression".to_string()),
                    });
                }
            }

            AlterOperation::RemoveData(name) => {
                if !machine_def.data.iter().any(|d| d.name == *name) {
                    return Err(SmqlError::ValidationError {
                        field: None,
                        message: format!(
                            "Data field '{}' does not exist in machine '{}'",
                            name, machine_def.name
                        ),
                        hint: None,
                    });
                }
            }

            AlterOperation::Backfill { field, .. } => {
                if !machine_def.data.iter().any(|d| d.name == *field) {
                    return Err(SmqlError::ValidationError {
                        field: None,
                        message: format!(
                            "Data field '{}' does not exist in machine '{}'",
                            field, machine_def.name
                        ),
                        hint: Some("Add the field first with ADD DATA".to_string()),
                    });
                }
            }
        }

        Ok(())
    }

    /// Apply a single alter operation to the machine definition and storage.
    /// Returns the number of instances affected by data migrations.
    async fn apply_alter_operation(
        &self,
        machine_def: &mut MachineDefinition,
        op: &AlterOperation,
        warnings: &mut Vec<String>,
    ) -> SmqlResult<u64> {
        match op {
            AlterOperation::AddState(name) => {
                machine_def.states.push(StateDefinition::new(name.clone()));
                Ok(0)
            }

            AlterOperation::RemoveState { state, migrate_to } => {
                // Migrate instances in the removed state to the target state
                let migrated = self
                    .storage
                    .migrate_instances_state(&machine_def.name, state, migrate_to)
                    .await?;

                if migrated > 0 {
                    warnings.push(format!(
                        "Migrated {} instance(s) from '{}' to '{}'",
                        migrated, state, migrate_to
                    ));
                }

                // Remove the state from the definition
                machine_def.states.retain(|s| s.name != *state);

                // Remove from terminal states if present
                machine_def.terminal_states.retain(|s| s != state);

                // Remove transitions involving this state
                let removed_count = machine_def.transitions.len();
                machine_def.transitions.retain(|t| {
                    let from_matches = match &t.from {
                        TransitionSource::State(s) => s == state,
                        _ => false,
                    };
                    !(from_matches || t.to == *state)
                });
                let removed = removed_count - machine_def.transitions.len();
                if removed > 0 {
                    warnings.push(format!(
                        "Removed {} transition(s) involving state '{}'",
                        removed, state
                    ));
                }

                // Clean up ANY transition except lists that reference the removed state
                for t in &mut machine_def.transitions {
                    if let TransitionSource::Any { except } = &mut t.from {
                        except.retain(|s| s != state);
                    }
                }

                Ok(migrated)
            }

            AlterOperation::AddTransition(t) => {
                machine_def.transitions.push(t.clone());
                Ok(0)
            }

            AlterOperation::RemoveTransition { from, to } => {
                machine_def.transitions.retain(|t| {
                    let from_matches = match &t.from {
                        TransitionSource::State(s) => s == from,
                        _ => false,
                    };
                    !(from_matches && t.to == *to)
                });
                Ok(0)
            }

            AlterOperation::ModifyTransition(new_t) => {
                for t in &mut machine_def.transitions {
                    let matches = t.to == new_t.to
                        && match (&t.from, &new_t.from) {
                            (TransitionSource::State(a), TransitionSource::State(b)) => a == b,
                            (TransitionSource::Any { .. }, TransitionSource::Any { .. }) => true,
                            _ => false,
                        };
                    if matches {
                        *t = new_t.clone();
                        break;
                    }
                }
                Ok(0)
            }

            AlterOperation::AddData { field, backfill } => {
                machine_def.data.push(field.clone());

                // Backfill existing instances if expression provided
                if let Some(backfill_expr) = backfill {
                    let ctx = EvalContext::new(std::collections::HashMap::new(), String::new());
                    let value = eval_expr(backfill_expr, &ctx)?;
                    let mutations = vec![Mutation::SetField(field.name.clone(), value)];
                    let count = self
                        .storage
                        .bulk_update_instances(&machine_def.name, &mutations)
                        .await?;
                    if count > 0 {
                        warnings.push(format!(
                            "Backfilled field '{}' on {} instance(s)",
                            field.name, count
                        ));
                    }
                    return Ok(count);
                }

                // If field has a DEFAULT, backfill with default value
                let default = field.constraints.iter().find_map(|c| {
                    if let Constraint::Default(d) = c {
                        Some(d)
                    } else {
                        None
                    }
                });
                if let Some(default_val) = default {
                    let value = default_to_value(default_val);
                    let mutations = vec![Mutation::SetField(field.name.clone(), value)];
                    let count = self
                        .storage
                        .bulk_update_instances(&machine_def.name, &mutations)
                        .await?;
                    if count > 0 {
                        warnings.push(format!(
                            "Set default for field '{}' on {} instance(s)",
                            field.name, count
                        ));
                    }
                    return Ok(count);
                }

                Ok(0)
            }

            AlterOperation::RemoveData(name) => {
                machine_def.data.retain(|d| d.name != *name);

                // Remove field from all existing instances
                let mutations = vec![Mutation::RemoveField(name.clone())];
                let count = self
                    .storage
                    .bulk_update_instances(&machine_def.name, &mutations)
                    .await?;
                if count > 0 {
                    warnings.push(format!(
                        "Removed field '{}' from {} instance(s)",
                        name, count
                    ));
                }
                Ok(count)
            }

            AlterOperation::Backfill { field, value } => {
                let ctx = EvalContext::new(std::collections::HashMap::new(), String::new());
                let val = eval_expr(value, &ctx)?;
                let mutations = vec![Mutation::SetField(field.clone(), val)];
                let count = self
                    .storage
                    .bulk_update_instances(&machine_def.name, &mutations)
                    .await?;
                Ok(count)
            }
        }
    }
}

/// Convert a DefaultValue to a runtime Value (mirrors engine.rs::default_to_value).
fn default_to_value(default: &smql_ast::types::DefaultValue) -> Value {
    match default {
        smql_ast::types::DefaultValue::String(s) => Value::Text(s.clone()),
        smql_ast::types::DefaultValue::Int(v) => Value::Int(*v),
        smql_ast::types::DefaultValue::Float(v) => Value::Float(*v),
        smql_ast::types::DefaultValue::Bool(v) => Value::Bool(*v),
        smql_ast::types::DefaultValue::EmptySet => Value::Set(Vec::new()),
        smql_ast::types::DefaultValue::EmptyList => Value::List(Vec::new()),
        smql_ast::types::DefaultValue::EmptyMap => Value::Map(std::collections::BTreeMap::new()),
        smql_ast::types::DefaultValue::Null => Value::Null,
    }
}

use chrono::Utc;
use smql_ast::command::{BatchTransitionCommand, SpawnCommand, TransitionCommand};
use smql_ast::error::{GuardFailure, TransitionDeniedError};
use smql_ast::machine::{Action, HookTrigger, MachineDefinition, TransitionSource};
use smql_ast::types::{Constraint, DefaultValue, TypeDefinition};
use smql_ast::value::Value;
use smql_ast::{SmqlError, SmqlResult};
use smql_catalog::MachineCatalog;
use smql_hooks::{EngineCallback, EventBus, HookContext, HookError, HookExecutor, ResolvedAction};
use smql_storage::instance::{Filter, Instance, Mutation, TrailEntry};
use smql_storage::traits::Storage;
use smql_timer::TimerManager;
use std::collections::HashMap;
use std::sync::Arc;

use crate::eval::{eval_expr, eval_guard, ActorInfo, ChildInfo, EvalContext};

/// The core SMQL engine — executes spawn, transition, and query operations.
pub struct Engine {
    pub catalog: Arc<MachineCatalog>,
    pub storage: Arc<dyn Storage>,
    pub timer_manager: Arc<TimerManager>,
    pub hook_executor: Arc<HookExecutor>,
}

/// Result of a spawn operation.
#[derive(Debug, Clone)]
pub struct SpawnResult {
    pub instance: Instance,
}

/// Result of a transition operation.
#[derive(Debug, Clone)]
pub struct TransitionResult {
    pub instance: Instance,
    pub from_state: String,
    pub to_state: String,
}

/// Result of a batch transition operation.
#[derive(Debug, Clone)]
pub struct BatchTransitionResult {
    pub matched: usize,
    pub transitioned: usize,
    pub failures: Vec<BatchTransitionFailure>,
    /// from_state counts for metric updates (state -> count).
    pub from_states: HashMap<String, usize>,
}

/// A single failure in a batch transition.
#[derive(Debug, Clone)]
pub struct BatchTransitionFailure {
    pub instance_id: String,
    pub error: String,
}

impl Engine {
    pub fn new(catalog: Arc<MachineCatalog>, storage: Arc<dyn Storage>) -> Self {
        let event_bus = Arc::new(EventBus::default());
        Self {
            catalog,
            storage,
            timer_manager: Arc::new(TimerManager::new()),
            hook_executor: Arc::new(HookExecutor::new(event_bus)),
        }
    }

    pub fn with_timer_manager(
        catalog: Arc<MachineCatalog>,
        storage: Arc<dyn Storage>,
        timer_manager: Arc<TimerManager>,
    ) -> Self {
        let event_bus = Arc::new(EventBus::default());
        Self {
            catalog,
            storage,
            timer_manager,
            hook_executor: Arc::new(HookExecutor::new(event_bus)),
        }
    }

    pub fn with_hooks(
        catalog: Arc<MachineCatalog>,
        storage: Arc<dyn Storage>,
        timer_manager: Arc<TimerManager>,
        hook_executor: Arc<HookExecutor>,
    ) -> Self {
        Self {
            catalog,
            storage,
            timer_manager,
            hook_executor,
        }
    }

    /// Get a reference to the event bus for subscribing to events.
    pub fn event_bus(&self) -> &Arc<EventBus> {
        &self.hook_executor.event_bus
    }

    /// Spawn a new machine instance.
    #[tracing::instrument(skip(self, cmd), fields(machine = %cmd.machine))]
    pub async fn spawn(&self, cmd: &SpawnCommand) -> SmqlResult<SpawnResult> {
        let machine_def = self.catalog.get(&cmd.machine)?;

        // Evaluate data expressions and collect into HashMap
        let ctx = EvalContext::new(HashMap::new(), machine_def.initial_state.clone());
        let mut data = HashMap::new();
        for (field, expr) in &cmd.data {
            let val = eval_expr(expr, &ctx)?;
            data.insert(field.clone(), val);
        }

        // Validate data against machine DATA definition
        self.validate_spawn_data(&machine_def, &mut data)?;

        // Create instance (with optional parent linkage)
        let instance = if let (Some(parent_id_str), Some(parent_machine)) =
            (&cmd.parent_id, &cmd.parent_machine)
        {
            let parent_id = smql_storage::InstanceId::from_string(parent_id_str)
                .map_err(|_| SmqlError::not_found("Parent instance", parent_id_str))?;
            // Validate parent exists
            let _parent = self
                .storage
                .get_instance(&parent_id)
                .await?
                .ok_or_else(|| SmqlError::not_found("Parent instance", parent_id_str))?;
            Instance::new_child(
                cmd.machine.clone(),
                machine_def.initial_state.clone(),
                data,
                parent_id,
                parent_machine.clone(),
            )
        } else {
            Instance::new(cmd.machine.clone(), machine_def.initial_state.clone(), data)
        };

        // Create initial trail entry (spawn event)
        let trail_entry = TrailEntry {
            instance_id: instance.id.clone(),
            machine: cmd.machine.clone(),
            sequence: 0,
            from_state: String::new(),
            to_state: machine_def.initial_state.clone(),
            transition_name: Some("SPAWN".to_string()),
            actor: None,
            memo: None,
            timestamp: Utc::now(),
            data_snapshot: Some(instance.data.clone()),
        };

        // Store atomically
        self.storage.store_instance(&instance).await?;
        self.storage.append_trail_entry(&trail_entry).await?;

        // --- Fire ON SPAWN hooks ---
        let hook_ctx = HookContext {
            instance_id: instance.id.as_str(),
            machine: cmd.machine.clone(),
            from_state: String::new(),
            to_state: machine_def.initial_state.clone(),
            data: instance.data.clone(),
            actor: None,
            memo: None,
        };
        let eval_ctx = EvalContext::new(instance.data.clone(), machine_def.initial_state.clone());
        let resolved = self.resolve_hooks_actions(&machine_def.hooks, &eval_ctx);
        let _ = self
            .hook_executor
            .fire_hooks(
                &machine_def.hooks,
                &HookTrigger::OnSpawn,
                &hook_ctx,
                &resolved,
            )
            .await;

        // --- Fire ON ENTER(initial_state) hooks ---
        let _ = self
            .hook_executor
            .fire_hooks(
                &machine_def.hooks,
                &HookTrigger::OnEnter(machine_def.initial_state.clone()),
                &hook_ctx,
                &resolved,
            )
            .await;

        // Handle THEN TRANSITION if specified
        if let Some(target_state) = &cmd.then_transition {
            let transition_cmd = TransitionCommand {
                machine: cmd.machine.clone(),
                instance_id: instance.id.as_str(),
                to_state: target_state.clone(),
                with_data: Vec::new(),
                memo: None,
                as_actor: None,
                through: Vec::new(),
                or_stay: false,
                cascade: false,
            };
            let result = self.transition(&transition_cmd).await?;
            return Ok(SpawnResult {
                instance: result.instance,
            });
        }

        tracing::info!(id = %instance.id, state = %instance.state, "instance spawned");
        Ok(SpawnResult { instance })
    }

    /// Validate spawn data against the machine's DATA definition.
    fn validate_spawn_data(
        &self,
        machine_def: &MachineDefinition,
        data: &mut HashMap<String, Value>,
    ) -> SmqlResult<()> {
        for field_def in &machine_def.data {
            let is_required = field_def
                .constraints
                .iter()
                .any(|c| matches!(c, Constraint::Required));

            if let Some(value) = data.get(&field_def.name) {
                // Type check
                if !matches!(value, Value::Null) {
                    self.check_type_compat(&field_def.name, value, &field_def.field_type)?;
                }
            } else if is_required {
                // Check for default value
                let default = field_def.constraints.iter().find_map(|c| {
                    if let Constraint::Default(d) = c {
                        Some(d)
                    } else {
                        None
                    }
                });

                if let Some(default_val) = default {
                    data.insert(field_def.name.clone(), default_to_value(default_val));
                } else {
                    return Err(SmqlError::SpawnRejected {
                        message: format!(
                            "Required field '{}' is missing and has no default",
                            field_def.name
                        ),
                        field: Some(field_def.name.clone()),
                        hint: Some(format!("Provide '{}' in SPAWN data", field_def.name)),
                    });
                }
            } else {
                // Optional field not provided — apply default if one exists
                let default = field_def.constraints.iter().find_map(|c| {
                    if let Constraint::Default(d) = c {
                        Some(d)
                    } else {
                        None
                    }
                });

                if let Some(default_val) = default {
                    data.insert(field_def.name.clone(), default_to_value(default_val));
                }
            }
        }

        Ok(())
    }

    /// Basic type compatibility check between a Value and a TypeDefinition.
    fn check_type_compat(
        &self,
        field_name: &str,
        value: &Value,
        type_def: &TypeDefinition,
    ) -> SmqlResult<()> {
        let compatible = match (value, type_def) {
            (Value::Text(_), TypeDefinition::Text) => true,
            (Value::Int(_), TypeDefinition::Int) => true,
            (Value::Float(_), TypeDefinition::Float) => true,
            (Value::Bool(_), TypeDefinition::Bool) => true,
            (Value::Uuid(_), TypeDefinition::Uuid) => true,
            (Value::Date(_), TypeDefinition::Date) => true,
            (Value::DateTime(_), TypeDefinition::DateTime) => true,
            (Value::Duration(_), TypeDefinition::Duration) => true,
            (Value::List(_), TypeDefinition::List(_)) => true,
            (Value::Set(_), TypeDefinition::Set(_)) => true,
            (Value::Map(_), TypeDefinition::Map(_, _)) => true,
            (Value::Blob(_), TypeDefinition::Blob) => true,
            (Value::Money(_, _), TypeDefinition::Money(_)) => true,
            (Value::Json(_), TypeDefinition::Json) => true,
            (Value::Ref(_, _), TypeDefinition::Ref(_)) => true,
            (Value::Text(_), TypeDefinition::Enum(_)) => true, // Enums stored as text
            (Value::Int(_), TypeDefinition::Float) => true,    // Int -> Float coercion
            _ => false,
        };

        if !compatible {
            return Err(SmqlError::SpawnRejected {
                message: format!(
                    "Field '{}' has type {} but got value {}",
                    field_name, type_def, value
                ),
                field: Some(field_name.to_string()),
                hint: Some(format!("Expected type: {}", type_def)),
            });
        }

        Ok(())
    }

    /// Execute a transition on an instance.
    pub fn transition<'a>(
        &'a self,
        cmd: &'a TransitionCommand,
    ) -> std::pin::Pin<
        Box<dyn std::future::Future<Output = SmqlResult<TransitionResult>> + Send + 'a>,
    > {
        Box::pin(self.transition_inner(cmd))
    }

    #[tracing::instrument(skip(self, cmd), fields(instance_id = %cmd.instance_id, to_state = %cmd.to_state))]
    async fn transition_inner(&self, cmd: &TransitionCommand) -> SmqlResult<TransitionResult> {
        // Handle THROUGH (multi-hop)
        if !cmd.through.is_empty() {
            return self.transition_through(cmd).await;
        }

        let id = smql_storage::InstanceId::from_string(&cmd.instance_id)
            .map_err(|_| SmqlError::not_found("Instance", &cmd.instance_id))?;

        let instance = self
            .storage
            .get_instance(&id)
            .await?
            .ok_or_else(|| SmqlError::not_found("Instance", &cmd.instance_id))?;

        // Validate machine name matches the instance's actual machine
        if !cmd.machine.is_empty() && cmd.machine != instance.machine {
            return Err(SmqlError::ValidationError {
                message: format!(
                    "Machine mismatch: command specifies '{}' but instance belongs to '{}'",
                    cmd.machine, instance.machine
                ),
                field: Some("machine".to_string()),
                hint: Some(format!(
                    "Use TRANSITION {} \"{}\" TO ...",
                    instance.machine, cmd.instance_id
                )),
            });
        }

        let machine_def = self.catalog.get(&instance.machine)?;

        // Find matching transition definition
        let transition_def = self.find_transition(&machine_def, &instance.state, &cmd.to_state)?;

        // Build evaluation context
        let mut eval_data = instance.data.clone();
        // Apply WITH data mutations for guard evaluation
        let with_ctx = EvalContext::new(instance.data.clone(), instance.state.clone());
        for (field, expr) in &cmd.with_data {
            let val = eval_expr(expr, &with_ctx)?;
            eval_data.insert(field.clone(), val);
        }

        let timeout_remaining = self
            .timer_manager
            .timeout_remaining(&cmd.instance_id, &instance.state);

        let mut ctx = EvalContext {
            data: eval_data,
            state: instance.state.clone(),
            actor: cmd.as_actor.as_ref().map(|a| ActorInfo {
                id: a.clone(),
                role: None,
                fields: HashMap::new(),
            }),
            state_entered_at: instance.state_entered_at,
            created_at: instance.created_at,
            now: Utc::now(),
            timeout_remaining,
            children: HashMap::new(),
            parent_data: None,
            parent_state: None,
        };

        // Populate children/parent context for composition guards
        if !machine_def.children.is_empty() || instance.parent_id.is_some() {
            self.populate_composition_context(&mut ctx, &instance, &machine_def)
                .await;
        }

        // Build HookContext for this transition
        let hook_ctx = HookContext {
            instance_id: cmd.instance_id.clone(),
            machine: instance.machine.clone(),
            from_state: instance.state.clone(),
            to_state: cmd.to_state.clone(),
            data: ctx.data.clone(),
            actor: cmd.as_actor.clone(),
            memo: cmd.memo.clone(),
        };

        // Resolve hook actions with current eval context
        let resolved_hook_actions = self.resolve_hooks_actions(&machine_def.hooks, &ctx);

        // --- 1. BEFORE EACH TRANSITION hooks (sync, can reject) ---
        if let Err(e) = self
            .hook_executor
            .fire_hooks(
                &machine_def.hooks,
                &HookTrigger::BeforeEachTransition,
                &hook_ctx,
                &resolved_hook_actions,
            )
            .await
        {
            // BEFORE hook rejected → treat like a guard failure
            return Err(SmqlError::TransitionDenied(TransitionDeniedError {
                instance_id: cmd.instance_id.clone(),
                from_state: instance.state.clone(),
                to_state: cmd.to_state.clone(),
                guard_failures: vec![GuardFailure {
                    guard_expr: "BEFORE EACH TRANSITION hook".to_string(),
                    actual_value: Some(e.to_string()),
                    expected: None,
                    hint: Some("Hook rejected the transition".to_string()),
                }],
                hint: None,
            }));
        }

        // --- 2. Evaluate ALL guard conditions — collect ALL failures ---
        let mut guard_failures = Vec::new();
        for guard in &transition_def.guards {
            match eval_guard(guard, &ctx) {
                Ok(true) => {}
                Ok(false) => {
                    guard_failures.push(GuardFailure {
                        guard_expr: guard.to_string(),
                        actual_value: None,
                        expected: Some("true".to_string()),
                        hint: None,
                    });
                }
                Err(e) => {
                    guard_failures.push(GuardFailure {
                        guard_expr: guard.to_string(),
                        actual_value: Some(e.to_string()),
                        expected: None,
                        hint: None,
                    });
                }
            }
        }

        if !guard_failures.is_empty() {
            tracing::warn!(failures = guard_failures.len(), "guard evaluation failed");
            if cmd.or_stay {
                // OR STAY: apply data mutations but don't transition
                let mut mutations = Vec::new();
                for (field, expr) in &cmd.with_data {
                    let val = eval_expr(expr, &with_ctx)?;
                    mutations.push(Mutation::SetField(field.clone(), val));
                }
                if !mutations.is_empty() {
                    self.storage
                        .update_instance(&id, instance.version, &mutations)
                        .await?;
                }
                let updated = self
                    .storage
                    .get_instance(&id)
                    .await?
                    .ok_or_else(|| SmqlError::not_found("Instance", &cmd.instance_id))?;
                return Ok(TransitionResult {
                    from_state: instance.state.clone(),
                    to_state: instance.state.clone(),
                    instance: updated,
                });
            }

            return Err(SmqlError::TransitionDenied(TransitionDeniedError {
                instance_id: cmd.instance_id.clone(),
                from_state: instance.state.clone(),
                to_state: cmd.to_state.clone(),
                guard_failures,
                hint: None,
            }));
        }

        // --- 3. Build mutations from WITH data and MUTATE clauses ---
        let mut mutations = Vec::new();
        for (field, expr) in &cmd.with_data {
            let val = eval_expr(expr, &ctx)?;
            mutations.push(Mutation::SetField(field.clone(), val));
        }
        for mutate in &transition_def.mutates {
            // Check for __spawn FunctionCall in MUTATE
            if let smql_ast::expression::ExpressionKind::FunctionCall { name, args } =
                &mutate.value.kind
            {
                if name == "__spawn" {
                    // __spawn(machine_name, key1, val1, key2, val2, ...)
                    if let Some(first_arg) = args.first() {
                        let machine_val = eval_expr(first_arg, &ctx)?;
                        let child_machine = match &machine_val {
                            Value::Text(s) => s.clone(),
                            _ => first_arg.to_string(),
                        };
                        // Collect remaining args as key-value pairs
                        let mut child_data = Vec::new();
                        let mut i = 1;
                        while i + 1 < args.len() {
                            let key_val = eval_expr(&args[i], &ctx)?;
                            let val = eval_expr(&args[i + 1], &ctx)?;
                            let key = match key_val {
                                Value::Text(k) => k,
                                _ => args[i].to_string(),
                            };
                            child_data.push((key, val));
                            i += 2;
                        }
                        // Spawn child with parent linkage
                        let child_data_exprs: Vec<(String, smql_ast::expression::Expression)> =
                            child_data
                                .into_iter()
                                .map(|(k, v)| {
                                    (
                                        k,
                                        smql_ast::expression::Expression::new(
                                            smql_ast::expression::ExpressionKind::Literal(v),
                                        ),
                                    )
                                })
                                .collect();
                        let child_cmd = SpawnCommand {
                            machine: child_machine.clone(),
                            data: child_data_exprs,
                            then_transition: None,
                            batch: false,
                            batch_data: Vec::new(),
                            parent_id: Some(cmd.instance_id.clone()),
                            parent_machine: Some(instance.machine.clone()),
                        };
                        match self.spawn(&child_cmd).await {
                            Ok(result) => {
                                let child_id = result.instance.id.as_str();
                                mutations.push(Mutation::SetField(
                                    mutate.field.clone(),
                                    Value::Ref(child_machine, child_id),
                                ));
                            }
                            Err(e) => {
                                return Err(SmqlError::internal(format!(
                                    "MUTATE SPAWN failed: {}",
                                    e
                                )));
                            }
                        }
                    }
                    continue;
                }
            }
            let val = eval_expr(&mutate.value, &ctx)?;
            mutations.push(Mutation::SetField(mutate.field.clone(), val));
        }

        // Apply mutations to context data for trail snapshot
        for m in &mutations {
            if let Mutation::SetField(field, val) = m {
                ctx.data.insert(field.clone(), val.clone());
            }
        }

        // Create trail entry
        let trail_entry = TrailEntry {
            instance_id: id.clone(),
            machine: instance.machine.clone(),
            sequence: instance.trail_length + 1,
            from_state: instance.state.clone(),
            to_state: cmd.to_state.clone(),
            transition_name: Some(format!("{} -> {}", instance.state, cmd.to_state)),
            actor: cmd.as_actor.clone(),
            memo: cmd.memo.clone(),
            timestamp: Utc::now(),
            data_snapshot: None,
        };

        // --- 4. Atomic storage write ---
        self.storage
            .transition_instance(
                &id,
                instance.version,
                &cmd.to_state,
                &mutations,
                trail_entry,
            )
            .await?;

        // --- 5. ON EXIT(old_state) hooks (fire-and-forget) ---
        let _ = self
            .hook_executor
            .fire_hooks(
                &machine_def.hooks,
                &HookTrigger::OnExit(instance.state.clone()),
                &hook_ctx,
                &resolved_hook_actions,
            )
            .await;

        // --- 6. Cancel old timeout, register new one ---
        self.timer_manager.cancel(&cmd.instance_id, &instance.state);
        let _ = self
            .storage
            .remove_timer(&cmd.instance_id, &instance.state)
            .await;

        if let Some(timeout) = &transition_def.timeout {
            self.timer_manager.register(
                &cmd.instance_id,
                &instance.machine,
                &cmd.to_state,
                &timeout.duration,
                &timeout.target_state,
            );
            // Persist timer to storage for crash recovery
            if let Some(entry) = self
                .timer_manager
                .get_timer(&cmd.instance_id, &cmd.to_state)
            {
                let stored = smql_storage::StoredTimer {
                    instance_id: cmd.instance_id.clone(),
                    machine: instance.machine.clone(),
                    from_state: cmd.to_state.clone(),
                    target_state: timeout.target_state.clone(),
                    deadline: entry.deadline,
                    registered_at: entry.registered_at,
                };
                let _ = self.storage.store_timer(&stored).await;
            }
        }

        // --- 7. Transition ACTIONs (fire-and-forget) ---
        if !transition_def.actions.is_empty() {
            let resolved_transition_actions = self.resolve_actions(&transition_def.actions, &ctx);
            let _ = self
                .hook_executor
                .execute_actions(&resolved_transition_actions, &hook_ctx)
                .await;
        }

        // --- 8. ON ENTER(new_state) hooks (fire-and-forget) ---
        let _ = self
            .hook_executor
            .fire_hooks(
                &machine_def.hooks,
                &HookTrigger::OnEnter(cmd.to_state.clone()),
                &hook_ctx,
                &resolved_hook_actions,
            )
            .await;

        // --- 9. AFTER EACH TRANSITION hooks (fire-and-forget) ---
        let _ = self
            .hook_executor
            .fire_hooks(
                &machine_def.hooks,
                &HookTrigger::AfterEachTransition,
                &hook_ctx,
                &resolved_hook_actions,
            )
            .await;

        // --- 10. CASCADE: transition all children to terminal states ---
        if cmd.cascade {
            self.cascade_children(&id, &instance.machine).await;
        }

        let updated = self
            .storage
            .get_instance(&id)
            .await?
            .ok_or_else(|| SmqlError::not_found("Instance", &cmd.instance_id))?;

        tracing::info!(from = %instance.state, to = %cmd.to_state, "transition complete");
        Ok(TransitionResult {
            from_state: instance.state,
            to_state: cmd.to_state.clone(),
            instance: updated,
        })
    }

    /// Try a transition — returns Ok(None) if guards fail instead of an error.
    pub async fn try_transition(
        &self,
        cmd: &TransitionCommand,
    ) -> SmqlResult<Option<TransitionResult>> {
        match self.transition(cmd).await {
            Ok(result) => Ok(Some(result)),
            Err(SmqlError::TransitionDenied(_)) => Ok(None),
            Err(e) => Err(e),
        }
    }

    /// Execute a batch transition — transition all matching instances.
    ///
    /// Best-effort: transitions what it can and reports failures.
    #[tracing::instrument(skip(self, cmd), fields(machine = %cmd.machine, to_state = %cmd.to_state))]
    pub async fn batch_transition(
        &self,
        cmd: &BatchTransitionCommand,
    ) -> SmqlResult<BatchTransitionResult> {
        // Validate machine exists
        let _machine_def = self.catalog.get(&cmd.machine)?;

        // Find all instances for this machine
        let filter = Filter::default();
        let instances = self.storage.find_instances(&cmd.machine, &filter).await?;

        // Apply WHERE filter
        let matching: Vec<&Instance> = instances
            .iter()
            .filter(|inst| {
                let ctx = EvalContext::new(inst.data.clone(), inst.state.clone());
                eval_guard(&cmd.filter, &ctx).unwrap_or(false)
            })
            .collect();

        let matched = matching.len();
        let mut transitioned = 0;
        let mut failures = Vec::new();
        let mut from_states: HashMap<String, usize> = HashMap::new();

        for inst in matching {
            let from_state = inst.state.clone();
            let t_cmd = TransitionCommand {
                machine: cmd.machine.clone(),
                instance_id: inst.id.as_str(),
                to_state: cmd.to_state.clone(),
                with_data: cmd.with_data.clone(),
                memo: cmd.memo.clone(),
                as_actor: cmd.as_actor.clone(),
                through: Vec::new(),
                or_stay: false,
                cascade: false,
            };

            match self.transition(&t_cmd).await {
                Ok(_) => {
                    transitioned += 1;
                    *from_states.entry(from_state).or_insert(0) += 1;
                }
                Err(e) => {
                    failures.push(BatchTransitionFailure {
                        instance_id: inst.id.as_str(),
                        error: e.to_string(),
                    });
                }
            }
        }

        tracing::info!(matched, transitioned, failed = failures.len(), "batch transition complete");
        Ok(BatchTransitionResult {
            matched,
            transitioned,
            failures,
            from_states,
        })
    }

    /// Execute a multi-hop transition through intermediate states.
    async fn transition_through(&self, cmd: &TransitionCommand) -> SmqlResult<TransitionResult> {
        let mut current_id = cmd.instance_id.clone();
        let mut all_states = cmd.through.clone();
        all_states.push(cmd.to_state.clone());

        let mut last_result = None;

        for target in &all_states {
            let step_cmd = TransitionCommand {
                machine: cmd.machine.clone(),
                instance_id: current_id.clone(),
                to_state: target.clone(),
                with_data: Vec::new(), // WITH data only applies to final transition
                memo: cmd.memo.clone(),
                as_actor: cmd.as_actor.clone(),
                through: Vec::new(),
                or_stay: false,
                cascade: false,
            };

            let result = self.transition(&step_cmd).await?;
            current_id = result.instance.id.as_str();
            last_result = Some(result);
        }

        last_result.ok_or_else(|| SmqlError::internal("THROUGH transition had no steps"))
    }

    /// Cascade: transition all children to their machine's first terminal state.
    /// Errors on child cascade are logged but don't fail the parent.
    async fn cascade_children(&self, parent_id: &smql_storage::InstanceId, _parent_machine: &str) {
        let children = match self.storage.find_children(parent_id, None).await {
            Ok(c) => c,
            Err(_) => return,
        };

        for child in children {
            // Find the child's machine definition to get terminal states
            let child_machine_def = match self.catalog.get(&child.machine) {
                Ok(m) => m,
                Err(_) => continue,
            };

            // Skip if already in a terminal state
            if child_machine_def.terminal_states.contains(&child.state) {
                continue;
            }

            // Try to find a transition from current state to the first terminal state
            if let Some(terminal) = child_machine_def.terminal_states.first() {
                let cmd = TransitionCommand {
                    machine: child.machine.clone(),
                    instance_id: child.id.as_str(),
                    to_state: terminal.clone(),
                    with_data: Vec::new(),
                    memo: Some("CASCADE from parent".to_string()),
                    as_actor: Some("System".to_string()),
                    through: Vec::new(),
                    or_stay: false,
                    cascade: true, // Recursive cascade for grandchildren
                };
                // Use try_transition so failures don't propagate
                let _ = self.try_transition(&cmd).await;
            }
        }
    }

    /// Find a matching transition definition for the given from -> to states.
    fn find_transition(
        &self,
        machine: &MachineDefinition,
        from_state: &str,
        to_state: &str,
    ) -> SmqlResult<smql_ast::machine::TransitionDefinition> {
        // First check direct transitions
        for t in &machine.transitions {
            if t.to != to_state {
                continue;
            }

            let matches_source = match &t.from {
                TransitionSource::State(s) => s == from_state,
                TransitionSource::Any { except } => !except.iter().any(|e| e == from_state),
                TransitionSource::Group(_) => false, // Groups resolved at runtime
            };

            if matches_source {
                return Ok(t.clone());
            }
        }

        Err(SmqlError::TransitionDenied(TransitionDeniedError {
            instance_id: String::new(),
            from_state: from_state.to_string(),
            to_state: to_state.to_string(),
            guard_failures: Vec::new(),
            hint: Some(format!(
                "No transition defined from '{}' to '{}' in machine '{}'",
                from_state, to_state, machine.name
            )),
        }))
    }

    /// Execute a timeout-triggered transition (guard-free, as System actor).
    ///
    /// This bypasses normal guard evaluation since the timeout IS the condition.
    /// If the instance has already left the expected state, this is a no-op.
    #[tracing::instrument(skip(self), fields(instance_id = %instance_id, target_state = %target_state))]
    pub async fn timeout_transition(
        &self,
        instance_id: &str,
        expected_from_state: &str,
        target_state: &str,
    ) -> SmqlResult<Option<TransitionResult>> {
        let id = match smql_storage::InstanceId::from_string(instance_id) {
            Ok(id) => id,
            Err(_) => return Ok(None), // Invalid ID, ignore
        };

        let instance = match self.storage.get_instance(&id).await? {
            Some(inst) => inst,
            None => return Ok(None), // Instance deleted, ignore
        };

        // Race condition: instance already moved to a different state
        if instance.state != expected_from_state {
            return Ok(None);
        }

        // Build mutations (none for timeout transitions)
        let mutations = Vec::new();

        // Create trail entry marked as TIMEOUT
        let trail_entry = TrailEntry {
            instance_id: id.clone(),
            machine: instance.machine.clone(),
            sequence: instance.trail_length + 1,
            from_state: instance.state.clone(),
            to_state: target_state.to_string(),
            transition_name: Some("TIMEOUT".to_string()),
            actor: Some("System".to_string()),
            memo: Some(format!(
                "Timeout expired: {} -> {}",
                expected_from_state, target_state
            )),
            timestamp: Utc::now(),
            data_snapshot: None,
        };

        // Atomic transition
        self.storage
            .transition_instance(&id, instance.version, target_state, &mutations, trail_entry)
            .await?;

        // Remove fired timer from storage
        let _ = self
            .storage
            .remove_timer(instance_id, expected_from_state)
            .await;

        // --- Fire hooks for timeout transition ---
        if let Ok(machine_def) = self.catalog.get(&instance.machine) {
            let hook_ctx = HookContext {
                instance_id: instance_id.to_string(),
                machine: instance.machine.clone(),
                from_state: instance.state.clone(),
                to_state: target_state.to_string(),
                data: instance.data.clone(),
                actor: Some("System".to_string()),
                memo: None,
            };
            let eval_ctx = EvalContext::new(instance.data.clone(), instance.state.clone());
            let resolved = self.resolve_hooks_actions(&machine_def.hooks, &eval_ctx);

            // ON EXIT(old_state)
            let _ = self
                .hook_executor
                .fire_hooks(
                    &machine_def.hooks,
                    &HookTrigger::OnExit(instance.state.clone()),
                    &hook_ctx,
                    &resolved,
                )
                .await;

            // Register new timeout if needed
            for t in &machine_def.transitions {
                let matches_source = match &t.from {
                    TransitionSource::State(s) => s == target_state,
                    _ => false,
                };
                if matches_source {
                    if let Some(timeout) = &t.timeout {
                        self.timer_manager.register(
                            instance_id,
                            &instance.machine,
                            target_state,
                            &timeout.duration,
                            &timeout.target_state,
                        );
                        // Persist new timer to storage
                        if let Some(entry) = self.timer_manager.get_timer(instance_id, target_state)
                        {
                            let stored = smql_storage::StoredTimer {
                                instance_id: instance_id.to_string(),
                                machine: instance.machine.clone(),
                                from_state: target_state.to_string(),
                                target_state: timeout.target_state.clone(),
                                deadline: entry.deadline,
                                registered_at: entry.registered_at,
                            };
                            let _ = self.storage.store_timer(&stored).await;
                        }
                        break; // Only one timeout per state
                    }
                }
            }

            // ON ENTER(new_state)
            let _ = self
                .hook_executor
                .fire_hooks(
                    &machine_def.hooks,
                    &HookTrigger::OnEnter(target_state.to_string()),
                    &hook_ctx,
                    &resolved,
                )
                .await;

            // AFTER EACH TRANSITION
            let _ = self
                .hook_executor
                .fire_hooks(
                    &machine_def.hooks,
                    &HookTrigger::AfterEachTransition,
                    &hook_ctx,
                    &resolved,
                )
                .await;
        } else {
            // Machine not in catalog (shouldn't happen), just register timeouts
            if let Ok(machine_def) = self.catalog.get(&instance.machine) {
                for t in &machine_def.transitions {
                    let matches_source = match &t.from {
                        TransitionSource::State(s) => s == target_state,
                        _ => false,
                    };
                    if matches_source {
                        if let Some(timeout) = &t.timeout {
                            self.timer_manager.register(
                                instance_id,
                                &instance.machine,
                                target_state,
                                &timeout.duration,
                                &timeout.target_state,
                            );
                            // Persist new timer to storage
                            if let Some(entry) =
                                self.timer_manager.get_timer(instance_id, target_state)
                            {
                                let stored = smql_storage::StoredTimer {
                                    instance_id: instance_id.to_string(),
                                    machine: instance.machine.clone(),
                                    from_state: target_state.to_string(),
                                    target_state: timeout.target_state.clone(),
                                    deadline: entry.deadline,
                                    registered_at: entry.registered_at,
                                };
                                let _ = self.storage.store_timer(&stored).await;
                            }
                            break;
                        }
                    }
                }
            }
        }

        let updated = self
            .storage
            .get_instance(&id)
            .await?
            .ok_or_else(|| SmqlError::not_found("Instance", instance_id))?;

        tracing::info!("timeout transition fired");
        Ok(Some(TransitionResult {
            from_state: instance.state,
            to_state: target_state.to_string(),
            instance: updated,
        }))
    }

    /// Start the background timer loop that checks for expired timers.
    ///
    /// Returns a JoinHandle that can be used to cancel the loop.
    /// The loop runs every `check_interval` and fires timeout transitions.
    pub fn start_timer_loop(
        self: &Arc<Self>,
        check_interval: std::time::Duration,
    ) -> tokio::task::JoinHandle<()> {
        let engine = Arc::clone(self);
        tokio::spawn(async move {
            let mut interval = tokio::time::interval(check_interval);
            loop {
                interval.tick().await;
                let expired = engine.timer_manager.drain_expired();
                for entry in expired {
                    // Handle race condition: instance may have already transitioned
                    let _ = engine
                        .timeout_transition(
                            &entry.instance_id,
                            &entry.from_state,
                            &entry.target_state,
                        )
                        .await;
                }
            }
        })
    }

    /// Restore persisted timers from storage into the in-memory TimerManager.
    ///
    /// Call this on startup before `start_timer_loop()` to recover timers
    /// that were registered before a restart. Returns the number of timers restored.
    pub async fn restore_timers(&self) -> SmqlResult<usize> {
        let stored_timers = self.storage.load_all_timers().await?;
        let mut count = 0;
        for timer in &stored_timers {
            self.timer_manager.register_with_deadline(
                &timer.instance_id,
                &timer.machine,
                &timer.from_state,
                &timer.target_state,
                timer.deadline,
                timer.registered_at,
            );
            count += 1;
        }
        if count > 0 {
            tracing::info!(count, "restored timers from storage");
        }
        Ok(count)
    }

    // -----------------------------------------------------------------------
    // Hook / Action resolution helpers
    // -----------------------------------------------------------------------

    /// Resolve a list of AST Actions into ResolvedActions using the eval context.
    fn resolve_actions(&self, actions: &[Action], ctx: &EvalContext) -> Vec<ResolvedAction> {
        actions
            .iter()
            .filter_map(|action| self.resolve_action(action, ctx).ok())
            .collect()
    }

    /// Resolve a single AST Action into a ResolvedAction.
    fn resolve_action(&self, action: &Action, ctx: &EvalContext) -> SmqlResult<ResolvedAction> {
        match action {
            Action::Log(msg) => Ok(ResolvedAction::Log(msg.clone())),
            Action::Emit { event, payload } => {
                let resolved_payload = payload
                    .as_ref()
                    .map(|expr| eval_expr(expr, ctx))
                    .transpose()?;
                Ok(ResolvedAction::Emit {
                    event: event.clone(),
                    payload: resolved_payload,
                })
            }
            Action::Notify { target, event } => {
                let resolved_target = eval_expr(target, ctx)?;
                Ok(ResolvedAction::Notify {
                    target: resolved_target,
                    event: event.clone(),
                })
            }
            Action::Webhook { url, payload } => {
                let resolved_payload = payload
                    .as_ref()
                    .map(|expr| eval_expr(expr, ctx))
                    .transpose()?;
                Ok(ResolvedAction::Webhook {
                    url: url.clone(),
                    payload: resolved_payload,
                })
            }
            Action::SpawnChild { machine, data } => {
                let resolved_data: SmqlResult<Vec<(String, Value)>> = data
                    .iter()
                    .map(|(k, expr)| {
                        let val = eval_expr(expr, ctx)?;
                        Ok((k.clone(), val))
                    })
                    .collect();
                Ok(ResolvedAction::SpawnChild {
                    machine: machine.clone(),
                    data: resolved_data?,
                })
            }
            Action::SignalParent { target_state } => Ok(ResolvedAction::SignalParent {
                target_state: target_state.clone(),
            }),
        }
    }

    /// Resolve actions for all hooks in a machine definition.
    /// Returns a Vec parallel to the hooks slice, each containing the resolved actions.
    fn resolve_hooks_actions(
        &self,
        hooks: &[smql_ast::machine::HookDefinition],
        ctx: &EvalContext,
    ) -> Vec<Vec<ResolvedAction>> {
        hooks
            .iter()
            .map(|hook| self.resolve_actions(&hook.actions, ctx))
            .collect()
    }
}

// ---------------------------------------------------------------------------
// EngineCallback — allows hooks to spawn children / signal parent
// ---------------------------------------------------------------------------

/// Wrapper that holds an Arc<Engine> for use as EngineCallback.
/// We can't impl EngineCallback directly on Engine because we need Arc<Self>.
pub struct EngineCallbackImpl {
    pub catalog: Arc<MachineCatalog>,
    pub storage: Arc<dyn Storage>,
    pub timer_manager: Arc<TimerManager>,
    pub hook_executor: Arc<HookExecutor>,
}

#[async_trait::async_trait]
impl EngineCallback for EngineCallbackImpl {
    async fn spawn_child(
        &self,
        parent_instance_id: &str,
        machine: &str,
        data: Vec<(String, Value)>,
    ) -> Result<String, HookError> {
        let parent_id =
            smql_storage::InstanceId::from_string(parent_instance_id).map_err(|_| {
                HookError::ActionFailed {
                    message: format!("Invalid parent instance ID: {}", parent_instance_id),
                }
            })?;
        let parent = self
            .storage
            .get_instance(&parent_id)
            .await
            .map_err(|e| HookError::ActionFailed {
                message: format!("Failed to get parent: {}", e),
            })?
            .ok_or_else(|| HookError::ActionFailed {
                message: format!("Parent instance not found: {}", parent_instance_id),
            })?;

        let data_exprs: Vec<(String, smql_ast::expression::Expression)> = data
            .into_iter()
            .map(|(k, v)| {
                (
                    k,
                    smql_ast::expression::Expression::new(
                        smql_ast::expression::ExpressionKind::Literal(v),
                    ),
                )
            })
            .collect();

        let cmd = SpawnCommand {
            machine: machine.to_string(),
            data: data_exprs,
            then_transition: None,
            batch: false,
            batch_data: Vec::new(),
            parent_id: Some(parent_instance_id.to_string()),
            parent_machine: Some(parent.machine.clone()),
        };

        // Create a temporary engine to perform the spawn
        let engine = Engine {
            catalog: self.catalog.clone(),
            storage: self.storage.clone(),
            timer_manager: self.timer_manager.clone(),
            hook_executor: self.hook_executor.clone(),
        };
        let result = engine
            .spawn(&cmd)
            .await
            .map_err(|e| HookError::ActionFailed {
                message: format!("Failed to spawn child: {}", e),
            })?;
        Ok(result.instance.id.as_str())
    }

    async fn signal_parent(
        &self,
        child_instance_id: &str,
        target_state: &str,
    ) -> Result<(), HookError> {
        let child_id = smql_storage::InstanceId::from_string(child_instance_id).map_err(|_| {
            HookError::ActionFailed {
                message: format!("Invalid child instance ID: {}", child_instance_id),
            }
        })?;
        let child = self
            .storage
            .get_instance(&child_id)
            .await
            .map_err(|e| HookError::ActionFailed {
                message: format!("Failed to get child: {}", e),
            })?
            .ok_or_else(|| HookError::ActionFailed {
                message: format!("Child instance not found: {}", child_instance_id),
            })?;

        let parent_id = match &child.parent_id {
            Some(pid) => pid.clone(),
            None => return Ok(()), // No parent — no-op
        };

        let parent_machine = child.parent_machine.clone().unwrap_or_default();
        let cmd =
            TransitionCommand::new(parent_machine, parent_id.as_str(), target_state.to_string());
        let engine = Engine {
            catalog: self.catalog.clone(),
            storage: self.storage.clone(),
            timer_manager: self.timer_manager.clone(),
            hook_executor: self.hook_executor.clone(),
        };
        // Use try_transition so if the parent can't transition, we don't fail the hook
        let _ = engine
            .try_transition(&cmd)
            .await
            .map_err(|e| HookError::ActionFailed {
                message: format!("Failed to signal parent: {}", e),
            })?;
        Ok(())
    }
}

impl Engine {
    /// Wire up the engine callback on the hook executor.
    /// Call this after constructing an Arc<Engine> to enable SPAWN CHILD / SIGNAL PARENT.
    pub fn wire_callback(&self) {
        let cb = Arc::new(EngineCallbackImpl {
            catalog: self.catalog.clone(),
            storage: self.storage.clone(),
            timer_manager: self.timer_manager.clone(),
            hook_executor: self.hook_executor.clone(),
        });
        self.hook_executor.set_callback(cb);
    }

    /// Populate the EvalContext with children and parent data for composition guards.
    async fn populate_composition_context(
        &self,
        ctx: &mut EvalContext,
        instance: &Instance,
        machine_def: &MachineDefinition,
    ) {
        // Populate children for each child definition in the machine
        for child_def in &machine_def.children {
            let children = self
                .storage
                .find_children(&instance.id, Some(&child_def.machine))
                .await
                .unwrap_or_default();

            let child_infos: Vec<ChildInfo> = children
                .into_iter()
                .map(|c| ChildInfo {
                    id: c.id.as_str(),
                    machine: c.machine,
                    state: c.state,
                    data: c.data,
                })
                .collect();

            ctx.children.insert(child_def.name.clone(), child_infos);
        }

        // Populate parent data if this instance has a parent
        if let Some(parent_id) = &instance.parent_id {
            if let Ok(Some(parent)) = self.storage.get_instance(parent_id).await {
                ctx.parent_data = Some(parent.data);
                ctx.parent_state = Some(parent.state);
            }
        }
    }
}

/// Convert a DefaultValue to a runtime Value.
fn default_to_value(default: &DefaultValue) -> Value {
    match default {
        DefaultValue::String(s) => Value::Text(s.clone()),
        DefaultValue::Int(v) => Value::Int(*v),
        DefaultValue::Float(v) => Value::Float(*v),
        DefaultValue::Bool(v) => Value::Bool(*v),
        DefaultValue::EmptySet => Value::Set(Vec::new()),
        DefaultValue::EmptyList => Value::List(Vec::new()),
        DefaultValue::EmptyMap => Value::Map(std::collections::BTreeMap::new()),
        DefaultValue::Null => Value::Null,
    }
}

use chrono::{DateTime, Utc};
use smql_ast::expression::{BinaryOperator, Expression, ExpressionKind, UnaryOperator};
use smql_ast::value::{SmqlDuration, Value};
use smql_ast::{SmqlError, SmqlResult};
use std::collections::HashMap;

/// Information about a child instance (for composition guards).
#[derive(Debug, Clone)]
pub struct ChildInfo {
    pub id: String,
    pub machine: String,
    pub state: String,
    pub data: HashMap<String, Value>,
}

/// Context for evaluating expressions during transitions and guards.
pub struct EvalContext {
    /// Instance data fields
    pub data: HashMap<String, Value>,
    /// Current state of the instance
    pub state: String,
    /// Actor performing the transition (optional)
    pub actor: Option<ActorInfo>,
    /// When the instance entered the current state
    pub state_entered_at: DateTime<Utc>,
    /// When the instance was created
    pub created_at: DateTime<Utc>,
    /// Current timestamp
    pub now: DateTime<Utc>,
    /// Time remaining until timeout fires (None if no active timeout)
    pub timeout_remaining: Option<chrono::TimeDelta>,
    /// Child instances grouped by child ref name (for composition)
    pub children: HashMap<String, Vec<ChildInfo>>,
    /// Parent's data fields (if this instance has a parent)
    pub parent_data: Option<HashMap<String, Value>>,
    /// Parent's state (if this instance has a parent)
    pub parent_state: Option<String>,
}

/// Information about the actor performing a transition.
#[derive(Debug, Clone)]
pub struct ActorInfo {
    pub id: String,
    pub role: Option<String>,
    pub fields: HashMap<String, Value>,
}

impl EvalContext {
    pub fn new(data: HashMap<String, Value>, state: String) -> Self {
        let now = Utc::now();
        Self {
            data,
            state,
            actor: None,
            state_entered_at: now,
            created_at: now,
            now,
            timeout_remaining: None,
            children: HashMap::new(),
            parent_data: None,
            parent_state: None,
        }
    }
}

/// Evaluate an expression against a context, returning a Value.
pub fn eval_expr(expr: &Expression, ctx: &EvalContext) -> SmqlResult<Value> {
    match &expr.kind {
        ExpressionKind::Literal(v) => Ok(v.clone()),

        ExpressionKind::DurationLiteral(d) => Ok(Value::Duration(d.clone())),

        ExpressionKind::FieldAccess(path) => {
            if path.is_empty() {
                return Ok(Value::Null);
            }
            // Check if first path segment is a child ref name
            if path.len() >= 2 {
                if let Some(children) = ctx.children.get(&path[0]) {
                    let field = &path[1];
                    if field.to_uppercase() == "STATE" {
                        // child_ref.STATE — returns the state of the first child (or Null)
                        return Ok(children
                            .first()
                            .map(|c| Value::Text(c.state.clone()))
                            .unwrap_or(Value::Null));
                    }
                    if field == "count" {
                        return Ok(Value::Int(children.len() as i64));
                    }
                    // Access a data field on the first child
                    if let Some(child) = children.first() {
                        let mut current = child.data.get(field).cloned().unwrap_or(Value::Null);
                        for segment in &path[2..] {
                            current = access_field(&current, segment);
                        }
                        return Ok(current);
                    }
                    return Ok(Value::Null);
                }
                // Check PARENT access
                if path[0].to_uppercase() == "PARENT" {
                    let field = &path[1];
                    if field.to_uppercase() == "STATE" {
                        return Ok(ctx
                            .parent_state
                            .as_ref()
                            .map(|s| Value::Text(s.clone()))
                            .unwrap_or(Value::Null));
                    }
                    if let Some(parent_data) = &ctx.parent_data {
                        let mut current = parent_data.get(field).cloned().unwrap_or(Value::Null);
                        for segment in &path[2..] {
                            current = access_field(&current, segment);
                        }
                        return Ok(current);
                    }
                    return Ok(Value::Null);
                }
            }
            let mut current = ctx.data.get(&path[0]).cloned().unwrap_or(Value::Null);
            for segment in &path[1..] {
                current = access_field(&current, segment);
            }
            Ok(current)
        }

        ExpressionKind::SelfRef => {
            // SELF returns the full data map
            let map = ctx
                .data
                .iter()
                .map(|(k, v)| (k.clone(), v.clone()))
                .collect();
            Ok(Value::Map(map))
        }

        ExpressionKind::ActorRef => {
            if let Some(actor) = &ctx.actor {
                let mut map = std::collections::BTreeMap::new();
                map.insert("id".to_string(), Value::Text(actor.id.clone()));
                if let Some(role) = &actor.role {
                    map.insert("role".to_string(), Value::Text(role.clone()));
                }
                for (k, v) in &actor.fields {
                    map.insert(k.clone(), v.clone());
                }
                Ok(Value::Map(map))
            } else {
                Ok(Value::Null)
            }
        }

        ExpressionKind::QualifiedAccess { root, path } => {
            let root_val = eval_expr(root, ctx)?;
            let mut current = root_val;
            for segment in path {
                current = access_field(&current, segment);
            }
            Ok(current)
        }

        ExpressionKind::BinaryOp { left, op, right } => {
            let left_val = eval_expr(left, ctx)?;
            let right_val = eval_expr(right, ctx)?;
            eval_binary_op(&left_val, *op, &right_val)
        }

        ExpressionKind::UnaryOp { op, operand } => {
            let val = eval_expr(operand, ctx)?;
            eval_unary_op(*op, &val)
        }

        ExpressionKind::FunctionCall { name, args } => eval_function(name, args, ctx),

        ExpressionKind::StateIs(state_name) => Ok(Value::Bool(ctx.state == *state_name)),

        ExpressionKind::StateIn(states) => Ok(Value::Bool(states.contains(&ctx.state))),

        ExpressionKind::IsSet(inner) => {
            let val = eval_expr(inner, ctx)?;
            Ok(Value::Bool(!matches!(val, Value::Null)))
        }

        ExpressionKind::IsNotSet(inner) => {
            let val = eval_expr(inner, ctx)?;
            Ok(Value::Bool(matches!(val, Value::Null)))
        }

        ExpressionKind::InSet { expr, values } => {
            let val = eval_expr(expr, ctx)?;
            let mut found = false;
            for v in values {
                let member = eval_expr(v, ctx)?;
                if val == member {
                    found = true;
                    break;
                }
            }
            Ok(Value::Bool(found))
        }

        ExpressionKind::InList { expr, values } => {
            let val = eval_expr(expr, ctx)?;
            let mut found = false;
            for v in values {
                let member = eval_expr(v, ctx)?;
                if val == member {
                    found = true;
                    break;
                }
            }
            Ok(Value::Bool(found))
        }

        ExpressionKind::All {
            collection,
            predicate,
        } => {
            let children = resolve_children_from_expr(collection, ctx);
            if children.is_empty() {
                // ALL over empty collection is vacuously true
                return Ok(Value::Bool(true));
            }
            for child in &children {
                let child_ctx = make_child_eval_context(child, ctx);
                let result = eval_expr(predicate, &child_ctx)?;
                if !is_truthy(&result) {
                    return Ok(Value::Bool(false));
                }
            }
            Ok(Value::Bool(true))
        }

        ExpressionKind::Any {
            collection,
            predicate,
        } => {
            let children = resolve_children_from_expr(collection, ctx);
            for child in &children {
                let child_ctx = make_child_eval_context(child, ctx);
                let result = eval_expr(predicate, &child_ctx)?;
                if is_truthy(&result) {
                    return Ok(Value::Bool(true));
                }
            }
            Ok(Value::Bool(false))
        }

        ExpressionKind::Count(inner) => {
            match inner {
                Some(expr) => {
                    // Check if inner expression refers to a children collection
                    if let ExpressionKind::FieldAccess(path) = &expr.kind {
                        if path.len() == 1 {
                            if let Some(children) = ctx.children.get(&path[0]) {
                                return Ok(Value::Int(children.len() as i64));
                            }
                        }
                    }
                    let val = eval_expr(expr, ctx)?;
                    match val {
                        Value::List(items) => Ok(Value::Int(items.len() as i64)),
                        Value::Set(items) => Ok(Value::Int(items.len() as i64)),
                        _ => Ok(Value::Int(0)),
                    }
                }
                None => Ok(Value::Int(0)),
            }
        }

        ExpressionKind::SignalFrom { machine, condition } => {
            // Find children matching the given machine name
            for children in ctx.children.values() {
                for child in children {
                    if child.machine == *machine {
                        let child_ctx = make_child_eval_context(child, ctx);
                        let result = eval_expr(condition, &child_ctx)?;
                        if is_truthy(&result) {
                            return Ok(Value::Bool(true));
                        }
                    }
                }
            }
            Ok(Value::Bool(false))
        }

        ExpressionKind::Pattern(regex_str) => {
            // Return the pattern as a text value; comparison happens in binary ops
            Ok(Value::Text(regex_str.clone()))
        }
    }
}

/// Access a field on a Value (for dot-access chains).
fn access_field(value: &Value, field: &str) -> Value {
    match value {
        Value::Map(map) => map.get(field).cloned().unwrap_or(Value::Null),
        _ => Value::Null,
    }
}

/// Evaluate a binary operation.
fn eval_binary_op(left: &Value, op: BinaryOperator, right: &Value) -> SmqlResult<Value> {
    match op {
        BinaryOperator::And => Ok(Value::Bool(is_truthy(left) && is_truthy(right))),
        BinaryOperator::Or => Ok(Value::Bool(is_truthy(left) || is_truthy(right))),
        BinaryOperator::Eq => Ok(Value::Bool(values_equal(left, right))),
        BinaryOperator::NotEq => Ok(Value::Bool(!values_equal(left, right))),
        BinaryOperator::Lt => Ok(Value::Bool(
            compare_values(left, right) == Some(std::cmp::Ordering::Less),
        )),
        BinaryOperator::Gt => Ok(Value::Bool(
            compare_values(left, right) == Some(std::cmp::Ordering::Greater),
        )),
        BinaryOperator::LtEq => Ok(Value::Bool(matches!(
            compare_values(left, right),
            Some(std::cmp::Ordering::Less | std::cmp::Ordering::Equal)
        ))),
        BinaryOperator::GtEq => Ok(Value::Bool(matches!(
            compare_values(left, right),
            Some(std::cmp::Ordering::Greater | std::cmp::Ordering::Equal)
        ))),
        BinaryOperator::Add => eval_arithmetic_add(left, right),
        BinaryOperator::Sub => eval_arithmetic_sub(left, right),
        BinaryOperator::Mul => eval_arithmetic_mul(left, right),
        BinaryOperator::Div => eval_arithmetic_div(left, right),
    }
}

/// Evaluate a unary operation.
fn eval_unary_op(op: UnaryOperator, val: &Value) -> SmqlResult<Value> {
    match op {
        UnaryOperator::Not => Ok(Value::Bool(!is_truthy(val))),
        UnaryOperator::Neg => match val {
            Value::Int(v) => Ok(Value::Int(-v)),
            Value::Float(v) => Ok(Value::Float(-v)),
            _ => Err(SmqlError::GuardFailed {
                message: format!("Cannot negate value: {}", val),
                guard_expr: format!("-{}", val),
                actual_value: Some(val.to_string()),
                hint: None,
            }),
        },
    }
}

/// Check if a value is truthy.
fn is_truthy(val: &Value) -> bool {
    match val {
        Value::Bool(b) => *b,
        Value::Null => false,
        Value::Int(0) => false,
        Value::Text(s) if s.is_empty() => false,
        Value::List(items) if items.is_empty() => false,
        Value::Set(items) if items.is_empty() => false,
        _ => true,
    }
}

/// Compare two values for equality with type coercion.
fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        // Same-type comparison
        (Value::Int(a), Value::Int(b)) => a == b,
        (Value::Float(a), Value::Float(b)) => a == b,
        (Value::Text(a), Value::Text(b)) => a == b,
        (Value::Bool(a), Value::Bool(b)) => a == b,
        (Value::Null, Value::Null) => true,
        // Cross-type coercion
        (Value::Int(a), Value::Float(b)) => (*a as f64) == *b,
        (Value::Float(a), Value::Int(b)) => *a == (*b as f64),
        // Default: structural equality
        _ => a == b,
    }
}

/// Compare two values for ordering.
fn compare_values(a: &Value, b: &Value) -> Option<std::cmp::Ordering> {
    match (a, b) {
        (Value::Int(a), Value::Int(b)) => Some(a.cmp(b)),
        (Value::Float(a), Value::Float(b)) => a.partial_cmp(b),
        (Value::Int(a), Value::Float(b)) => (*a as f64).partial_cmp(b),
        (Value::Float(a), Value::Int(b)) => a.partial_cmp(&(*b as f64)),
        (Value::Text(a), Value::Text(b)) => Some(a.cmp(b)),
        (Value::DateTime(a), Value::DateTime(b)) => Some(a.cmp(b)),
        (Value::Date(a), Value::Date(b)) => Some(a.cmp(b)),
        (Value::Duration(a), Value::Duration(b)) => Some(a.cmp(b)),
        _ => None,
    }
}

fn eval_arithmetic_add(left: &Value, right: &Value) -> SmqlResult<Value> {
    match (left, right) {
        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a + b)),
        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a + b)),
        (Value::Int(a), Value::Float(b)) => Ok(Value::Float(*a as f64 + b)),
        (Value::Float(a), Value::Int(b)) => Ok(Value::Float(a + *b as f64)),
        (Value::Text(a), Value::Text(b)) => Ok(Value::Text(format!("{}{}", a, b))),
        (Value::Duration(a), Value::Duration(b)) => Ok(Value::Duration(
            SmqlDuration::from_seconds(a.seconds + b.seconds),
        )),
        _ => Err(SmqlError::GuardFailed {
            message: format!("Cannot add {} + {}", left, right),
            guard_expr: format!("{} + {}", left, right),
            actual_value: None,
            hint: None,
        }),
    }
}

fn eval_arithmetic_sub(left: &Value, right: &Value) -> SmqlResult<Value> {
    match (left, right) {
        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a - b)),
        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a - b)),
        (Value::Int(a), Value::Float(b)) => Ok(Value::Float(*a as f64 - b)),
        (Value::Float(a), Value::Int(b)) => Ok(Value::Float(a - *b as f64)),
        (Value::Duration(a), Value::Duration(b)) => Ok(Value::Duration(
            SmqlDuration::from_seconds(a.seconds.saturating_sub(b.seconds)),
        )),
        _ => Err(SmqlError::GuardFailed {
            message: format!("Cannot subtract {} - {}", left, right),
            guard_expr: format!("{} - {}", left, right),
            actual_value: None,
            hint: None,
        }),
    }
}

fn eval_arithmetic_mul(left: &Value, right: &Value) -> SmqlResult<Value> {
    match (left, right) {
        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a * b)),
        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a * b)),
        (Value::Int(a), Value::Float(b)) => Ok(Value::Float(*a as f64 * b)),
        (Value::Float(a), Value::Int(b)) => Ok(Value::Float(a * *b as f64)),
        _ => Err(SmqlError::GuardFailed {
            message: format!("Cannot multiply {} * {}", left, right),
            guard_expr: format!("{} * {}", left, right),
            actual_value: None,
            hint: None,
        }),
    }
}

fn eval_arithmetic_div(left: &Value, right: &Value) -> SmqlResult<Value> {
    match (left, right) {
        (Value::Int(_), Value::Int(0)) | (Value::Float(_), Value::Int(0)) => {
            Err(SmqlError::GuardFailed {
                message: "Division by zero".to_string(),
                guard_expr: format!("{} / {}", left, right),
                actual_value: None,
                hint: None,
            })
        }
        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a / b)),
        (Value::Float(a), Value::Float(b)) => {
            if *b == 0.0 {
                Err(SmqlError::GuardFailed {
                    message: "Division by zero".to_string(),
                    guard_expr: format!("{} / {}", left, right),
                    actual_value: None,
                    hint: None,
                })
            } else {
                Ok(Value::Float(a / b))
            }
        }
        (Value::Int(a), Value::Float(b)) => {
            if *b == 0.0 {
                Err(SmqlError::GuardFailed {
                    message: "Division by zero".to_string(),
                    guard_expr: format!("{} / {}", left, right),
                    actual_value: None,
                    hint: None,
                })
            } else {
                Ok(Value::Float(*a as f64 / b))
            }
        }
        (Value::Float(a), Value::Int(b)) => Ok(Value::Float(a / *b as f64)),
        _ => Err(SmqlError::GuardFailed {
            message: format!("Cannot divide {} / {}", left, right),
            guard_expr: format!("{} / {}", left, right),
            actual_value: None,
            hint: None,
        }),
    }
}

/// Evaluate a built-in function call.
fn eval_function(name: &str, args: &[Expression], ctx: &EvalContext) -> SmqlResult<Value> {
    match name.to_lowercase().as_str() {
        "elapsed" | "elapsed_in_state" => {
            let elapsed = ctx.now.signed_duration_since(ctx.state_entered_at);
            let seconds = elapsed.num_seconds().max(0) as u64;
            Ok(Value::Duration(SmqlDuration::from_seconds(seconds)))
        }

        "elapsed_since" => {
            // elapsed_since(state_name) — for now, same as elapsed()
            // Full implementation requires trail lookup
            let elapsed = ctx.now.signed_duration_since(ctx.state_entered_at);
            let seconds = elapsed.num_seconds().max(0) as u64;
            Ok(Value::Duration(SmqlDuration::from_seconds(seconds)))
        }

        "now" => Ok(Value::DateTime(ctx.now)),

        "today" => Ok(Value::Date(ctx.now.date_naive())),

        "timeout_remaining" => match &ctx.timeout_remaining {
            Some(remaining) => {
                let seconds = remaining.num_seconds().max(0) as u64;
                Ok(Value::Duration(SmqlDuration::from_seconds(seconds)))
            }
            None => Ok(Value::Null),
        },

        "count" => {
            if args.is_empty() {
                Ok(Value::Int(0))
            } else {
                let val = eval_expr(&args[0], ctx)?;
                match val {
                    Value::List(items) => Ok(Value::Int(items.len() as i64)),
                    Value::Set(items) => Ok(Value::Int(items.len() as i64)),
                    _ => Ok(Value::Int(0)),
                }
            }
        }

        "len" | "length" => {
            if args.is_empty() {
                return Ok(Value::Int(0));
            }
            let val = eval_expr(&args[0], ctx)?;
            match val {
                Value::Text(s) => Ok(Value::Int(s.len() as i64)),
                Value::List(items) => Ok(Value::Int(items.len() as i64)),
                Value::Set(items) => Ok(Value::Int(items.len() as i64)),
                _ => Ok(Value::Int(0)),
            }
        }

        "lower" | "lowercase" => {
            if args.is_empty() {
                return Ok(Value::Null);
            }
            let val = eval_expr(&args[0], ctx)?;
            match val {
                Value::Text(s) => Ok(Value::Text(s.to_lowercase())),
                other => Ok(other),
            }
        }

        "upper" | "uppercase" => {
            if args.is_empty() {
                return Ok(Value::Null);
            }
            let val = eval_expr(&args[0], ctx)?;
            match val {
                Value::Text(s) => Ok(Value::Text(s.to_uppercase())),
                other => Ok(other),
            }
        }

        "__map" => {
            // Internal: map literal { key: value, ... }
            // Args are alternating key (text literal), value pairs
            let mut map = std::collections::BTreeMap::new();
            let mut i = 0;
            while i + 1 < args.len() {
                let key = eval_expr(&args[i], ctx)?;
                let val = eval_expr(&args[i + 1], ctx)?;
                if let Value::Text(k) = key {
                    map.insert(k, val);
                }
                i += 2;
            }
            Ok(Value::Map(map))
        }

        _ => {
            // Unknown function — return Null for now
            Ok(Value::Null)
        }
    }
}

/// Resolve a collection expression to a list of child instances.
/// The collection is typically a FieldAccess like `items` referring to a child ref name.
fn resolve_children_from_expr<'a>(
    collection: &Expression,
    ctx: &'a EvalContext,
) -> Vec<&'a ChildInfo> {
    match &collection.kind {
        ExpressionKind::FieldAccess(path) if path.len() == 1 => {
            if let Some(children) = ctx.children.get(&path[0]) {
                children.iter().collect()
            } else {
                Vec::new()
            }
        }
        _ => Vec::new(),
    }
}

/// Create a temporary EvalContext for evaluating predicates against a child instance.
fn make_child_eval_context(child: &ChildInfo, parent_ctx: &EvalContext) -> EvalContext {
    EvalContext {
        data: child.data.clone(),
        state: child.state.clone(),
        actor: parent_ctx.actor.clone(),
        state_entered_at: parent_ctx.now, // Approximate
        created_at: parent_ctx.now,
        now: parent_ctx.now,
        timeout_remaining: None,
        children: HashMap::new(),
        parent_data: Some(parent_ctx.data.clone()),
        parent_state: Some(parent_ctx.state.clone()),
    }
}

/// Evaluate a guard expression and return whether it passes.
/// Returns the boolean result and the display string of the expression for error reporting.
pub fn eval_guard(expr: &Expression, ctx: &EvalContext) -> SmqlResult<bool> {
    let result = eval_expr(expr, ctx)?;
    Ok(is_truthy(&result))
}

