        let guard_expr = lit(Value::Float(0.1));
        assert!(eval_guard(&guard_expr, &ctx).unwrap());
    }

    #[test]
    fn truthy_duration_is_truthy() {
        let ctx = ctx_with_data(vec![]);
        let guard_expr = lit(Value::Duration(SmqlDuration::from_seconds(10)));
        assert!(eval_guard(&guard_expr, &ctx).unwrap());
    }
}

