#[cfg(test)]
mod coverage_timeout_tests {
    use crate::engine::Engine;
    use smql_ast::command::{SpawnCommand, TransitionCommand};
    use smql_ast::machine::*;
    use smql_ast::types::*;
    use smql_ast::value::SmqlDuration;
    use smql_catalog::MachineCatalog;
    use smql_storage::{MemoryStorage, Storage};
    use smql_timer::TimerManager;
    use std::sync::Arc;

    fn setup_engine_with_timer() -> (Engine, Arc<TimerManager>, Arc<dyn Storage>) {
        let catalog = Arc::new(MachineCatalog::new());
        let storage: Arc<dyn Storage> = Arc::new(MemoryStorage::new());
        let timer_manager = Arc::new(TimerManager::new());
        let engine = Engine::with_timer_manager(
            catalog,
            Arc::clone(&storage),
            Arc::clone(&timer_manager),
        );
        (engine, timer_manager, storage)
    }

    fn register_timeout_machine(engine: &Engine) {
        let mut m = MachineDefinition::new("TM".into(), "idle".into());
        m.states = vec![
            StateDefinition::new("idle".into()),
            StateDefinition::new("waiting".into()),
            StateDefinition::new("expired".into()),
            StateDefinition::new("done".into()),
        ];
        m.terminal_states = vec!["done".into()];
        m.data = vec![DataFieldDefinition {
            name: "label".into(),
            field_type: TypeDefinition::Text,
            constraints: vec![Constraint::Default(DefaultValue::String("test".into()))],
        }];

        let mut t1 =
            TransitionDefinition::new(TransitionSource::State("idle".into()), "waiting".into());
        t1.timeout = Some(TimeoutClause {
            duration: SmqlDuration::from_hours(1),
            target_state: "expired".into(),
        });

        let t2 =
            TransitionDefinition::new(TransitionSource::State("waiting".into()), "done".into());
        let t3 =
            TransitionDefinition::new(TransitionSource::State("expired".into()), "done".into());

        m.transitions = vec![t1, t2, t3];
        engine.catalog.register(m).unwrap();
    }

    fn spawn_cmd(machine: &str) -> SpawnCommand {
        SpawnCommand {
            machine: machine.to_string(),
            data: Vec::new(),
            then_transition: None,
            batch: false,
            batch_data: Vec::new(),
            parent_id: None,
            parent_machine: None,
        }
    }

    // --- timeout_transition with invalid ID format ---

    #[tokio::test]
    async fn timeout_transition_invalid_id_returns_none() {
        let (engine, _, _) = setup_engine_with_timer();
        register_timeout_machine(&engine);

        let result = engine
            .timeout_transition("not-a-valid-ulid!", "waiting", "expired")
            .await
            .unwrap();
        assert!(result.is_none());
    }

    // --- timeout_transition with deleted instance ---

    #[tokio::test]
    async fn timeout_transition_deleted_instance_returns_none() {
        let (engine, _, storage) = setup_engine_with_timer();
        register_timeout_machine(&engine);

        let spawned = engine.spawn(&spawn_cmd("TM")).await.unwrap();
        let id_str = spawned.instance.id.as_str();

        engine
            .transition(&TransitionCommand::new(
                "TM".into(),
                id_str.to_string(),
                "waiting".into(),
            ))
            .await
            .unwrap();

        // Delete the instance
        storage
            .delete_instance(&spawned.instance.id)
            .await
            .unwrap();

        // Timeout fires for a now-deleted instance
        let result = engine
            .timeout_transition(&id_str, "waiting", "expired")
            .await
            .unwrap();
        assert!(result.is_none());
    }

    // --- restore_timers ---

    #[tokio::test]
    async fn restore_timers_from_storage() {
        let (engine, timer_manager, storage) = setup_engine_with_timer();
        register_timeout_machine(&engine);

        let spawned = engine.spawn(&spawn_cmd("TM")).await.unwrap();
        let id_str = spawned.instance.id.as_str();

        // Transition to waiting (registers a timer and persists it)
        engine
            .transition(&TransitionCommand::new(
                "TM".into(),
                id_str.to_string(),
                "waiting".into(),
            ))
            .await
            .unwrap();

        assert_eq!(timer_manager.timer_count(), 1);

        // Verify timer was persisted to storage
        let stored = storage.load_all_timers().await.unwrap();
        assert_eq!(stored.len(), 1);
        assert_eq!(stored[0].instance_id, id_str);
        assert_eq!(stored[0].from_state, "waiting");
        assert_eq!(stored[0].target_state, "expired");

        // Create a new engine with a fresh TimerManager (simulating restart)
        let new_timer_manager = Arc::new(TimerManager::new());
        let new_engine = Engine::with_timer_manager(
            engine.catalog.clone(),
            storage.clone(),
            Arc::clone(&new_timer_manager),
        );
        assert_eq!(new_timer_manager.timer_count(), 0);

        // Restore timers
        let restored = new_engine.restore_timers().await.unwrap();
        assert_eq!(restored, 1);
        assert_eq!(new_timer_manager.timer_count(), 1);
    }

    // --- restore_timers with no stored timers ---

    #[tokio::test]
    async fn restore_timers_empty() {
        let (engine, _, _) = setup_engine_with_timer();
        register_timeout_machine(&engine);

        let restored = engine.restore_timers().await.unwrap();
        assert_eq!(restored, 0);
    }

    // --- timeout_transition persists removal of fired timer ---

    #[tokio::test]
    async fn timeout_transition_removes_timer_from_storage() {
        let (engine, _timer_manager, storage) = setup_engine_with_timer();
        register_timeout_machine(&engine);

        let spawned = engine.spawn(&spawn_cmd("TM")).await.unwrap();
        let id_str = spawned.instance.id.as_str();

        engine
            .transition(&TransitionCommand::new(
                "TM".into(),
                id_str.to_string(),
                "waiting".into(),
            ))
            .await
            .unwrap();

        // Timer is stored
        assert_eq!(storage.load_all_timers().await.unwrap().len(), 1);

        // Fire the timeout
        engine
            .timeout_transition(&id_str, "waiting", "expired")
            .await
            .unwrap();

        // Timer should be removed from storage
        assert_eq!(storage.load_all_timers().await.unwrap().len(), 0);
    }
}

// SMQL Hooks — Action/hook execution runtime

pub mod webhook;

use smql_ast::machine::{HookDefinition, HookTrigger};
use smql_ast::value::Value;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::broadcast;

pub use webhook::{WebhookClient, WebhookConfig};

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, thiserror::Error)]
pub enum HookError {
    #[error("Hook rejected transition: {reason}")]
    Rejected { reason: String },

    #[error("Action failed: {message}")]
    ActionFailed { message: String },

    #[error("Webhook failed: {url}: {message}")]
    WebhookFailed { url: String, message: String },
}

// ---------------------------------------------------------------------------
// HookContext — data passed into hook execution
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
pub struct HookContext {
    pub instance_id: String,
    pub machine: String,
    pub from_state: String,
    pub to_state: String,
    pub data: HashMap<String, Value>,
    pub actor: Option<String>,
    pub memo: Option<String>,
}

// ---------------------------------------------------------------------------
// ResolvedAction — actions with concrete Values (no expressions)
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
pub enum ResolvedAction {
    Notify {
        target: Value,
        event: String,
    },
    Log(String),
    Emit {
        event: String,
        payload: Option<Value>,
    },
    Webhook {
        url: String,
        payload: Option<Value>,
    },
    SpawnChild {
        machine: String,
        data: Vec<(String, Value)>,
    },
    SignalParent {
        target_state: String,
    },
}

// ---------------------------------------------------------------------------
// EngineCallback — trait for engine operations that hooks can trigger
// ---------------------------------------------------------------------------

#[async_trait::async_trait]
pub trait EngineCallback: Send + Sync {
    async fn spawn_child(
        &self,
        parent_instance_id: &str,
        machine: &str,
        data: Vec<(String, Value)>,
    ) -> Result<String, HookError>;

    async fn signal_parent(
        &self,
        child_instance_id: &str,
        target_state: &str,
    ) -> Result<(), HookError>;
}

// ---------------------------------------------------------------------------
// Event — published on the event bus
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
pub struct Event {
    pub name: String,
    pub instance_id: String,
    pub machine: String,
    pub payload: Option<Value>,
}

// ---------------------------------------------------------------------------
// EventBus — broadcast channel for EMIT actions
// ---------------------------------------------------------------------------

pub struct EventBus {
    sender: broadcast::Sender<Event>,
}

impl EventBus {
    pub fn new(capacity: usize) -> Self {
        let (sender, _) = broadcast::channel(capacity);
        Self { sender }
    }

    pub fn emit(&self, event: Event) {
        // Ignore error if no receivers
        let _ = self.sender.send(event);
    }

    pub fn subscribe(&self) -> broadcast::Receiver<Event> {
        self.sender.subscribe()
    }
}

impl Default for EventBus {
    fn default() -> Self {
        Self::new(256)
    }
}

// ---------------------------------------------------------------------------
// HookExecutor — orchestrates hook matching and action dispatch
// ---------------------------------------------------------------------------

pub struct HookExecutor {
    pub event_bus: Arc<EventBus>,
    callback: std::sync::RwLock<Option<Arc<dyn EngineCallback>>>,
    webhook_client: std::sync::RwLock<Option<Arc<WebhookClient>>>,
}

impl HookExecutor {
    pub fn new(event_bus: Arc<EventBus>) -> Self {
        Self {
            event_bus,
            callback: std::sync::RwLock::new(None),
            webhook_client: std::sync::RwLock::new(None),
        }
    }

    pub fn with_callback(event_bus: Arc<EventBus>, callback: Arc<dyn EngineCallback>) -> Self {
        Self {
            event_bus,
            callback: std::sync::RwLock::new(Some(callback)),
            webhook_client: std::sync::RwLock::new(None),
        }
    }

    pub fn set_callback(&self, callback: Arc<dyn EngineCallback>) {
        *self.callback.write().unwrap() = Some(callback);
    }

    /// Set the webhook HTTP client. When set, WEBHOOK actions make real HTTP POST requests.
    /// When not set, WEBHOOK actions are logged as dry-run.
    pub fn set_webhook_client(&self, client: Arc<WebhookClient>) {
        *self.webhook_client.write().unwrap() = Some(client);
    }

    /// Fire matching hooks for a trigger. Returns Err only if a BEFORE hook rejects.
    ///
    /// - BEFORE hooks: executed synchronously, can reject via HookError::Rejected
    /// - All other hooks: fire-and-forget (errors are logged, not propagated)
    pub async fn fire_hooks(
        &self,
        hooks: &[HookDefinition],
        trigger: &HookTrigger,
        ctx: &HookContext,
        resolved_actions_per_hook: &[Vec<ResolvedAction>],
    ) -> Result<(), HookError> {
        let is_before = matches!(trigger, HookTrigger::BeforeEachTransition);

        for (i, hook) in hooks.iter().enumerate() {
            if !trigger_matches(&hook.trigger, trigger) {
                continue;
            }

            let actions = resolved_actions_per_hook
                .get(i)
                .cloned()
                .unwrap_or_default();

            if is_before {
                // Synchronous: any error rejects the transition
                self.execute_actions(&actions, ctx).await?;
            } else {
                // Fire-and-forget: log errors but don't propagate
                if let Err(e) = self.execute_actions(&actions, ctx).await {
                    tracing::warn!(
                        hook_trigger = %hook.trigger,
                        instance_id = %ctx.instance_id,
                        error = %e,
                        "Hook action failed (fire-and-forget)"
                    );
                }
            }
        }
        Ok(())
    }

    /// Execute a list of resolved actions for a single hook or transition.
    pub async fn execute_actions(
        &self,
        actions: &[ResolvedAction],
        ctx: &HookContext,
    ) -> Result<(), HookError> {
        for action in actions {
            self.execute_action(action, ctx).await?;
        }
        Ok(())
    }

    /// Execute a single resolved action.
    async fn execute_action(
        &self,
        action: &ResolvedAction,
        ctx: &HookContext,
    ) -> Result<(), HookError> {
        match action {
            ResolvedAction::Log(message) => {
                let rendered = render_log_template(message, ctx);
                tracing::info!(
                    instance_id = %ctx.instance_id,
                    machine = %ctx.machine,
                    "LOG: {}", rendered
                );
                Ok(())
            }

            ResolvedAction::Emit { event, payload } => {
                self.event_bus.emit(Event {
                    name: event.clone(),
                    instance_id: ctx.instance_id.clone(),
                    machine: ctx.machine.clone(),
                    payload: payload.clone(),
                });
                tracing::debug!(
                    event = %event,
                    instance_id = %ctx.instance_id,
                    "EMIT event"
                );
                Ok(())
            }

            ResolvedAction::Notify { target, event } => {
                tracing::info!(
                    target = %target,
                    event = %event,
                    instance_id = %ctx.instance_id,
                    "NOTIFY (dry-run)"
                );
                Ok(())
            }

            ResolvedAction::Webhook { url, payload } => {
                let client = self.webhook_client.read().unwrap().clone();
                if let Some(client) = client {
                    match client.execute(url, ctx, payload.as_ref()).await {
                        Ok(()) => {
                            tracing::info!(
                                url = %url,
                                instance_id = %ctx.instance_id,
                                "WEBHOOK delivered"
                            );
                        }
                        Err(e) => {
                            tracing::warn!(
                                url = %url,
                                instance_id = %ctx.instance_id,
                                error = %e,
                                "WEBHOOK failed"
                            );
                            return Err(HookError::WebhookFailed {
                                url: url.clone(),
                                message: e.to_string(),
                            });
                        }
                    }
                } else {
                    tracing::info!(
                        url = %url,
                        instance_id = %ctx.instance_id,
                        has_payload = payload.is_some(),
                        "WEBHOOK (dry-run, no HTTP client)"
                    );
                }
                Ok(())
            }

            ResolvedAction::SpawnChild { machine, data } => {
                let cb = self.callback.read().unwrap().clone();
                if let Some(cb) = cb {
                    let child_id = cb
                        .spawn_child(&ctx.instance_id, machine, data.clone())
                        .await?;
                    tracing::info!(
                        parent = %ctx.instance_id,
                        child = %child_id,
                        machine = %machine,
                        "SPAWN CHILD"
                    );
                } else {
                    tracing::warn!(
                        instance_id = %ctx.instance_id,
                        machine = %machine,
                        "SPAWN CHILD skipped: no engine callback configured"
                    );
                }
                Ok(())
            }

            ResolvedAction::SignalParent { target_state } => {
                let cb = self.callback.read().unwrap().clone();
                if let Some(cb) = cb {
                    cb.signal_parent(&ctx.instance_id, target_state).await?;
                } else {
                    tracing::warn!(
                        instance_id = %ctx.instance_id,
                        target_state = %target_state,
                        "SIGNAL PARENT skipped: no engine callback configured"
                    );
                }
                Ok(())
            }
        }
    }
}

/// Check if a hook trigger matches the fired trigger.
fn trigger_matches(hook_trigger: &HookTrigger, fired: &HookTrigger) -> bool {
    match (hook_trigger, fired) {
        (HookTrigger::OnSpawn, HookTrigger::OnSpawn) => true,
        (HookTrigger::BeforeEachTransition, HookTrigger::BeforeEachTransition) => true,
        (HookTrigger::AfterEachTransition, HookTrigger::AfterEachTransition) => true,
        (HookTrigger::OnEnter(hook_state), HookTrigger::OnEnter(fired_state)) => {
            hook_state == fired_state
        }
        (HookTrigger::OnExit(hook_state), HookTrigger::OnExit(fired_state)) => {
            hook_state == fired_state
        }
        _ => false,
    }
}

/// Simple template rendering for LOG messages.
/// Replaces `{field}` with values from context data.
fn render_log_template(template: &str, ctx: &HookContext) -> String {
    let mut result = template.to_string();
    // Replace built-in variables
    result = result.replace("{instance_id}", &ctx.instance_id);
    result = result.replace("{machine}", &ctx.machine);
    result = result.replace("{from_state}", &ctx.from_state);
    result = result.replace("{to_state}", &ctx.to_state);
    if let Some(actor) = &ctx.actor {
        result = result.replace("{actor}", actor);
    }
    // Replace data fields
    for (key, value) in &ctx.data {
        let placeholder = format!("{{{}}}", key);
        result = result.replace(&placeholder, &value.to_string());
    }
    result
}

