use crate::common;
use crate::expr;
use crate::Parser;
use smql_ast::command::*;
use smql_ast::machine::TransitionDefinition;
use smql_ast::{SmqlError, SmqlResult};

/// Parse SPAWN Machine { field: value, ... } [THEN TRANSITION TO state].
pub fn parse_spawn(parser: &mut Parser) -> SmqlResult<Command> {
    parser.expect_keyword("SPAWN")?;

    // Check for SPAWN BATCH
    let batch = parser.try_keyword("BATCH");

    let machine_name = parser.expect_ident()?;

    if batch {
        // SPAWN BATCH Machine [ { ... }, { ... }, ... ]
        parser.expect_punct("[")?;
        let mut batch_data = Vec::new();
        while !parser.check_punct("]") {
            let data = parse_spawn_data(parser)?;
            batch_data.push(data);
            parser.try_punct(",");
        }
        parser.expect_punct("]")?;
        return Ok(Command::Spawn(SpawnCommand {
            machine: machine_name,
            data: Vec::new(),
            then_transition: None,
            batch: true,
            batch_data,
            parent_id: None,
            parent_machine: None,
        }));
    }

    let data = parse_spawn_data(parser)?;

    let then_transition = if parser.try_keyword("THEN") {
        parser.expect_keyword("TRANSITION")?;
        parser.expect_keyword("TO")?;
        Some(parser.expect_ident()?)
    } else {
        None
    };

    Ok(Command::Spawn(SpawnCommand {
        machine: machine_name,
        data,
        then_transition,
        batch: false,
        batch_data: Vec::new(),
        parent_id: None,
        parent_machine: None,
    }))
}

fn parse_spawn_data(
    parser: &mut Parser,
) -> SmqlResult<Vec<(String, smql_ast::expression::Expression)>> {
    parser.expect_punct("{")?;
    let mut data = Vec::new();
    while !parser.check_punct("}") {
        let field = parser.expect_ident()?;
        parser.expect_punct(":")?;
        let value = expr::parse_expression(parser)?;
        data.push((field, value));
        parser.try_punct(",");
    }
    parser.expect_punct("}")?;
    Ok(data)
}

/// Parse TRANSITION instance_id TO state [WITH { ... }] [MEMO "..."] [AS actor].
pub fn parse_transition(parser: &mut Parser) -> SmqlResult<Command> {
    parser.expect_keyword("TRANSITION")?;

    // Check for TRANSITION ALL Machine WHERE ... TO state
    if parser.check_keyword("ALL") {
        return parse_batch_transition(parser);
    }

    let machine_name = parser.expect_ident()?;
    let instance_id = parser.expect_ident_or_string()?;
    parser.expect_keyword("TO")?;
    let to_state = parser.expect_ident()?;

    let mut cmd = TransitionCommand::new(machine_name, instance_id, to_state);

    // Parse optional clauses
    loop {
        if parser.try_keyword("WITH") {
            cmd.with_data = parse_spawn_data(parser)?;
        } else if parser.try_keyword("MEMO") {
            cmd.memo = Some(common::parse_string_literal(parser)?);
        } else if parser.try_keyword("AS") {
            cmd.as_actor = Some(parser.expect_ident_or_string()?);
        } else if parser.try_keyword("THROUGH") {
            parser.expect_punct("[")?;
            while !parser.check_punct("]") {
                cmd.through.push(parser.expect_ident()?);
                parser.try_punct(",");
            }
            parser.expect_punct("]")?;
        } else if parser.try_keyword("OR_STAY") {
            cmd.or_stay = true;
        } else if parser.try_keyword("CASCADE") {
            cmd.cascade = true;
        } else {
            break;
        }
    }

    Ok(Command::Transition(cmd))
}

/// Parse TRY TRANSITION instance_id TO state ...
pub fn parse_try_transition(parser: &mut Parser) -> SmqlResult<Command> {
    parser.expect_keyword("TRY")?;
    parser.expect_keyword("TRANSITION")?;

    let machine_name = parser.expect_ident()?;
    let instance_id = parser.expect_ident_or_string()?;
    parser.expect_keyword("TO")?;
    let to_state = parser.expect_ident()?;

    let mut cmd = TransitionCommand::new(machine_name, instance_id, to_state);

    loop {
        if parser.try_keyword("WITH") {
            cmd.with_data = parse_spawn_data(parser)?;
        } else if parser.try_keyword("MEMO") {
            cmd.memo = Some(common::parse_string_literal(parser)?);
        } else if parser.try_keyword("AS") {
            cmd.as_actor = Some(parser.expect_ident_or_string()?);
        } else {
            break;
        }
    }

    Ok(Command::TryTransition(cmd))
}

fn parse_batch_transition(parser: &mut Parser) -> SmqlResult<Command> {
    parser.expect_keyword("ALL")?;
    let machine = parser.expect_ident()?;
    parser.expect_keyword("WHERE")?;
    let filter = expr::parse_expression(parser)?;
    parser.expect_keyword("TO")?;
    let to_state = parser.expect_ident()?;

    let mut cmd = BatchTransitionCommand {
        machine,
        filter,
        to_state,
        with_data: Vec::new(),
        memo: None,
        as_actor: None,
    };

    loop {
        if parser.try_keyword("WITH") {
            cmd.with_data = parse_spawn_data(parser)?;
        } else if parser.try_keyword("MEMO") {
            cmd.memo = Some(common::parse_string_literal(parser)?);
        } else if parser.try_keyword("AS") {
            cmd.as_actor = Some(parser.expect_ident()?);
        } else {
            break;
        }
    }

    Ok(Command::BatchTransition(cmd))
}

/// Parse ALTER MACHINE Name operations.
pub fn parse_alter_machine(parser: &mut Parser) -> SmqlResult<Command> {
    parser.expect_keyword("ALTER")?;
    parser.expect_keyword("MACHINE")?;
    let machine = parser.expect_ident()?;

    let mut operations = Vec::new();

    while !parser.is_eof() {
        if parser.try_keyword("ADD") {
            if parser.try_keyword("STATE") {
                let state = parser.expect_ident()?;
                operations.push(AlterOperation::AddState(state));
            } else if parser.try_keyword("TRANSITION") {
                // We'd need to parse a full transition definition here
                // For now, parse minimal: from -> to { ... }
                let from = parser.expect_ident()?;
                parser.expect_operator("->")?;
                let to = parser.expect_ident()?;
                let transition =
                    TransitionDefinition::new(smql_ast::machine::TransitionSource::State(from), to);
                operations.push(AlterOperation::AddTransition(transition));
            } else if parser.try_keyword("DATA") {
                let field = crate::machine::parse_data_field_from_alter(parser)?;
                let backfill = if parser.try_keyword("BACKFILL") {
                    Some(expr::parse_expression(parser)?)
                } else {
                    None
                };
                operations.push(AlterOperation::AddData { field, backfill });
            } else {
                return Err(SmqlError::parse(
                    "Expected STATE, TRANSITION, or DATA after ADD",
                ));
            }
        } else if parser.try_keyword("REMOVE") {
            if parser.try_keyword("STATE") {
                let state = parser.expect_ident()?;
                parser.expect_keyword("MIGRATE")?;
                parser.expect_keyword("TO")?;
                let migrate_to = parser.expect_ident()?;
                operations.push(AlterOperation::RemoveState { state, migrate_to });
            } else if parser.try_keyword("TRANSITION") {
                let from = parser.expect_ident()?;
                parser.expect_operator("->")?;
                let to = parser.expect_ident()?;
                operations.push(AlterOperation::RemoveTransition { from, to });
            } else if parser.try_keyword("DATA") {
                let field = parser.expect_ident()?;
                operations.push(AlterOperation::RemoveData(field));
            } else {
                return Err(SmqlError::parse(
                    "Expected STATE, TRANSITION, or DATA after REMOVE",
                ));
            }
        } else if parser.try_keyword("BACKFILL") {
            let field = parser.expect_ident()?;
            parser.expect_operator("=")?;
            let value = expr::parse_expression(parser)?;
            operations.push(AlterOperation::Backfill { field, value });
        } else {
            break;
        }
    }

    Ok(Command::AlterMachine(AlterMachineCommand {
        machine,
        operations,
    }))
}

use crate::lexer::TokenKind;
use crate::Parser;
use smql_ast::value::{SmqlDuration, Value};
use smql_ast::{SmqlError, SmqlResult, Span};

/// Parse a string literal, returning its contents.
pub fn parse_string_literal(parser: &mut Parser) -> SmqlResult<String> {
    let tok = parser.advance()?;
    match &tok.kind {
        TokenKind::StringLiteral(s) => Ok(s.clone()),
        _ => Err(SmqlError::ParseError {
            message: format!("Expected string literal, found '{}'", tok.text),
            span: Some(Span::new(tok.offset, tok.offset + tok.text.len())),
            hint: None,
        }),
    }
}

/// Parse an integer literal.
pub fn parse_int_literal(parser: &mut Parser) -> SmqlResult<i64> {
    let tok = parser.advance()?;
    match &tok.kind {
        TokenKind::IntLiteral(v) => Ok(*v),
        _ => Err(SmqlError::ParseError {
            message: format!("Expected integer, found '{}'", tok.text),
            span: Some(Span::new(tok.offset, tok.offset + tok.text.len())),
            hint: None,
        }),
    }
}

/// Parse a duration literal, returning seconds.
pub fn parse_duration(parser: &mut Parser) -> SmqlResult<SmqlDuration> {
    let tok = parser.advance()?;
    match &tok.kind {
        TokenKind::DurationLiteral(secs) => Ok(SmqlDuration::from_seconds(*secs)),
        _ => Err(SmqlError::ParseError {
            message: format!("Expected duration (e.g. 24h, 7d), found '{}'", tok.text),
            span: Some(Span::new(tok.offset, tok.offset + tok.text.len())),
            hint: Some(
                "Durations use suffixes: s (seconds), m (minutes), h (hours), d (days)".into(),
            ),
        }),
    }
}

/// Parse a literal value (string, int, float, bool, null).
pub fn parse_literal_value(parser: &mut Parser) -> SmqlResult<Value> {
    match parser.peek_kind() {
        Some(TokenKind::StringLiteral(_)) => {
            let s = parse_string_literal(parser)?;
            Ok(Value::Text(s))
        }
        Some(TokenKind::IntLiteral(_)) => {
            let v = parse_int_literal(parser)?;
            Ok(Value::Int(v))
        }
        Some(TokenKind::FloatLiteral(_)) => {
            let tok = parser.advance()?;
            if let TokenKind::FloatLiteral(v) = tok.kind {
                Ok(Value::Float(v))
            } else {
                unreachable!()
            }
        }
        Some(TokenKind::Keyword(k)) if k == "TRUE" => {
            parser.advance()?;
            Ok(Value::Bool(true))
        }
        Some(TokenKind::Keyword(k)) if k == "FALSE" => {
            parser.advance()?;
            Ok(Value::Bool(false))
        }
        Some(TokenKind::Keyword(k)) if k == "NULL" => {
            parser.advance()?;
            Ok(Value::Null)
        }
        _ => {
            let tok = parser.peek();
            let msg = match tok {
                Some(t) => format!("Expected literal value, found '{}'", t.text),
                None => "Expected literal value, found end of input".to_string(),
            };
            Err(SmqlError::parse(msg))
        }
    }
}

/// Parse a comma-separated list of identifiers within braces: { a, b, c }.
pub fn parse_ident_set(parser: &mut Parser) -> SmqlResult<Vec<String>> {
    parser.expect_punct("{")?;
    let mut items = Vec::new();
    while !parser.check_punct("}") {
        let name = parser.expect_ident()?;
        items.push(name);
        if !parser.try_punct(",") {
            break;
        }
    }
    parser.expect_punct("}")?;
    Ok(items)
}

/// Parse a comma-separated list of identifiers in parens: ( a, b, c ) — returns strings.
pub fn parse_ident_list_parens(parser: &mut Parser) -> SmqlResult<Vec<String>> {
    parser.expect_punct("(")?;
    let mut items = Vec::new();
    while !parser.check_punct(")") {
        // Could be identifier or string
        match parser.peek_kind() {
            Some(TokenKind::StringLiteral(_)) => {
                let s = parse_string_literal(parser)?;
                items.push(s);
            }
            _ => {
                let name = parser.expect_ident()?;
                items.push(name);
            }
        }
        if !parser.try_punct(",") {
            break;
        }
    }
    parser.expect_punct(")")?;
    Ok(items)
}

/// Check if the next token sequence is `IS SET`.
pub fn check_is_set(parser: &Parser) -> bool {
    if let Some(TokenKind::Keyword(k)) = parser.peek_kind() {
        if k == "IS" {
            if let Some(t2) = parser.peek_nth(1) {
                if let TokenKind::Keyword(k2) = &t2.kind {
                    return k2 == "SET";
                }
            }
        }
    }
    false
}

/// Check if the next token sequence is `IS NOT SET` or `IS NULL`.
pub fn check_is_not_set(parser: &Parser) -> bool {
    if let Some(TokenKind::Keyword(k)) = parser.peek_kind() {
        if k == "IS" {
            if let Some(t2) = parser.peek_nth(1) {
                if let TokenKind::Keyword(k2) = &t2.kind {
                    if k2 == "NOT" {
                        if let Some(t3) = parser.peek_nth(2) {
                            if let TokenKind::Keyword(k3) = &t3.kind {
                                return k3 == "SET";
                            }
                        }
                    } else if k2 == "NULL" {
                        return true;
                    }
                }
            }
        }
    }
    false
}

use crate::common;
use crate::lexer::TokenKind;
use crate::Parser;
use smql_ast::expression::*;
use smql_ast::value::Value;
use smql_ast::{SmqlError, SmqlResult};

/// Parse a full expression (entry point for guards and WHERE clauses).
pub fn parse_expression(parser: &mut Parser) -> SmqlResult<Expression> {
    parse_or_expr(parser)
}

/// OR has lowest precedence.
fn parse_or_expr(parser: &mut Parser) -> SmqlResult<Expression> {
    let mut left = parse_and_expr(parser)?;
    while parser.try_keyword("OR") {
        let right = parse_and_expr(parser)?;
        left = Expression::new(ExpressionKind::BinaryOp {
            left: Box::new(left),
            op: BinaryOperator::Or,
            right: Box::new(right),
        });
    }
    Ok(left)
}

/// AND.
fn parse_and_expr(parser: &mut Parser) -> SmqlResult<Expression> {
    let mut left = parse_not_expr(parser)?;
    while parser.try_keyword("AND") {
        let right = parse_not_expr(parser)?;
        left = Expression::new(ExpressionKind::BinaryOp {
            left: Box::new(left),
            op: BinaryOperator::And,
            right: Box::new(right),
        });
    }
    Ok(left)
}

/// NOT (unary prefix).
fn parse_not_expr(parser: &mut Parser) -> SmqlResult<Expression> {
    if parser.try_keyword("NOT") {
        let operand = parse_comparison(parser)?;
        Ok(Expression::new(ExpressionKind::UnaryOp {
            op: UnaryOperator::Not,
            operand: Box::new(operand),
        }))
    } else {
        parse_comparison(parser)
    }
}

/// Comparison operators: ==, !=, <, >, <=, >=, IS SET, IS NOT SET, IN.
fn parse_comparison(parser: &mut Parser) -> SmqlResult<Expression> {
    let left = parse_addition(parser)?;

    // IS SET / IS NOT SET / IS NULL
    if common::check_is_not_set(parser) {
        parser.expect_keyword("IS")?;
        if parser.try_keyword("NOT") {
            parser.expect_keyword("SET")?;
        } else {
            parser.expect_keyword("NULL")?;
        }
        return Ok(Expression::new(ExpressionKind::IsNotSet(Box::new(left))));
    }
    if common::check_is_set(parser) {
        parser.expect_keyword("IS")?;
        parser.expect_keyword("SET")?;
        return Ok(Expression::new(ExpressionKind::IsSet(Box::new(left))));
    }

    // IN { ... } or IN ( ... )
    if parser.check_keyword("IN") {
        parser.expect_keyword("IN")?;
        if parser.check_punct("{") {
            parser.expect_punct("{")?;
            let mut values = Vec::new();
            while !parser.check_punct("}") {
                values.push(parse_expression(parser)?);
                if !parser.try_punct(",") {
                    break;
                }
            }
            parser.expect_punct("}")?;
            return Ok(Expression::new(ExpressionKind::InSet {
                expr: Box::new(left),
                values,
            }));
        } else if parser.check_punct("(") {
            parser.expect_punct("(")?;
            let mut values = Vec::new();
            while !parser.check_punct(")") {
                values.push(parse_expression(parser)?);
                if !parser.try_punct(",") {
                    break;
                }
            }
            parser.expect_punct(")")?;
            return Ok(Expression::new(ExpressionKind::InList {
                expr: Box::new(left),
                values,
            }));
        }
    }

    // Binary comparison operators
    if let Some(op) = try_parse_comparison_op(parser) {
        let right = parse_addition(parser)?;
        return Ok(Expression::new(ExpressionKind::BinaryOp {
            left: Box::new(left),
            op,
            right: Box::new(right),
        }));
    }

    Ok(left)
}

fn try_parse_comparison_op(parser: &mut Parser) -> Option<BinaryOperator> {
    if parser.try_operator("==") {
        return Some(BinaryOperator::Eq);
    }
    if parser.try_operator("!=") {
        return Some(BinaryOperator::NotEq);
    }
    if parser.try_operator(">=") {
        return Some(BinaryOperator::GtEq);
    }
    if parser.try_operator("<=") {
        return Some(BinaryOperator::LtEq);
    }
    if parser.try_operator(">") {
        return Some(BinaryOperator::Gt);
    }
    if parser.try_operator("<") {
        return Some(BinaryOperator::Lt);
    }
    None
}

/// Addition/subtraction.
fn parse_addition(parser: &mut Parser) -> SmqlResult<Expression> {
    let mut left = parse_multiplication(parser)?;
    loop {
        if parser.try_operator("+") {
            let right = parse_multiplication(parser)?;
            left = Expression::new(ExpressionKind::BinaryOp {
                left: Box::new(left),
                op: BinaryOperator::Add,
                right: Box::new(right),
            });
        } else if parser.check_operator("-") {
            // Need to distinguish minus operator from negative number
            // If next token after '-' is a number, it could be subtraction
            parser.advance()?;
            let right = parse_multiplication(parser)?;
            left = Expression::new(ExpressionKind::BinaryOp {
                left: Box::new(left),
                op: BinaryOperator::Sub,
                right: Box::new(right),
            });
        } else {
            break;
        }
    }
    Ok(left)
}

/// Multiplication/division.
fn parse_multiplication(parser: &mut Parser) -> SmqlResult<Expression> {
    let mut left = parse_unary(parser)?;
    loop {
        if parser.try_operator("*") {
            let right = parse_unary(parser)?;
            left = Expression::new(ExpressionKind::BinaryOp {
                left: Box::new(left),
                op: BinaryOperator::Mul,
                right: Box::new(right),
            });
        } else if parser.try_operator("/") {
            let right = parse_unary(parser)?;
            left = Expression::new(ExpressionKind::BinaryOp {
                left: Box::new(left),
                op: BinaryOperator::Div,
                right: Box::new(right),
            });
        } else {
            break;
        }
    }
    Ok(left)
}

/// Unary prefix: -, NOT (already handled above, so mainly negation).
fn parse_unary(parser: &mut Parser) -> SmqlResult<Expression> {
    parse_postfix(parser)
}

/// Postfix: dot access (a.b.c), and chained calls.
fn parse_postfix(parser: &mut Parser) -> SmqlResult<Expression> {
    let mut expr = parse_primary(parser)?;

    // Handle dot access chains
    while parser.check_punct(".") {
        // Don't consume the dot if this is a float being parsed
        parser.expect_punct(".")?;
        let field = parser.expect_ident()?;

        // If the base is a field access, extend the path
        match &expr.kind {
            ExpressionKind::FieldAccess(path) => {
                let mut new_path = path.clone();
                new_path.push(field);
                expr = Expression::new(ExpressionKind::FieldAccess(new_path));
            }
            ExpressionKind::SelfRef | ExpressionKind::ActorRef => {
                expr = Expression::new(ExpressionKind::QualifiedAccess {
                    root: Box::new(expr),
                    path: vec![field],
                });
            }
            ExpressionKind::QualifiedAccess { root, path } => {
                let mut new_path = path.clone();
                new_path.push(field);
                expr = Expression::new(ExpressionKind::QualifiedAccess {
                    root: root.clone(),
                    path: new_path,
                });
            }
            _ => {
                expr = Expression::new(ExpressionKind::QualifiedAccess {
                    root: Box::new(expr),
                    path: vec![field],
                });
            }
        }
    }

    Ok(expr)
}

/// Primary expressions: literals, identifiers, function calls, parenthesized, keywords.
fn parse_primary(parser: &mut Parser) -> SmqlResult<Expression> {
    // Map/object literal: { key: value, ... }
    if parser.check_punct("{") {
        parser.expect_punct("{")?;
        let mut entries = std::collections::BTreeMap::new();
        while !parser.check_punct("}") {
            let key = parser.expect_ident()?;
            parser.expect_punct(":")?;
            let value = parse_expression(parser)?;
            // For now, store as a nested expression; we'll evaluate to Value::Map at runtime
            entries.insert(key, value);
            parser.try_punct(",");
        }
        parser.expect_punct("}")?;
        // Convert to a Map value with expressions as children
        // For AST purposes, represent as a function-call-like construct
        let args: Vec<Expression> = entries
            .into_iter()
            .flat_map(|(k, v)| vec![Expression::new(ExpressionKind::Literal(Value::Text(k))), v])
            .collect();
        return Ok(Expression::new(ExpressionKind::FunctionCall {
            name: "__map".into(),
            args,
        }));
    }

    // Parenthesized expression
    if parser.check_punct("(") {
        parser.expect_punct("(")?;
        let expr = parse_expression(parser)?;
        parser.expect_punct(")")?;
        return Ok(expr);
    }

    // Duration literal
    if let Some(TokenKind::DurationLiteral(_)) = parser.peek_kind() {
        let d = common::parse_duration(parser)?;
        return Ok(Expression::new(ExpressionKind::DurationLiteral(d)));
    }

    // Numeric and string literals
    if let Some(TokenKind::IntLiteral(_)) = parser.peek_kind() {
        let v = common::parse_literal_value(parser)?;
        return Ok(Expression::new(ExpressionKind::Literal(v)));
    }
    if let Some(TokenKind::FloatLiteral(_)) = parser.peek_kind() {
        let v = common::parse_literal_value(parser)?;
        return Ok(Expression::new(ExpressionKind::Literal(v)));
    }
    if let Some(TokenKind::StringLiteral(_)) = parser.peek_kind() {
        let v = common::parse_literal_value(parser)?;
        return Ok(Expression::new(ExpressionKind::Literal(v)));
    }

    // Keywords that are expressions
    match parser.peek_kind() {
        Some(TokenKind::Keyword(k)) => {
            let kw = k.clone();
            match kw.as_str() {
                "TRUE" => {
                    parser.advance()?;
                    Ok(Expression::new(ExpressionKind::Literal(Value::Bool(true))))
                }
                "FALSE" => {
                    parser.advance()?;
                    Ok(Expression::new(ExpressionKind::Literal(Value::Bool(false))))
                }
                "NULL" => {
                    parser.advance()?;
                    Ok(Expression::new(ExpressionKind::Literal(Value::Null)))
                }
                "SELF" => {
                    parser.advance()?;
                    Ok(Expression::new(ExpressionKind::SelfRef))
                }
                "ACTOR" => {
                    parser.advance()?;
                    Ok(Expression::new(ExpressionKind::ActorRef))
                }
                "STATE" => {
                    parser.advance()?;
                    // STATE IS state_name or STATE IN { ... }
                    if parser.try_keyword("IS") {
                        let state = parser.expect_ident()?;
                        Ok(Expression::new(ExpressionKind::StateIs(state)))
                    } else if parser.try_keyword("IN") {
                        let states = common::parse_ident_set(parser)?;
                        Ok(Expression::new(ExpressionKind::StateIn(states)))
                    } else {
                        // Just "STATE" as a field reference
                        Ok(Expression::new(ExpressionKind::FieldAccess(vec![
                            "STATE".into()
                        ])))
                    }
                }
                "ALL" => {
                    parser.advance()?;
                    parser.expect_punct("(")?;
                    let collection = parse_expression(parser)?;
                    parser.expect_punct(",")?;
                    let predicate = parse_expression(parser)?;
                    parser.expect_punct(")")?;
                    Ok(Expression::new(ExpressionKind::All {
                        collection: Box::new(collection),
                        predicate: Box::new(predicate),
                    }))
                }
                "ANY" => {
                    parser.advance()?;
                    parser.expect_punct("(")?;
                    let collection = parse_expression(parser)?;
                    parser.expect_punct(",")?;
                    let predicate = parse_expression(parser)?;
                    parser.expect_punct(")")?;
                    Ok(Expression::new(ExpressionKind::Any {
                        collection: Box::new(collection),
                        predicate: Box::new(predicate),
                    }))
                }
                "COUNT" => {
                    parser.advance()?;
                    parser.expect_punct("(")?;
                    if parser.check_punct(")") {
                        parser.expect_punct(")")?;
                        Ok(Expression::new(ExpressionKind::Count(None)))
                    } else {
                        let expr = parse_expression(parser)?;
                        parser.expect_punct(")")?;
                        Ok(Expression::new(ExpressionKind::Count(Some(Box::new(expr)))))
                    }
                }
                "SIGNAL" => {
                    parser.advance()?;
                    parser.expect_keyword("FROM")?;
                    let machine = parser.expect_ident()?;
                    parser.expect_keyword("WHERE")?;
                    let condition = parse_expression(parser)?;
                    Ok(Expression::new(ExpressionKind::SignalFrom {
                        machine,
                        condition: Box::new(condition),
                    }))
                }
                "PATTERN" => {
                    parser.advance()?;
                    parser.expect_punct("(")?;
                    let regex = common::parse_string_literal(parser)?;
                    parser.expect_punct(")")?;
                    Ok(Expression::new(ExpressionKind::Pattern(regex)))
                }
                // Built-in functions (elapsed, NOW, TODAY, etc.)
                "NOW" | "TODAY" => {
                    let name = kw.to_lowercase();
                    parser.advance()?;
                    parser.expect_punct("(")?;
                    parser.expect_punct(")")?;
                    Ok(Expression::new(ExpressionKind::FunctionCall {
                        name,
                        args: vec![],
                    }))
                }
                // Functions that look like keywords
                _ => {
                    // Could be a function call if followed by (
                    // Use original text to preserve case for field names
                    let tok = parser.advance()?;
                    let name = tok.text.clone();
                    if parser.check_punct("(") {
                        parse_function_call_args(parser, name)
                    } else {
                        // Treat as field access / identifier
                        Ok(Expression::new(ExpressionKind::FieldAccess(vec![name])))
                    }
                }
            }
        }
        Some(TokenKind::Identifier(_)) => {
            let tok = parser.advance()?;
            let name = match &tok.kind {
                TokenKind::Identifier(s) => s.clone(),
                _ => unreachable!(),
            };
            // Check for function call
            if parser.check_punct("(") {
                parse_function_call_args(parser, name)
            } else {
                Ok(Expression::new(ExpressionKind::FieldAccess(vec![name])))
            }
        }
        _ => {
            let tok = parser.peek();
            let msg = match tok {
                Some(t) => format!("Expected expression, found '{}'", t.text),
                None => "Expected expression, found end of input".to_string(),
            };
            Err(SmqlError::parse(msg))
        }
    }
}

fn parse_function_call_args(parser: &mut Parser, name: String) -> SmqlResult<Expression> {
    parser.expect_punct("(")?;
    let mut args = Vec::new();
    while !parser.check_punct(")") {
        args.push(parse_expression(parser)?);
        if !parser.try_punct(",") {
            break;
        }
    }
    parser.expect_punct(")")?;
    Ok(Expression::new(ExpressionKind::FunctionCall { name, args }))
}

use smql_ast::{SmqlError, SmqlResult};

/// A single token from the SMQL input.
#[derive(Debug, Clone, PartialEq)]
pub struct Token {
    pub kind: TokenKind,
    pub text: String,
    pub offset: usize,
}

/// Token classification.
#[derive(Debug, Clone, PartialEq)]
pub enum TokenKind {
    Keyword(String),
    Identifier(String),
    StringLiteral(String),
    IntLiteral(i64),
    FloatLiteral(f64),
    DurationLiteral(u64), // seconds
    Operator(String),
    Punctuation(String),
}

/// All SMQL keywords (case-insensitive).
const KEYWORDS: &[&str] = &[
    "DEFINE",
    "MACHINE",
    "DATA",
    "STATES",
