    // IN () with single value
    #[test]
    fn parse_in_list_single() {
        let e = parse_expr("x IN (1)");
        match e.kind {
            ExpressionKind::InList { values, .. } => assert_eq!(values.len(), 1),
            _ => panic!("Expected InList"),
        }
    }

