    fn parser_expect_punct_wrong() {
        let tokens = lexer::tokenize("{").unwrap();
        let mut parser = Parser::new(&tokens, "{");
        let result = parser.expect_punct("}");
        assert!(result.is_err());
        let err = result.unwrap_err();
        assert!(err.to_string().contains("Expected '}'"));
    }

    // expect_operator with wrong operator
    #[test]
    fn parser_expect_operator_wrong() {
        let tokens = lexer::tokenize("==").unwrap();
        let mut parser = Parser::new(&tokens, "==");
        let result = parser.expect_operator("->");
        assert!(result.is_err());
        let err = result.unwrap_err();
        assert!(err.to_string().contains("Expected '->'"));
    }

    // peek_nth beyond tokens
    #[test]
    fn parser_peek_nth_beyond() {
        let tokens = lexer::tokenize("DEFINE").unwrap();
        let parser = Parser::new(&tokens, "DEFINE");
        assert!(parser.peek_nth(0).is_some());
        assert!(parser.peek_nth(1).is_none());
        assert!(parser.peek_nth(100).is_none());
    }

    // try_keyword returns false for non-match
    #[test]
    fn parser_try_keyword_false() {
        let tokens = lexer::tokenize("DEFINE").unwrap();
        let mut parser = Parser::new(&tokens, "DEFINE");
        assert!(!parser.try_keyword("MACHINE"));
        // Position should not advance
        assert_eq!(parser.peek().unwrap().text, "DEFINE");
    }

    // try_punct returns false for non-match
    #[test]
    fn parser_try_punct_false() {
        let tokens = lexer::tokenize("{").unwrap();
        let mut parser = Parser::new(&tokens, "{");
        assert!(!parser.try_punct("}"));
    }

    // try_operator returns false for non-match
    #[test]
    fn parser_try_operator_false() {
        let tokens = lexer::tokenize("==").unwrap();
        let mut parser = Parser::new(&tokens, "==");
        assert!(!parser.try_operator("!="));
    }

    // check methods on empty parser
    #[test]
    fn parser_check_on_empty() {
        let tokens = lexer::tokenize("").unwrap();
        let parser = Parser::new(&tokens, "");
        assert!(!parser.check_keyword("DEFINE"));
        assert!(!parser.check_punct("{"));
        assert!(!parser.check_operator("=="));
    }

    // current_offset at end of input
    #[test]
    fn parser_current_offset_at_eof() {
        let input = "DEFINE";
        let tokens = lexer::tokenize(input).unwrap();
        let mut parser = Parser::new(&tokens, input);
        parser.advance().unwrap();
        assert_eq!(parser.current_offset(), input.len());
    }

    // current_offset at start
    #[test]
    fn parser_current_offset_at_start() {
        let input = "DEFINE MACHINE";
        let tokens = lexer::tokenize(input).unwrap();
        let parser = Parser::new(&tokens, input);
        assert_eq!(parser.current_offset(), 0);
    }

    // expect_ident with keyword: should return original text
    #[test]
    fn parser_expect_ident_keyword_returns_text() {
        let tokens = lexer::tokenize("count").unwrap();
        let mut parser = Parser::new(&tokens, "count");
        // "count" is lexed as Keyword("COUNT") but text is "count"
        let name = parser.expect_ident().unwrap();
        assert_eq!(name, "count");
    }
}

//! Basic SDK example: connect to a server, define a machine, spawn, transition, query.
//!
//! Prerequisites: start the SMQL server first:
//!   cargo run --bin smql -- serve
//!
//! Then run this example:
//!   cargo run --example sdk_basic

use smql_sdk::prelude::*;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let client = SmqlClient::new("http://localhost:4200")?;

    // Check health
    let healthy = client.health().await?;
    println!("Server healthy: {}", healthy);

    // Define a task machine
    client
        .define_machine(
            r#"DEFINE MACHINE task (
                DATA {
                    title : TEXT
                    owner : TEXT -> OPTIONAL
                }
                STATES { todo, in_progress, done }
                INITIAL STATE todo
                TERMINAL STATES { done }
                TRANSITIONS {
                    todo -> in_progress {}
                    in_progress -> done {}
                }
            )"#,
        )
        .await?;
    println!("Machine 'task' defined.");

    // List machines
    let machines = client.list_machines().await?;
    println!("Machines: {:?}", machines);

    // Spawn instances
    let t1 = client
        .spawn("task", serde_json::json!({"title": "Write docs"}))
        .await?;
    println!("Spawned task: {} (state: {})", t1.id, t1.state);

    let t2 = client
        .spawn("task", serde_json::json!({"title": "Write tests"}))
        .await?;
    println!("Spawned task: {} (state: {})", t2.id, t2.state);

    // Transition t1
    let tr = client
        .transition("task", &t1.id, "in_progress", TransitionOptions::default())
        .await?;
    println!("Transitioned {} -> {}", tr.from_state, tr.to_state);

    // Find all todo tasks
    let todos = client.find("task").in_state("todo").execute().await?;
    println!("Found {} tasks in 'todo' state", todos.len());

    // Get trail
    let trail = client.trail(&t1.id).await?;
    println!("Trail for {}: {} entries", t1.id, trail.len());

    // Aggregate
    let agg = client
        .aggregate("task")
        .measure("COUNT()")
        .group_by_state()
        .execute()
        .await?;
    println!("Aggregate: {}", serde_json::to_string_pretty(&agg)?);

    println!("Done!");
    Ok(())
}

use crate::error::{SdkError, SdkResult};
use crate::find::{AggregateBuilder, FindBuilder};
use crate::smql_fmt;
use crate::subscription::Subscription;
use crate::types::*;
use std::time::Duration;

/// Builder for configuring an `SmqlClient`.
pub struct SmqlClientBuilder {
    base_url: String,
    timeout: Option<Duration>,
}

impl SmqlClientBuilder {
    /// Set the connection/request timeout.
    pub fn timeout(mut self, timeout: Duration) -> Self {
        self.timeout = Some(timeout);
        self
    }

    /// Build the client.
    pub fn build(self) -> SdkResult<SmqlClient> {
        let mut builder = reqwest::Client::builder();
        if let Some(t) = self.timeout {
            builder = builder.timeout(t);
        }
        let http = builder.build().map_err(SdkError::Http)?;
        // Normalize: strip trailing slash
        let base_url = self.base_url.trim_end_matches('/').to_string();
        Ok(SmqlClient { http, base_url })
    }
}

/// HTTP client for the SMQL server.
pub struct SmqlClient {
    pub(crate) http: reqwest::Client,
    pub(crate) base_url: String,
}

impl SmqlClient {
    /// Create a new client connected to the given base URL.
    pub fn new(base_url: &str) -> SdkResult<Self> {
        Self::builder(base_url).build()
    }

    /// Create a builder for more configuration options.
    pub fn builder(base_url: &str) -> SmqlClientBuilder {
        SmqlClientBuilder {
            base_url: base_url.to_string(),
            timeout: None,
        }
    }

    /// Execute raw SMQL and return the response.
    pub async fn execute(&self, smql: &str) -> SdkResult<ExecuteResponse> {
        let resp = self
            .http
            .post(format!("{}/execute", self.base_url))
            .json(&serde_json::json!({ "smql": smql }))
            .send()
            .await?;

        let status = resp.status();
        let body: ExecuteResponse = resp
            .json()
            .await
            .map_err(|e| SdkError::Deserialize(format!("Failed to parse response: {}", e)))?;

        if !body.success {
            let msg = body.error.unwrap_or_default();
            if status == reqwest::StatusCode::NOT_FOUND {
                return Err(SdkError::NotFound(msg));
            }
            if status == reqwest::StatusCode::CONFLICT {
                return Err(SdkError::TransitionDenied(msg));
            }
            return Err(SdkError::Server(msg));
        }

        Ok(body)
    }

    /// Define a machine from SMQL source.
    pub async fn define_machine(&self, smql: &str) -> SdkResult<DefineResult> {
        let resp = self.execute(smql).await?;
        let result = resp.result.unwrap_or_default();
        let action = result["action"].as_str().unwrap_or("").to_string();
        Ok(DefineResult {
            action,
            warnings: resp.warnings,
        })
    }

    /// Spawn a new instance.
    pub async fn spawn(
        &self,
        machine: &str,
        data: serde_json::Value,
    ) -> SdkResult<InstanceResponse> {
        let smql = smql_fmt::format_spawn(machine, &data);
        let resp = self.execute(&smql).await?;
        let result = resp
            .result
            .ok_or_else(|| SdkError::Deserialize("Missing result in spawn response".to_string()))?;
        serde_json::from_value(result).map_err(|e| SdkError::Deserialize(e.to_string()))
    }

    /// Transition an instance to a new state.
    pub async fn transition(
        &self,
        machine: &str,
        instance_id: &str,
        to_state: &str,
        opts: TransitionOptions,
    ) -> SdkResult<TransitionResponse> {
        let smql = smql_fmt::format_transition(machine, instance_id, to_state, &opts);
        let resp = self.execute(&smql).await?;
        let result = resp.result.ok_or_else(|| {
            SdkError::Deserialize("Missing result in transition response".to_string())
        })?;
        serde_json::from_value(result).map_err(|e| SdkError::Deserialize(e.to_string()))
    }

    /// Try to transition; returns `None` if guard fails instead of an error.
    pub async fn try_transition(
        &self,
        machine: &str,
        instance_id: &str,
        to_state: &str,
        opts: TransitionOptions,
    ) -> SdkResult<Option<TransitionResponse>> {
        let smql = smql_fmt::format_try_transition(machine, instance_id, to_state, &opts);
        let resp = self.execute(&smql).await?;
        let result = resp.result.ok_or_else(|| {
            SdkError::Deserialize("Missing result in try_transition response".to_string())
        })?;
        let transitioned = result["transitioned"].as_bool().unwrap_or(false);
        if !transitioned {
            return Ok(None);
        }
        let tr: TransitionResponse =
            serde_json::from_value(result).map_err(|e| SdkError::Deserialize(e.to_string()))?;
        Ok(Some(tr))
    }

    /// Get an instance by ID (via REST endpoint).
    pub async fn get_instance(&self, id: &str) -> SdkResult<InstanceResponse> {
        let url = format!("{}/instances/{}", self.base_url, id);
        let resp = self.http.get(&url).send().await?;

        let status = resp.status();
        if !status.is_success() {
            let body_text = resp.text().await.unwrap_or_default();
            let body: serde_json::Value = serde_json::from_str(&body_text).unwrap_or_default();
            let msg = body["error"]
                .as_str()
                .map(String::from)
                .unwrap_or_else(|| format!("HTTP {}: {}", status, body_text));
            if status == reqwest::StatusCode::NOT_FOUND {
                return Err(SdkError::NotFound(msg));
            }
            return Err(SdkError::Server(msg));
        }

        let inst: InstanceResponse = resp
            .json()
            .await
            .map_err(|e| SdkError::Deserialize(e.to_string()))?;
        Ok(inst)
    }

    /// List all registered machine names.
    pub async fn list_machines(&self) -> SdkResult<Vec<String>> {
        let resp = self
            .http
            .get(format!("{}/machines", self.base_url))
            .send()
            .await?;

        let body: serde_json::Value = resp
            .json()
            .await
            .map_err(|e| SdkError::Deserialize(e.to_string()))?;

        let names = body["machines"]
            .as_array()
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| v.as_str().map(String::from))
                    .collect()
            })
            .unwrap_or_default();
        Ok(names)
    }

    /// Get machine definition info.
    pub async fn get_machine(&self, name: &str) -> SdkResult<MachineInfo> {
        let resp = self
            .http
            .get(format!("{}/machines/{}", self.base_url, name))
            .send()
            .await?;

        if resp.status() == reqwest::StatusCode::NOT_FOUND {
            return Err(SdkError::NotFound(format!("Machine '{}' not found", name)));
        }

        let info: MachineInfo = resp
            .json()
            .await
            .map_err(|e| SdkError::Deserialize(e.to_string()))?;
        Ok(info)
    }

    /// Get trail entries for an instance.
    pub async fn trail(&self, instance_id: &str) -> SdkResult<Vec<TrailEntryResponse>> {
        let smql = smql_fmt::format_trail(instance_id);
        let resp = self.execute(&smql).await?;
        let result = resp.result.unwrap_or_default();
        let entries = result["entries"]
            .as_array()
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| serde_json::from_value(v.clone()).ok())
                    .collect()
            })
            .unwrap_or_default();
        Ok(entries)
    }

    /// Check server health.
    pub async fn health(&self) -> SdkResult<bool> {
        let resp = self
            .http
            .get(format!("{}/health", self.base_url))
            .send()
            .await?;

        let body: serde_json::Value = resp
            .json()
            .await
            .map_err(|e| SdkError::Deserialize(e.to_string()))?;

        Ok(body["status"] == "ok")
    }

    /// Start building a FIND query.
    pub fn find(&self, machine: &str) -> FindBuilder<'_> {
        FindBuilder::new(self, machine)
    }

    /// Start building an AGGREGATE query.
    pub fn aggregate(&self, machine: &str) -> AggregateBuilder<'_> {
        AggregateBuilder::new(self, machine)
    }

    /// Subscribe to server events via WebSocket.
    pub async fn subscribe(&self, machine: Option<&str>) -> SdkResult<Subscription> {
        let ws_url = self
            .base_url
            .replacen("http://", "ws://", 1)
            .replacen("https://", "wss://", 1);
        let mut url = format!("{}/subscribe", ws_url);
        if let Some(m) = machine {
            url.push_str(&format!("?machine={}", m));
        }
        Subscription::connect(&url).await
    }
}

use thiserror::Error;

/// Errors returned by the SDK.
#[derive(Debug, Error)]
pub enum SdkError {
    /// HTTP transport error.
    #[error("HTTP error: {0}")]
    Http(#[from] reqwest::Error),

    /// Server returned an error response.
    #[error("Server error: {0}")]
    Server(String),

    /// Transition was denied (guard failure).
    #[error("Transition denied: {0}")]
    TransitionDenied(String),

    /// Resource not found.
    #[error("Not found: {0}")]
    NotFound(String),

    /// SMQL parse or format error.
    #[error("Parse error: {0}")]
    Parse(String),

    /// WebSocket subscription error.
    #[error("Subscription error: {0}")]
    Subscription(String),

    /// JSON deserialization error.
    #[error("Deserialization error: {0}")]
    Deserialize(String),

    /// Invalid URL.
    #[error("Invalid URL: {0}")]
    InvalidUrl(String),
}

pub type SdkResult<T> = Result<T, SdkError>;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_error_display() {
        let err = SdkError::Server("internal error".to_string());
        assert_eq!(err.to_string(), "Server error: internal error");

        let err = SdkError::TransitionDenied("guard failed".to_string());
        assert_eq!(err.to_string(), "Transition denied: guard failed");

        let err = SdkError::NotFound("instance abc not found".to_string());
        assert_eq!(err.to_string(), "Not found: instance abc not found");

        let err = SdkError::Parse("unexpected token".to_string());
        assert_eq!(err.to_string(), "Parse error: unexpected token");

        let err = SdkError::Subscription("connection closed".to_string());
        assert_eq!(err.to_string(), "Subscription error: connection closed");

        let err = SdkError::Deserialize("invalid json".to_string());
        assert_eq!(err.to_string(), "Deserialization error: invalid json");

        let err = SdkError::InvalidUrl("bad url".to_string());
        assert_eq!(err.to_string(), "Invalid URL: bad url");
    }
}

use crate::client::SmqlClient;
use crate::error::{SdkError, SdkResult};
use crate::smql_fmt;
use crate::types::InstanceResponse;

/// Builder for FIND queries.
pub struct FindBuilder<'a> {
    client: &'a SmqlClient,
    machine: String,
    filter: Option<String>,
    sort: Vec<(String, String)>,
    limit: Option<u64>,
    offset: Option<u64>,
}

impl<'a> FindBuilder<'a> {
    pub(crate) fn new(client: &'a SmqlClient, machine: &str) -> Self {
        Self {
            client,
            machine: machine.to_string(),
            filter: None,
            sort: Vec::new(),
            limit: None,
            offset: None,
        }
    }

    /// Filter to instances in a specific state.
    pub fn in_state(mut self, state: &str) -> Self {
        self.filter = Some(format!("STATE IS {}", state));
        self
    }

    /// Filter to instances stuck in a state for longer than a duration.
    pub fn stuck_in(mut self, state: &str, duration: &str) -> Self {
        self.filter = Some(format!("STUCK IN {} FOR {}", state, duration));
        self
    }

    /// Add a raw WHERE clause expression.
    pub fn where_clause(mut self, expr: &str) -> Self {
        self.filter = Some(expr.to_string());
        self
    }

    /// Add a sort clause.
    pub fn sort_by(mut self, field: &str, direction: &str) -> Self {
        self.sort.push((field.to_string(), direction.to_string()));
        self
    }

    /// Limit results.
    pub fn limit(mut self, n: u64) -> Self {
        self.limit = Some(n);
        self
    }

    /// Offset results.
    pub fn offset(mut self, n: u64) -> Self {
        self.offset = Some(n);
        self
    }

    /// Execute the query and return matching instances.
    pub async fn execute(self) -> SdkResult<Vec<InstanceResponse>> {
        let smql = smql_fmt::format_find(
            &self.machine,
            self.filter.as_deref(),
            &self.sort,
            self.limit,
            self.offset,
        );
        let resp = self.client.execute(&smql).await?;
        let result = resp.result.unwrap_or_default();

        // Single instance (GET) or list of instances (FIND)
        if let Some(arr) = result["instances"].as_array() {
            let instances: Vec<InstanceResponse> = arr
                .iter()
                .filter_map(|v| serde_json::from_value(v.clone()).ok())
                .collect();
            Ok(instances)
        } else {
            Ok(Vec::new())
        }
    }

    /// Execute the query and return only the count.
    pub async fn count(self) -> SdkResult<u64> {
        let smql = smql_fmt::format_find(
            &self.machine,
            self.filter.as_deref(),
            &self.sort,
            self.limit,
            self.offset,
        );
        let resp = self.client.execute(&smql).await?;
        let result = resp.result.unwrap_or_default();
        Ok(result["count"].as_u64().unwrap_or(0))
    }
}

/// Builder for AGGREGATE queries.
pub struct AggregateBuilder<'a> {
    client: &'a SmqlClient,
    machine: String,
    measure: Option<String>,
    group_by: Option<String>,
}

impl<'a> AggregateBuilder<'a> {
    pub(crate) fn new(client: &'a SmqlClient, machine: &str) -> Self {
        Self {
            client,
            machine: machine.to_string(),
            measure: None,
            group_by: None,
        }
    }

    /// Set the measure function (e.g., "COUNT()", "AVG(field)").
    pub fn measure(mut self, m: &str) -> Self {
        self.measure = Some(m.to_string());
        self
    }

    /// Group by state.
    pub fn group_by_state(mut self) -> Self {
        self.group_by = Some("state".to_string());
        self
    }

    /// Group by a data field.
    pub fn group_by_field(mut self, field: &str) -> Self {
        self.group_by = Some(field.to_string());
        self
    }

    /// Execute the aggregate query.
    pub async fn execute(self) -> SdkResult<serde_json::Value> {
        let smql = smql_fmt::format_aggregate(
            &self.machine,
            self.measure.as_deref(),
            self.group_by.as_deref(),
        );
        let resp = self.client.execute(&smql).await?;
        resp.result.ok_or_else(|| {
            SdkError::Deserialize("Missing result in aggregate response".to_string())
        })
    }
}

//! SMQL SDK — ergonomic Rust client for the SMQL server.
//!
//! # Quick Start
//!
//! ```no_run
//! use smql_sdk::prelude::*;
//!
//! #[tokio::main]
//! async fn main() -> Result<(), Box<dyn std::error::Error>> {
//!     let client = SmqlClient::new("http://localhost:4200")?;
//!     assert!(client.health().await?);
//!     Ok(())
//! }
//! ```

pub mod client;
pub mod error;
pub mod find;
pub mod smql_fmt;
pub mod subscription;
pub mod typed;
pub mod types;

/// Re-exports of the most commonly used types.
pub mod prelude {
    pub use crate::client::SmqlClient;
    pub use crate::error::{SdkError, SdkResult};
    pub use crate::find::{AggregateBuilder, FindBuilder};
    pub use crate::subscription::{Subscription, SubscriptionHandle};
    pub use crate::typed::{SmqlMachine, SmqlState, TypedInstance};
    pub use crate::types::*;
}

use crate::types::TransitionOptions;

/// Format a SPAWN command.
pub fn format_spawn(machine: &str, data: &serde_json::Value) -> String {
    let data_str = format_data_fields(data);
    format!("SPAWN {} {{{}}}", machine, data_str)
}

/// Format a TRANSITION command.
pub fn format_transition(
    machine: &str,
    instance_id: &str,
    to_state: &str,
    opts: &TransitionOptions,
) -> String {
    let mut s = format!("TRANSITION {} \"{}\" TO {}", machine, instance_id, to_state);
    if !opts.with_data.is_empty() {
        let fields: Vec<String> = opts
            .with_data
            .iter()
            .map(|(k, v)| format!("{}: {}", k, value_to_smql(v)))
            .collect();
        s.push_str(&format!(" WITH {{ {} }}", fields.join(", ")));
    }
    if let Some(ref memo) = opts.memo {
        s.push_str(&format!(" MEMO \"{}\"", escape_string(memo)));
    }
    if let Some(ref actor) = opts.as_actor {
        s.push_str(&format!(" AS \"{}\"", escape_string(actor)));
    }
    s
}

/// Format a TRY TRANSITION command.
pub fn format_try_transition(
    machine: &str,
    instance_id: &str,
    to_state: &str,
    opts: &TransitionOptions,
) -> String {
    let base = format_transition(machine, instance_id, to_state, opts);
    format!("TRY {}", base)
}

/// Format a FIND query.
pub fn format_find(
    machine: &str,
    filter: Option<&str>,
    sort: &[(String, String)],
    limit: Option<u64>,
    offset: Option<u64>,
) -> String {
    let mut s = format!("FIND {}", machine);
    if let Some(f) = filter {
        s.push_str(&format!(" WHERE {}", f));
    }
    if !sort.is_empty() {
        let clauses: Vec<String> = sort
            .iter()
            .map(|(field, dir)| format!("{} {}", field, dir))
            .collect();
        s.push_str(&format!(" SORT BY {}", clauses.join(", ")));
    }
    if let Some(n) = limit {
        s.push_str(&format!(" LIMIT {}", n));
    }
    if let Some(n) = offset {
        s.push_str(&format!(" OFFSET {}", n));
    }
    s
}

/// Format a GET query.
pub fn format_get(machine: &str, instance_id: &str) -> String {
    format!("GET {} \"{}\"", machine, instance_id)
}

/// Format a TRAIL query.
pub fn format_trail(instance_id: &str) -> String {
    format!("TRAIL OF \"{}\"", instance_id)
}

/// Format an AGGREGATE query.
pub fn format_aggregate(machine: &str, measure: Option<&str>, group_by: Option<&str>) -> String {
    let mut s = format!("AGGREGATE {}", machine);
    if let Some(m) = measure {
        s.push_str(&format!(" MEASURE {}", m));
    }
    if let Some(g) = group_by {
        s.push_str(&format!(" GROUP BY {}", g));
    }
    s
}

/// Convert a JSON value to an SMQL literal.
pub fn value_to_smql(val: &serde_json::Value) -> String {
    match val {
        serde_json::Value::Null => "NULL".to_string(),
        serde_json::Value::Bool(b) => if *b { "true" } else { "false" }.to_string(),
        serde_json::Value::Number(n) => n.to_string(),
        serde_json::Value::String(s) => format!("\"{}\"", escape_string(s)),
        serde_json::Value::Array(arr) => {
            let items: Vec<String> = arr.iter().map(value_to_smql).collect();
            format!("[{}]", items.join(", "))
        }
        serde_json::Value::Object(obj) => {
            let fields: Vec<String> = obj
                .iter()
                .map(|(k, v)| format!("{}: {}", k, value_to_smql(v)))
                .collect();
            format!("{{{}}}", fields.join(", "))
        }
    }
}

fn format_data_fields(data: &serde_json::Value) -> String {
    match data {
        serde_json::Value::Object(obj) if obj.is_empty() => String::new(),
        serde_json::Value::Object(obj) => {
            let fields: Vec<String> = obj
                .iter()
                .map(|(k, v)| format!("{}: {}", k, value_to_smql(v)))
                .collect();
            format!(" {} ", fields.join(", "))
        }
        _ => String::new(),
    }
}

fn escape_string(s: &str) -> String {
    s.replace('\\', "\\\\").replace('"', "\\\"")
}

