use prometheus::{
    Encoder, HistogramOpts, HistogramVec, IntCounterVec, IntGaugeVec, Opts, Registry, TextEncoder,
};

/// All Prometheus metrics for the SMQL server.
#[derive(Clone)]
pub struct SmqlMetrics {
    pub registry: Registry,
    pub instances_total: IntGaugeVec,
    pub transitions_total: IntCounterVec,
    pub transition_duration_seconds: HistogramVec,
    pub guard_failures_total: IntCounterVec,
    pub timeout_fires_total: IntCounterVec,
    pub query_duration_seconds: HistogramVec,
    pub spawns_total: IntCounterVec,
}

impl SmqlMetrics {
    pub fn new() -> Self {
        let registry = Registry::new();

        let instances_total = IntGaugeVec::new(
            Opts::new(
                "smql_instances_total",
                "Number of active instances by machine and state",
            ),
            &["machine", "state"],
        )
        .unwrap();

        let transitions_total = IntCounterVec::new(
            Opts::new(
                "smql_transitions_total",
                "Total transitions by machine, from, to",
            ),
            &["machine", "from", "to"],
        )
        .unwrap();

        let transition_duration_seconds = HistogramVec::new(
            HistogramOpts::new(
                "smql_transition_duration_seconds",
                "Transition duration in seconds",
            ),
            &["machine"],
        )
        .unwrap();

        let guard_failures_total = IntCounterVec::new(
            Opts::new(
                "smql_guard_failures_total",
                "Total guard failures by machine",
            ),
            &["machine"],
        )
        .unwrap();

        let timeout_fires_total = IntCounterVec::new(
            Opts::new(
                "smql_timeout_fires_total",
                "Total timeout transitions by machine and state",
            ),
            &["machine", "state"],
        )
        .unwrap();

        let query_duration_seconds = HistogramVec::new(
            HistogramOpts::new("smql_query_duration_seconds", "Query duration in seconds"),
            &["query_type"],
        )
        .unwrap();

        let spawns_total = IntCounterVec::new(
            Opts::new("smql_spawns_total", "Total spawned instances by machine"),
            &["machine"],
        )
        .unwrap();

        registry
            .register(Box::new(instances_total.clone()))
            .unwrap();
        registry
            .register(Box::new(transitions_total.clone()))
            .unwrap();
        registry
            .register(Box::new(transition_duration_seconds.clone()))
            .unwrap();
        registry
            .register(Box::new(guard_failures_total.clone()))
            .unwrap();
        registry
            .register(Box::new(timeout_fires_total.clone()))
            .unwrap();
        registry
            .register(Box::new(query_duration_seconds.clone()))
            .unwrap();
        registry.register(Box::new(spawns_total.clone())).unwrap();

        Self {
            registry,
            instances_total,
            transitions_total,
            transition_duration_seconds,
            guard_failures_total,
            timeout_fires_total,
            query_duration_seconds,
            spawns_total,
        }
    }

    /// Encode all metrics as Prometheus text format.
    pub fn encode(&self) -> String {
        let encoder = TextEncoder::new();
        let metric_families = self.registry.gather();
        let mut buffer = Vec::new();
        encoder.encode(&metric_families, &mut buffer).unwrap();
        String::from_utf8(buffer).unwrap()
    }
}

impl Default for SmqlMetrics {
    fn default() -> Self {
        Self::new()
    }
}

use axum::Router;
use smql_catalog::MachineCatalog;
use smql_engine_core::Engine;
use smql_hooks::{EventBus, WebhookClient, WebhookConfig};
use smql_storage::{MemoryStorage, Storage};
use std::sync::Arc;

use crate::handlers;
use crate::metrics::SmqlMetrics;

/// Shared application state.
#[derive(Clone)]
pub struct AppState {
    pub engine: Arc<Engine>,
    pub metrics: Arc<SmqlMetrics>,
    pub event_bus: Arc<EventBus>,
}

/// The SMQL HTTP server.
pub struct SmqlServer {
    state: AppState,
    #[cfg(feature = "auth")]
    auth_config: Option<crate::auth::AuthConfig>,
}

impl SmqlServer {
    /// Create a new server with in-memory storage.
    pub fn new() -> Self {
        let catalog = Arc::new(MachineCatalog::new());
        let storage = Arc::new(MemoryStorage::new());
        let engine = Arc::new(Engine::new(catalog, storage));
        engine.wire_callback();
        let event_bus = engine.event_bus().clone();
        let metrics = Arc::new(SmqlMetrics::new());

        Self {
            state: AppState {
                engine,
                metrics,
                event_bus,
            },
            #[cfg(feature = "auth")]
            auth_config: None,
        }
    }

    /// Create a new server with a custom storage backend.
    pub fn with_storage(storage: Arc<dyn Storage>) -> Self {
        let catalog = Arc::new(MachineCatalog::new());
        let engine = Arc::new(Engine::new(catalog, storage));
        engine.wire_callback();
        let event_bus = engine.event_bus().clone();
        let metrics = Arc::new(SmqlMetrics::new());

        Self {
            state: AppState {
                engine,
                metrics,
                event_bus,
            },
            #[cfg(feature = "auth")]
            auth_config: None,
        }
    }

    /// Create a server with an existing engine (for testing).
    pub fn with_engine(engine: Arc<Engine>) -> Self {
        engine.wire_callback();
        let event_bus = engine.event_bus().clone();
        let metrics = Arc::new(SmqlMetrics::new());

        Self {
            state: AppState {
                engine,
                metrics,
                event_bus,
            },
            #[cfg(feature = "auth")]
            auth_config: None,
        }
    }

    /// Enable JWT authentication with the given config.
    #[cfg(feature = "auth")]
    pub fn with_auth(mut self, config: crate::auth::AuthConfig) -> Self {
        self.auth_config = Some(config);
        self
    }

    /// Build the axum Router.
    pub fn router(&self) -> Router {
        let router = handlers::build_router(self.state.clone());

        #[cfg(feature = "auth")]
        let router = if let Some(config) = &self.auth_config {
            router
                .layer(axum::middleware::from_fn(crate::auth::auth_middleware))
                .layer(crate::auth::AuthConfigLayer {
                    config: config.clone(),
                })
        } else {
            router
        };

        router
    }

    /// Start the server on the given address.
    pub async fn serve(self, addr: &str) -> Result<(), Box<dyn std::error::Error>> {
        // Wire up webhook client for real HTTP POST
        let webhook_client = Arc::new(WebhookClient::new(WebhookConfig::default()));
        self.state
            .engine
            .hook_executor
            .set_webhook_client(webhook_client);

        // Restore persisted timers before starting the timer loop
        match self.state.engine.restore_timers().await {
            Ok(count) => {
                if count > 0 {
                    tracing::info!(count, "restored persisted timers");
                }
            }
            Err(e) => {
                tracing::warn!("failed to restore timers: {}", e);
            }
        }

        // Start background EventBus listener for timeout metrics
        crate::handlers::start_event_metrics_listener(
            self.state.event_bus.clone(),
            self.state.metrics.clone(),
        );

        let app = self.router();
        let listener = tokio::net::TcpListener::bind(addr).await?;
        tracing::info!("SMQL server listening on {}", addr);
        axum::serve(listener, app).await?;
        Ok(())
    }
}

