#[tokio::test]
async fn metrics_track_all_query_types() {
    let server = SmqlServer::new();
    let app = server.router();

    let resp = app
        .clone()
        .oneshot(execute_request(define_task_machine()))
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::CREATED);

    // Spawn an instance
