use axum::extract::ws::{Message, WebSocket};
use smql_hooks::EventBus;
use std::sync::Arc;

/// Query parameters for WebSocket event filtering.
#[derive(Debug, Clone, Default, serde::Deserialize)]
pub struct SubscribeParams {
    pub machine: Option<String>,
    pub event: Option<String>,
}

/// Handle a WebSocket connection, forwarding matching EventBus events as JSON.
pub async fn handle_ws(mut socket: WebSocket, event_bus: Arc<EventBus>, params: SubscribeParams) {
    let mut receiver = event_bus.subscribe();

    loop {
        tokio::select! {
            result = receiver.recv() => {
                match result {
                    Ok(event) => {
                        // Apply filters
                        if let Some(ref machine) = params.machine {
                            if event.machine != *machine {
                                continue;
                            }
                        }
                        if let Some(ref event_name) = params.event {
                            if event.name != *event_name {
                                continue;
                            }
                        }

                        let payload = serde_json::json!({
                            "event": event.name,
                            "instance_id": event.instance_id,
                            "machine": event.machine,
                            "payload": event.payload.map(|v| crate::handlers::value_to_json(&v)),
                        });

                        if socket
                            .send(Message::Text(payload.to_string()))
                            .await
                            .is_err()
                        {
                            break; // Client disconnected
                        }
                    }
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                        tracing::warn!(skipped = n, "WebSocket subscriber lagged");
                    }
                    Err(tokio::sync::broadcast::error::RecvError::Closed) => {
                        break; // EventBus shut down
                    }
                }
            }
            // Check for client disconnect (incoming messages)
            msg = socket.recv() => {
                match msg {
                    Some(Ok(Message::Close(_))) | None => break,
                    _ => {} // Ignore other messages from client
                }
            }
        }
    }
}

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use smql_ast::value::Value;
use std::collections::HashMap;
use std::fmt;

/// A unique identifier for a machine instance, backed by ULID.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct InstanceId(pub ulid::Ulid);

impl InstanceId {
    pub fn new() -> Self {
        Self(ulid::Ulid::new())
    }

    pub fn from_string(s: &str) -> Result<Self, ulid::DecodeError> {
        Ok(Self(ulid::Ulid::from_string(s)?))
    }

    pub fn as_str(&self) -> String {
        self.0.to_string()
    }
}

impl Default for InstanceId {
    fn default() -> Self {
        Self::new()
    }
}

impl fmt::Display for InstanceId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

/// A live instance of a state machine.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Instance {
    pub id: InstanceId,
    pub machine: String,
    pub state: String,
    pub data: HashMap<String, Value>,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
    pub state_entered_at: DateTime<Utc>,
    pub trail_length: u64,
    pub version: u64, // optimistic concurrency control
    /// Parent instance ID (for child machines in composition)
    pub parent_id: Option<InstanceId>,
    /// Parent machine name (for child machines in composition)
    pub parent_machine: Option<String>,
}

impl Instance {
    pub fn new(machine: String, initial_state: String, data: HashMap<String, Value>) -> Self {
        let now = Utc::now();
        Self {
            id: InstanceId::new(),
            machine,
            state: initial_state,
            data,
            created_at: now,
            updated_at: now,
            state_entered_at: now,
            trail_length: 0,
            version: 1,
            parent_id: None,
            parent_machine: None,
        }
    }

    /// Create a child instance linked to a parent.
    pub fn new_child(
        machine: String,
        initial_state: String,
        data: HashMap<String, Value>,
        parent_id: InstanceId,
        parent_machine: String,
    ) -> Self {
        let now = Utc::now();
        Self {
            id: InstanceId::new(),
            machine,
            state: initial_state,
            data,
            created_at: now,
            updated_at: now,
            state_entered_at: now,
            trail_length: 0,
            version: 1,
            parent_id: Some(parent_id),
            parent_machine: Some(parent_machine),
        }
    }
}

