#[cfg(test)]
mod coverage_tests {
    use super::instance::*;
    use super::memory::MemoryStorage;
    use super::traits::Storage;
    use chrono::{NaiveDate, Utc};
    use smql_ast::value::{SmqlDuration, Value};
    use std::collections::HashMap;

    // -----------------------------------------------------------------------
    // InstanceId tests
    // -----------------------------------------------------------------------

    #[test]
    fn instance_id_default_creates_new_id() {
        let id1 = InstanceId::default();
        let id2 = InstanceId::default();
        // Two default IDs should be distinct (ULIDs are unique)
        assert_ne!(id1, id2);
    }

    #[test]
    fn instance_id_display() {
        let id = InstanceId::new();
        let display = format!("{}", id);
        let as_str = id.as_str();
        assert_eq!(display, as_str);
        // ULID strings are 26 characters
        assert_eq!(display.len(), 26);
    }

    // -----------------------------------------------------------------------
    // FilterPredicate::matches() — Gt, Gte, Lt, Lte, IsNull, IsNotNull, And, Or
    // -----------------------------------------------------------------------

    fn data_with(key: &str, val: Value) -> HashMap<String, Value> {
        let mut data = HashMap::new();
        data.insert(key.to_string(), val);
        data
    }

    #[test]
    fn predicate_gt_true_and_false() {
        let data = data_with("x", Value::Int(10));
        assert!(FilterPredicate::Gt("x".to_string(), Value::Int(5)).matches(&data));
        assert!(!FilterPredicate::Gt("x".to_string(), Value::Int(10)).matches(&data));
        assert!(!FilterPredicate::Gt("x".to_string(), Value::Int(15)).matches(&data));
    }

    #[test]
    fn predicate_gte_true_and_false() {
        let data = data_with("x", Value::Int(10));
        assert!(FilterPredicate::Gte("x".to_string(), Value::Int(5)).matches(&data));
        assert!(FilterPredicate::Gte("x".to_string(), Value::Int(10)).matches(&data));
        assert!(!FilterPredicate::Gte("x".to_string(), Value::Int(15)).matches(&data));
    }

    #[test]
    fn predicate_lt_true_and_false() {
        let data = data_with("x", Value::Int(3));
        assert!(FilterPredicate::Lt("x".to_string(), Value::Int(5)).matches(&data));
        assert!(!FilterPredicate::Lt("x".to_string(), Value::Int(3)).matches(&data));
        assert!(!FilterPredicate::Lt("x".to_string(), Value::Int(1)).matches(&data));
    }

    #[test]
    fn predicate_lte_true_and_false() {
        let data = data_with("x", Value::Int(3));
        assert!(FilterPredicate::Lte("x".to_string(), Value::Int(5)).matches(&data));
        assert!(FilterPredicate::Lte("x".to_string(), Value::Int(3)).matches(&data));
        assert!(!FilterPredicate::Lte("x".to_string(), Value::Int(1)).matches(&data));
    }

    #[test]
    fn predicate_is_null_present_null() {
        let data = data_with("x", Value::Null);
        assert!(FilterPredicate::IsNull("x".to_string()).matches(&data));
    }

    #[test]
    fn predicate_is_null_missing_field() {
        let data: HashMap<String, Value> = HashMap::new();
        // Missing field is treated as null
        assert!(FilterPredicate::IsNull("x".to_string()).matches(&data));
    }

    #[test]
    fn predicate_is_null_present_non_null() {
        let data = data_with("x", Value::Int(1));
        assert!(!FilterPredicate::IsNull("x".to_string()).matches(&data));
    }

    #[test]
    fn predicate_is_not_null_present_value() {
        let data = data_with("x", Value::Text("hi".to_string()));
        assert!(FilterPredicate::IsNotNull("x".to_string()).matches(&data));
    }

    #[test]
    fn predicate_is_not_null_missing_field() {
        let data: HashMap<String, Value> = HashMap::new();
        assert!(!FilterPredicate::IsNotNull("x".to_string()).matches(&data));
    }

    #[test]
    fn predicate_is_not_null_present_null() {
        let data = data_with("x", Value::Null);
        assert!(!FilterPredicate::IsNotNull("x".to_string()).matches(&data));
    }

    #[test]
    fn predicate_and_both_true() {
        let mut data = HashMap::new();
        data.insert("a".to_string(), Value::Int(5));
        data.insert("b".to_string(), Value::Int(10));
        let pred = FilterPredicate::And(
            Box::new(FilterPredicate::Gt("a".to_string(), Value::Int(3))),
            Box::new(FilterPredicate::Lt("b".to_string(), Value::Int(20))),
        );
        assert!(pred.matches(&data));
    }

    #[test]
    fn predicate_and_one_false() {
        let mut data = HashMap::new();
        data.insert("a".to_string(), Value::Int(1));
        data.insert("b".to_string(), Value::Int(10));
        let pred = FilterPredicate::And(
            Box::new(FilterPredicate::Gt("a".to_string(), Value::Int(3))),
            Box::new(FilterPredicate::Lt("b".to_string(), Value::Int(20))),
        );
        assert!(!pred.matches(&data));
    }

    #[test]
    fn predicate_or_one_true() {
        let data = data_with("a", Value::Int(1));
        let pred = FilterPredicate::Or(
            Box::new(FilterPredicate::Gt("a".to_string(), Value::Int(3))),
            Box::new(FilterPredicate::Lt("a".to_string(), Value::Int(5))),
        );
        assert!(pred.matches(&data));
    }

    #[test]
    fn predicate_or_both_false() {
        let data = data_with("a", Value::Int(10));
        let pred = FilterPredicate::Or(
            Box::new(FilterPredicate::Lt("a".to_string(), Value::Int(3))),
            Box::new(FilterPredicate::Eq("a".to_string(), Value::Int(5))),
        );
        assert!(!pred.matches(&data));
    }

    // -----------------------------------------------------------------------
    // compare_values() — DateTime, Date, Duration, and incompatible types
    // -----------------------------------------------------------------------

    #[test]
    fn predicate_gt_datetime() {
        let dt1 = Utc::now();
        let dt2 = dt1 + chrono::Duration::hours(1);
        let data = data_with("ts", Value::DateTime(dt2));
        assert!(FilterPredicate::Gt("ts".to_string(), Value::DateTime(dt1)).matches(&data));
        assert!(!FilterPredicate::Gt("ts".to_string(), Value::DateTime(dt2)).matches(&data));
    }

    #[test]
    fn predicate_lt_date() {
        let d1 = NaiveDate::from_ymd_opt(2025, 1, 1).unwrap();
        let d2 = NaiveDate::from_ymd_opt(2025, 6, 15).unwrap();
        let data = data_with("d", Value::Date(d1));
        assert!(FilterPredicate::Lt("d".to_string(), Value::Date(d2)).matches(&data));
        assert!(!FilterPredicate::Lt("d".to_string(), Value::Date(d1)).matches(&data));
    }

    #[test]
    fn predicate_gte_duration() {
        let dur_short = SmqlDuration::from_seconds(60);
        let dur_long = SmqlDuration::from_seconds(120);
        let data = data_with("dur", Value::Duration(dur_long.clone()));
        assert!(FilterPredicate::Gte("dur".to_string(), Value::Duration(dur_short)).matches(&data));
        assert!(FilterPredicate::Gte("dur".to_string(), Value::Duration(dur_long)).matches(&data));
    }

    #[test]
    fn predicate_incompatible_types_returns_false() {
        // Int vs Text — compare_values returns None, so Gt returns false
        let data = data_with("x", Value::Int(10));
        assert!(
            !FilterPredicate::Gt("x".to_string(), Value::Text("hello".to_string())).matches(&data)
        );
        assert!(
            !FilterPredicate::Lt("x".to_string(), Value::Text("hello".to_string())).matches(&data)
        );
        assert!(
            !FilterPredicate::Gte("x".to_string(), Value::Text("hello".to_string())).matches(&data)
        );
        assert!(
            !FilterPredicate::Lte("x".to_string(), Value::Text("hello".to_string())).matches(&data)
        );
    }

    #[test]
    fn predicate_gt_missing_field_returns_false() {
        let data: HashMap<String, Value> = HashMap::new();
        assert!(!FilterPredicate::Gt("x".to_string(), Value::Int(5)).matches(&data));
    }

    // -----------------------------------------------------------------------
    // MemoryStorage mutation tests: RemoveField, IncrementField, AppendToList
    // -----------------------------------------------------------------------

    fn make_instance(machine: &str, state: &str) -> Instance {
        let mut data = HashMap::new();
        data.insert("name".to_string(), Value::Text("test".to_string()));
        Instance::new(machine.to_string(), state.to_string(), data)
    }

    #[tokio::test]
    async fn mutation_remove_field() {
        let storage = MemoryStorage::new();
        let mut inst = make_instance("Order", "open");
        inst.data
            .insert("extra".to_string(), Value::Text("val".to_string()));
        let id = inst.id.clone();
        storage.store_instance(&inst).await.unwrap();

        let mutations = vec![Mutation::RemoveField("extra".to_string())];
        storage.update_instance(&id, 1, &mutations).await.unwrap();

        let updated = storage.get_instance(&id).await.unwrap().unwrap();
        assert!(!updated.data.contains_key("extra"));
        // "name" should still be there
        assert!(updated.data.contains_key("name"));
    }

    #[tokio::test]
    async fn mutation_increment_field() {
        let storage = MemoryStorage::new();
        let mut inst = make_instance("Order", "open");
        inst.data.insert("counter".to_string(), Value::Int(10));
        let id = inst.id.clone();
        storage.store_instance(&inst).await.unwrap();

        let mutations = vec![Mutation::IncrementField("counter".to_string(), 7)];
        storage.update_instance(&id, 1, &mutations).await.unwrap();

        let updated = storage.get_instance(&id).await.unwrap().unwrap();
        assert_eq!(updated.data.get("counter"), Some(&Value::Int(17)));
    }

    #[tokio::test]
    async fn mutation_increment_field_negative_delta() {
        let storage = MemoryStorage::new();
        let mut inst = make_instance("Order", "open");
        inst.data.insert("counter".to_string(), Value::Int(10));
        let id = inst.id.clone();
        storage.store_instance(&inst).await.unwrap();

        let mutations = vec![Mutation::IncrementField("counter".to_string(), -3)];
        storage.update_instance(&id, 1, &mutations).await.unwrap();

        let updated = storage.get_instance(&id).await.unwrap().unwrap();
        assert_eq!(updated.data.get("counter"), Some(&Value::Int(7)));
    }

    #[tokio::test]
    async fn mutation_append_to_list() {
        let storage = MemoryStorage::new();
        let mut inst = make_instance("Order", "open");
        inst.data.insert(
            "items".to_string(),
            Value::List(vec![Value::Text("a".to_string())]),
        );
        let id = inst.id.clone();
        storage.store_instance(&inst).await.unwrap();

        let mutations = vec![Mutation::AppendToList(
            "items".to_string(),
            Value::Text("b".to_string()),
        )];
        storage.update_instance(&id, 1, &mutations).await.unwrap();

        let updated = storage.get_instance(&id).await.unwrap().unwrap();
        match updated.data.get("items") {
            Some(Value::List(items)) => {
                assert_eq!(items.len(), 2);
                assert_eq!(items[0], Value::Text("a".to_string()));
                assert_eq!(items[1], Value::Text("b".to_string()));
            }
            other => panic!("Expected List, got {:?}", other),
        }
    }

    // -----------------------------------------------------------------------
    // delete_instance for non-existent ID (NotFound error)
    // -----------------------------------------------------------------------

    #[tokio::test]
    async fn delete_nonexistent_instance_returns_not_found() {
        let storage = MemoryStorage::new();
        let id = InstanceId::new();
        let result = storage.delete_instance(&id).await;
        assert!(result.is_err());
        let err = result.unwrap_err();
        let err_str = format!("{}", err);
        assert!(
            err_str.contains("not found") || err_str.contains("Not found"),
            "Expected 'not found' error, got: {}",
            err_str
        );
    }

    // -----------------------------------------------------------------------
    // MemoryStorage::default() equivalence to new()
    // -----------------------------------------------------------------------

    #[tokio::test]
    async fn memory_storage_default_is_equivalent_to_new() {
        let storage_default = MemoryStorage::default();
        let storage_new = MemoryStorage::new();

        // Both should start empty and work the same way
        let inst = make_instance("Test", "initial");
        let id = inst.id.clone();
        storage_default.store_instance(&inst).await.unwrap();

        let retrieved = storage_default.get_instance(&id).await.unwrap();
        assert!(retrieved.is_some());

        // new() storage should also be empty
        let result = storage_new.get_instance(&id).await.unwrap();
        assert!(result.is_none());

        // And should be able to store
        let inst2 = make_instance("Test", "initial");
        storage_new.store_instance(&inst2).await.unwrap();
        let retrieved2 = storage_new.get_instance(&inst2.id).await.unwrap();
        assert!(retrieved2.is_some());
    }
}

use async_trait::async_trait;
use chrono::Utc;
use dashmap::DashMap;
use smql_ast::{SmqlError, SmqlResult};
use std::collections::{HashMap, HashSet};
use std::sync::RwLock;

use crate::instance::{
    Filter, Instance, InstanceId, Mutation, StoredTimer, TrailEntry, TrailFilter,
};
use crate::traits::Storage;

/// In-memory storage backend using DashMap for concurrent access.
/// Suitable for development, testing, and single-node deployments.
pub struct MemoryStorage {
    /// Primary instance storage: id -> Instance
    instances: DashMap<String, Instance>,
    /// State index: "{machine}:{state}" -> set of instance IDs
    state_index: DashMap<String, HashSet<String>>,
    /// Machine index: machine -> set of instance IDs
    machine_index: DashMap<String, HashSet<String>>,
    /// Trail storage: instance_id -> ordered trail entries
    trails: DashMap<String, RwLock<Vec<TrailEntry>>>,
    /// Parent-child index: parent_id -> set of child instance IDs
    parent_index: DashMap<String, HashSet<String>>,
    /// Timer persistence: "{instance_id}:{state}" -> StoredTimer
    timers: DashMap<String, StoredTimer>,
}

impl MemoryStorage {
    pub fn new() -> Self {
        Self {
            instances: DashMap::new(),
            state_index: DashMap::new(),
            machine_index: DashMap::new(),
            trails: DashMap::new(),
            parent_index: DashMap::new(),
            timers: DashMap::new(),
        }
    }

    fn state_index_key(machine: &str, state: &str) -> String {
        format!("{}:{}", machine, state)
    }

    fn add_to_state_index(&self, machine: &str, state: &str, id: &str) {
        let key = Self::state_index_key(machine, state);
        self.state_index
            .entry(key)
            .or_default()
            .insert(id.to_string());
    }

    fn remove_from_state_index(&self, machine: &str, state: &str, id: &str) {
        let key = Self::state_index_key(machine, state);
        if let Some(mut set) = self.state_index.get_mut(&key) {
            set.remove(id);
        }
    }

    fn add_to_machine_index(&self, machine: &str, id: &str) {
        self.machine_index
            .entry(machine.to_string())
            .or_default()
            .insert(id.to_string());
    }

    fn remove_from_machine_index(&self, machine: &str, id: &str) {
        if let Some(mut set) = self.machine_index.get_mut(machine) {
            set.remove(id);
        }
    }

    fn apply_mutations(instance: &mut Instance, mutations: &[Mutation]) {
        for mutation in mutations {
            match mutation {
                Mutation::SetField(field, value) => {
                    instance.data.insert(field.clone(), value.clone());
                }
                Mutation::RemoveField(field) => {
                    instance.data.remove(field);
                }
                Mutation::IncrementField(field, delta) => {
                    if let Some(smql_ast::value::Value::Int(v)) = instance.data.get_mut(field) {
                        *v += delta;
                    }
                }
                Mutation::AppendToList(field, value) => {
                    if let Some(smql_ast::value::Value::List(list)) = instance.data.get_mut(field) {
                        list.push(value.clone());
                    }
                }
            }
        }
        instance.updated_at = Utc::now();
    }
}

impl Default for MemoryStorage {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl Storage for MemoryStorage {
    async fn store_instance(&self, instance: &Instance) -> SmqlResult<()> {
        let id_str = instance.id.as_str();

        if self.instances.contains_key(&id_str) {
            return Err(SmqlError::Conflict {
                message: format!("Instance '{}' already exists", id_str),
                hint: None,
            });
        }

        self.instances.insert(id_str.clone(), instance.clone());
        self.add_to_state_index(&instance.machine, &instance.state, &id_str);
        self.add_to_machine_index(&instance.machine, &id_str);
        self.trails.insert(id_str.clone(), RwLock::new(Vec::new()));

        // Update parent-child index if this is a child instance
        if let Some(parent_id) = &instance.parent_id {
            self.parent_index
                .entry(parent_id.as_str())
                .or_default()
                .insert(id_str);
        }

        Ok(())
    }

    async fn get_instance(&self, id: &InstanceId) -> SmqlResult<Option<Instance>> {
        let id_str = id.as_str();
        Ok(self.instances.get(&id_str).map(|entry| entry.clone()))
    }

    async fn find_instances(&self, machine: &str, filter: &Filter) -> SmqlResult<Vec<Instance>> {
        // Use state index if filtering by specific state
        let candidate_ids: Vec<String> = if let Some(state) = &filter.state {
            let key = Self::state_index_key(machine, state);
            self.state_index
                .get(&key)
                .map(|set| set.iter().cloned().collect())
                .unwrap_or_default()
        } else if let Some(states) = &filter.states {
            let mut ids = Vec::new();
            for state in states {
                let key = Self::state_index_key(machine, state);
                if let Some(set) = self.state_index.get(&key) {
                    ids.extend(set.iter().cloned());
                }
            }
            ids
        } else {
            // Full scan of machine index
            self.machine_index
                .get(machine)
                .map(|set| set.iter().cloned().collect())
                .unwrap_or_default()
        };

        let mut results: Vec<Instance> = candidate_ids
            .iter()
            .filter_map(|id| self.instances.get(id).map(|entry| entry.clone()))
            .filter(|inst| inst.machine == machine)
            .filter(|inst| {
                if let Some(pred) = &filter.predicate {
                    pred.matches(&inst.data)
                } else {
                    true
                }
            })
            .collect();

        // Sort by ID for deterministic cursor-based pagination
        results.sort_by(|a, b| a.id.as_str().cmp(&b.id.as_str()));

        // Apply cursor filter: only instances with ID > after_id
        if let Some(after_id) = &filter.after_id {
            results.retain(|inst| inst.id.as_str().as_str() > after_id.as_str());
        }

        // Apply offset and limit
        if let Some(offset) = filter.offset {
            if offset < results.len() {
                results = results.into_iter().skip(offset).collect();
            } else {
                results.clear();
            }
        }
        if let Some(limit) = filter.limit {
            results.truncate(limit);
        }

        Ok(results)
    }

    async fn update_instance(
        &self,
        id: &InstanceId,
        expected_version: u64,
        mutations: &[Mutation],
    ) -> SmqlResult<()> {
        let id_str = id.as_str();

        let mut entry = self
            .instances
            .get_mut(&id_str)
            .ok_or_else(|| SmqlError::not_found("Instance", &id_str))?;

        if entry.version != expected_version {
            return Err(SmqlError::Conflict {
                message: format!(
                    "Version conflict for instance '{}': expected {}, got {}",
                    id_str, expected_version, entry.version
                ),
                hint: Some("Re-read the instance and retry".into()),
            });
        }

        Self::apply_mutations(&mut entry, mutations);
        entry.version += 1;

        Ok(())
    }

    async fn transition_instance(
        &self,
        id: &InstanceId,
        expected_version: u64,
        new_state: &str,
        mutations: &[Mutation],
        trail_entry: TrailEntry,
    ) -> SmqlResult<()> {
        let id_str = id.as_str();

        let mut entry = self
            .instances
            .get_mut(&id_str)
            .ok_or_else(|| SmqlError::not_found("Instance", &id_str))?;

        if entry.version != expected_version {
            return Err(SmqlError::Conflict {
                message: format!(
                    "Version conflict for instance '{}': expected {}, got {}",
                    id_str, expected_version, entry.version
                ),
                hint: Some("Re-read the instance and retry".into()),
            });
        }

        let old_state = entry.state.clone();
        let machine = entry.machine.clone();

        // Apply mutations
        Self::apply_mutations(&mut entry, mutations);

        // Update state
        entry.state = new_state.to_string();
        entry.state_entered_at = Utc::now();
        entry.version += 1;
        entry.trail_length += 1;

        // Drop the mutable reference before updating indices
        drop(entry);

        // Update state index
        self.remove_from_state_index(&machine, &old_state, &id_str);
        self.add_to_state_index(&machine, new_state, &id_str);

        // Append trail entry
        if let Some(trail) = self.trails.get(&id_str) {
            if let Ok(mut entries) = trail.write() {
                entries.push(trail_entry);
            }
        }

        Ok(())
    }

    async fn delete_instance(&self, id: &InstanceId) -> SmqlResult<()> {
        let id_str = id.as_str();

        let (_, instance) = self
            .instances
            .remove(&id_str)
            .ok_or_else(|| SmqlError::not_found("Instance", &id_str))?;

        self.remove_from_state_index(&instance.machine, &instance.state, &id_str);
        self.remove_from_machine_index(&instance.machine, &id_str);
        self.trails.remove(&id_str);

        // Remove from parent-child index if this is a child
        if let Some(parent_id) = &instance.parent_id {
            if let Some(mut children) = self.parent_index.get_mut(&parent_id.as_str()) {
                children.remove(&id_str);
            }
        }

        // Remove all timers for this instance
        let prefix = format!("{}:", &id_str);
        let keys: Vec<String> = self
            .timers
            .iter()
            .filter(|entry| entry.key().starts_with(&prefix))
            .map(|entry| entry.key().clone())
            .collect();
        for key in keys {
            self.timers.remove(&key);
        }

        Ok(())
    }

    async fn count_by_state(&self, machine: &str) -> SmqlResult<HashMap<String, usize>> {
        let mut counts: HashMap<String, usize> = HashMap::new();

        if let Some(ids) = self.machine_index.get(machine) {
            for id in ids.iter() {
                if let Some(inst) = self.instances.get(id) {
                    *counts.entry(inst.state.clone()).or_insert(0) += 1;
                }
            }
        }

        Ok(counts)
    }

    async fn append_trail_entry(&self, entry: &TrailEntry) -> SmqlResult<()> {
        let id_str = entry.instance_id.as_str();

        let trail = self
            .trails
            .entry(id_str)
            .or_insert_with(|| RwLock::new(Vec::new()));

        trail
            .write()
            .map_err(|e| SmqlError::internal(format!("Trail lock poisoned: {}", e)))?
            .push(entry.clone());

        Ok(())
    }

    async fn get_trail(&self, id: &InstanceId) -> SmqlResult<Vec<TrailEntry>> {
        let id_str = id.as_str();

        let trail = self
            .trails
            .get(&id_str)
            .ok_or_else(|| SmqlError::not_found("Trail", &id_str))?;

        trail
            .read()
            .map(|entries| entries.clone())
            .map_err(|e| SmqlError::internal(format!("Trail lock poisoned: {}", e)))
    }

    async fn query_trails(
        &self,
        machine: &str,
        filter: &TrailFilter,
    ) -> SmqlResult<Vec<TrailEntry>> {
        let mut results = Vec::new();

        let ids: Vec<String> = self
            .machine_index
            .get(machine)
            .map(|set| set.iter().cloned().collect())
            .unwrap_or_default();

        for id in &ids {
            if let Some(trail) = self.trails.get(id) {
                if let Ok(entries) = trail.read() {
                    for entry in entries.iter() {
                        let matches = filter
                            .from_state
                            .as_ref()
                            .is_none_or(|s| entry.from_state == *s)
                            && filter
                                .to_state
                                .as_ref()
                                .is_none_or(|s| entry.to_state == *s)
                            && filter
                                .actor
                                .as_ref()
                                .is_none_or(|a| entry.actor.as_ref() == Some(a))
                            && filter.after.is_none_or(|t| entry.timestamp > t)
                            && filter.before.is_none_or(|t| entry.timestamp < t);

                        if matches {
                            results.push(entry.clone());
                        }
                    }
                }
            }
        }

        // Sort by timestamp
        results.sort_by(|a, b| a.timestamp.cmp(&b.timestamp));

        if let Some(limit) = filter.limit {
            results.truncate(limit);
        }

        Ok(results)
    }

    async fn find_children(
        &self,
        parent_id: &InstanceId,
        child_machine: Option<&str>,
    ) -> SmqlResult<Vec<Instance>> {
        let parent_str = parent_id.as_str();
        let child_ids: Vec<String> = self
            .parent_index
            .get(&parent_str)
            .map(|set| set.iter().cloned().collect())
            .unwrap_or_default();

        let mut results = Vec::new();
        for child_id in &child_ids {
            if let Some(inst) = self.instances.get(child_id) {
                if let Some(machine) = child_machine {
                    if inst.machine == machine {
                        results.push(inst.clone());
                    }
                } else {
                    results.push(inst.clone());
                }
            }
        }
        Ok(results)
    }

    async fn get_parent(&self, child_id: &InstanceId) -> SmqlResult<Option<Instance>> {
        let child = self.get_instance(child_id).await?;
        match child {
            Some(inst) => {
                if let Some(parent_id) = &inst.parent_id {
                    self.get_instance(parent_id).await
                } else {
                    Ok(None)
                }
            }
            None => Ok(None),
        }
    }

    async fn migrate_instances_state(
        &self,
        machine: &str,
        from_state: &str,
        to_state: &str,
    ) -> SmqlResult<u64> {
        let key = Self::state_index_key(machine, from_state);
        let ids: Vec<String> = self
            .state_index
            .get(&key)
            .map(|set| set.iter().cloned().collect())
            .unwrap_or_default();

        let mut count = 0u64;
        for id in &ids {
            if let Some(mut entry) = self.instances.get_mut(id) {
                if entry.machine == machine && entry.state == from_state {
                    entry.state = to_state.to_string();
                    entry.state_entered_at = Utc::now();
                    entry.updated_at = Utc::now();
                    entry.version += 1;
                    count += 1;
                }
            }
        }

        // Update state indices
        for id in &ids {
            self.remove_from_state_index(machine, from_state, id);
            self.add_to_state_index(machine, to_state, id);
        }

        Ok(count)
    }

    async fn bulk_update_instances(
        &self,
        machine: &str,
        mutations: &[Mutation],
    ) -> SmqlResult<u64> {
        let ids: Vec<String> = self
            .machine_index
            .get(machine)
            .map(|set| set.iter().cloned().collect())
            .unwrap_or_default();

        let mut count = 0u64;
        for id in &ids {
            if let Some(mut entry) = self.instances.get_mut(id) {
                if entry.machine == machine {
                    Self::apply_mutations(&mut entry, mutations);
                    entry.version += 1;
                    count += 1;
                }
            }
        }

        Ok(count)
    }

    async fn store_timer(&self, timer: &StoredTimer) -> SmqlResult<()> {
        let key = format!("{}:{}", timer.instance_id, timer.from_state);
        self.timers.insert(key, timer.clone());
        Ok(())
    }

    async fn remove_timer(&self, instance_id: &str, state: &str) -> SmqlResult<()> {
        let key = format!("{}:{}", instance_id, state);
        self.timers.remove(&key);
        Ok(())
    }

    async fn remove_all_timers(&self, instance_id: &str) -> SmqlResult<()> {
        let prefix = format!("{}:", instance_id);
        let keys: Vec<String> = self
            .timers
            .iter()
            .filter(|entry| entry.key().starts_with(&prefix))
            .map(|entry| entry.key().clone())
            .collect();
        for key in keys {
            self.timers.remove(&key);
        }
        Ok(())
    }

    async fn load_all_timers(&self) -> SmqlResult<Vec<StoredTimer>> {
        Ok(self
            .timers
            .iter()
            .map(|entry| entry.value().clone())
            .collect())
    }
}

use async_trait::async_trait;
use chrono::Utc;
use rocksdb::{
    ColumnFamilyDescriptor, DBWithThreadMode, IteratorMode, MultiThreaded, Options, ReadOptions,
    WriteBatchWithTransaction,
};
use smql_ast::value::Value;
use smql_ast::{SmqlError, SmqlResult};
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;

use crate::instance::{
    Filter, Instance, InstanceId, Mutation, StoredTimer, TrailEntry, TrailFilter,
};
use crate::traits::Storage;

type DB = DBWithThreadMode<MultiThreaded>;

const CF_INSTANCES: &str = "instances";
const CF_STATE_INDEX: &str = "state_index";
const CF_MACHINE_INDEX: &str = "machine_index";
const CF_TRAILS: &str = "trails";
const CF_PARENT_INDEX: &str = "parent_index";
const CF_ID_INDEX: &str = "id_index";
const CF_TIMERS: &str = "timers";

const SEP: u8 = 0x00;

/// RocksDB-backed persistent storage backend.
///
/// Uses 7 column families: instances, state_index, machine_index, trails,
/// parent_index, id_index, and timers. Atomic writes use WriteBatch.
///
/// **Concurrency note:** Operations like `store_instance`, `update_instance`,
/// and `transition_instance` use a read-check-write pattern that is not
/// transactionally atomic. The engine serializes writes through its own
/// coordination, but direct concurrent access to the storage layer can
/// experience TOCTOU races. For true multi-writer safety, migrate to
/// `TransactionDB` with `get_for_update`.
pub struct RocksDBStorage {
    db: Arc<DB>,
}

impl RocksDBStorage {
    /// Open (or create) a RocksDB database at the given path with 7 column families.
    pub fn open(path: impl AsRef<Path>) -> SmqlResult<Self> {
        let mut db_opts = Options::default();
        db_opts.create_if_missing(true);
        db_opts.create_missing_column_families(true);

        let cf_names = [
            CF_INSTANCES,
            CF_STATE_INDEX,
            CF_MACHINE_INDEX,
            CF_TRAILS,
            CF_PARENT_INDEX,
            CF_ID_INDEX,
            CF_TIMERS,
        ];

        let cf_descriptors: Vec<ColumnFamilyDescriptor> = cf_names
            .iter()
            .map(|name| ColumnFamilyDescriptor::new(*name, Options::default()))
            .collect();

        let db = DB::open_cf_descriptors(&db_opts, path.as_ref(), cf_descriptors)
            .map_err(|e| SmqlError::storage(format!("Failed to open RocksDB: {}", e)))?;

        Ok(Self { db: Arc::new(db) })
    }

    /// Destroy the database at the given path (for test cleanup).
    pub fn destroy(path: impl AsRef<Path>) -> SmqlResult<()> {
        DB::destroy(&Options::default(), path.as_ref())
            .map_err(|e| SmqlError::storage(format!("Failed to destroy RocksDB: {}", e)))
    }

    // --- Key helpers ---

    fn make_key(parts: &[&[u8]]) -> Vec<u8> {
        let total_len: usize =
            parts.iter().map(|p| p.len()).sum::<usize>() + parts.len().saturating_sub(1);
        let mut key = Vec::with_capacity(total_len);
        for (i, part) in parts.iter().enumerate() {
            if i > 0 {
                key.push(SEP);
            }
            key.extend_from_slice(part);
        }
        key
    }

    fn instance_key(machine: &str, id: &str) -> Vec<u8> {
        Self::make_key(&[machine.as_bytes(), id.as_bytes()])
    }

    fn state_index_key(machine: &str, state: &str, id: &str) -> Vec<u8> {
        Self::make_key(&[machine.as_bytes(), state.as_bytes(), id.as_bytes()])
    }

    fn machine_index_key(machine: &str, id: &str) -> Vec<u8> {
        Self::make_key(&[machine.as_bytes(), id.as_bytes()])
    }

    fn trail_key(machine: &str, id: &str, seq: u64) -> Vec<u8> {
        let seq_str = format!("{:08x}", seq);
        Self::make_key(&[machine.as_bytes(), id.as_bytes(), seq_str.as_bytes()])
    }

    fn parent_index_key(parent_id: &str, child_machine: &str, child_id: &str) -> Vec<u8> {
        Self::make_key(&[
            parent_id.as_bytes(),
            child_machine.as_bytes(),
            child_id.as_bytes(),
        ])
    }

    fn prefix_key(parts: &[&[u8]]) -> Vec<u8> {
        let mut key = Self::make_key(parts);
        key.push(SEP);
        key
    }

    // --- Serialization ---

    fn serialize_instance(instance: &Instance) -> SmqlResult<Vec<u8>> {
        serde_json::to_vec(instance)
            .map_err(|e| SmqlError::storage(format!("Serialize instance: {}", e)))
    }

    fn deserialize_instance(bytes: &[u8]) -> SmqlResult<Instance> {
        serde_json::from_slice(bytes)
            .map_err(|e| SmqlError::storage(format!("Deserialize instance: {}", e)))
    }

    fn serialize_trail_entry(entry: &TrailEntry) -> SmqlResult<Vec<u8>> {
        serde_json::to_vec(entry)
            .map_err(|e| SmqlError::storage(format!("Serialize trail entry: {}", e)))
    }

    fn deserialize_trail_entry(bytes: &[u8]) -> SmqlResult<TrailEntry> {
        serde_json::from_slice(bytes)
            .map_err(|e| SmqlError::storage(format!("Deserialize trail entry: {}", e)))
    }

    // --- Internal helpers ---

    /// Load an instance by ID, using id_index to find the machine name.
    fn load_instance(&self, id: &str) -> SmqlResult<Option<Instance>> {
        let cf_id = self.db.cf_handle(CF_ID_INDEX).unwrap();
        match self
            .db
            .get_cf(&cf_id, id.as_bytes())
            .map_err(|e| SmqlError::storage(e.to_string()))?
        {
            Some(machine_bytes) => {
                let machine = String::from_utf8(machine_bytes.to_vec())
                    .map_err(|e| SmqlError::storage(format!("Invalid UTF-8 in id_index: {}", e)))?;
                let cf_inst = self.db.cf_handle(CF_INSTANCES).unwrap();
                let key = Self::instance_key(&machine, id);
                match self
                    .db
                    .get_cf(&cf_inst, &key)
                    .map_err(|e| SmqlError::storage(e.to_string()))?
                {
                    Some(bytes) => Ok(Some(Self::deserialize_instance(&bytes)?)),
                    None => Ok(None),
                }
            }
            None => Ok(None),
        }
    }

    /// Scan all keys with a given prefix in a column family, returning raw key-value pairs.
    /// Uses range iteration with an upper bound to efficiently scan by prefix.
    fn scan_prefix(&self, cf_name: &str, prefix: &[u8]) -> SmqlResult<Vec<(Vec<u8>, Vec<u8>)>> {
        let cf = self.db.cf_handle(cf_name).unwrap();

        // Compute upper bound: increment last byte to get the exclusive end of prefix range.
        let upper_bound = Self::prefix_upper_bound(prefix);

        let mut read_opts = ReadOptions::default();
        if let Some(ref ub) = upper_bound {
            read_opts.set_iterate_upper_bound(ub.clone());
        }

        let iter = self.db.iterator_cf_opt(
            &cf,
            read_opts,
            IteratorMode::From(prefix, rocksdb::Direction::Forward),
        );

        let mut results = Vec::new();
        for item in iter {
            let (key, value) = item.map_err(|e| SmqlError::storage(e.to_string()))?;
            if !key.starts_with(prefix) {
                break;
            }
            results.push((key.to_vec(), value.to_vec()));
        }
        Ok(results)
    }

    /// Compute an exclusive upper bound for a prefix scan.
    /// Increments the last byte; returns None if the prefix is all 0xFF.
    fn prefix_upper_bound(prefix: &[u8]) -> Option<Vec<u8>> {
        let mut upper = prefix.to_vec();
        for i in (0..upper.len()).rev() {
            if upper[i] < 0xFF {
                upper[i] += 1;
                upper.truncate(i + 1);
                return Some(upper);
            }
        }
        None // all 0xFF — scan to end
    }

    /// Scan state_index for a given machine+state prefix, returning instance IDs.
    fn scan_state_index(&self, machine: &str, state: &str) -> SmqlResult<Vec<String>> {
        let prefix = Self::prefix_key(&[machine.as_bytes(), state.as_bytes()]);
        let pairs = self.scan_prefix(CF_STATE_INDEX, &prefix)?;
        let mut ids = Vec::new();
        for (key, _) in pairs {
            // Key format: machine\0state\0id
            if let Some(id) = self.extract_last_segment(&key) {
                ids.push(id);
            }
        }
        Ok(ids)
    }

    /// Scan machine_index for all instance IDs of a machine.
    fn scan_machine_index(&self, machine: &str) -> SmqlResult<Vec<String>> {
        let prefix = Self::prefix_key(&[machine.as_bytes()]);
        let pairs = self.scan_prefix(CF_MACHINE_INDEX, &prefix)?;
        let mut ids = Vec::new();
        for (key, _) in pairs {
            if let Some(id) = self.extract_last_segment(&key) {
                ids.push(id);
            }
        }
        Ok(ids)
    }

    /// Extract the last NUL-separated segment from a key as a String.
    fn extract_last_segment(&self, key: &[u8]) -> Option<String> {
        let pos = key.iter().rposition(|&b| b == SEP)?;
        let segment = &key[pos + 1..];
        String::from_utf8(segment.to_vec()).ok()
    }

    fn apply_mutations(instance: &mut Instance, mutations: &[Mutation]) {
        for mutation in mutations {
            match mutation {
                Mutation::SetField(field, value) => {
                    instance.data.insert(field.clone(), value.clone());
                }
                Mutation::RemoveField(field) => {
                    instance.data.remove(field);
                }
                Mutation::IncrementField(field, delta) => {
                    if let Some(Value::Int(v)) = instance.data.get_mut(field) {
                        *v += delta;
                    }
                }
                Mutation::AppendToList(field, value) => {
                    if let Some(Value::List(list)) = instance.data.get_mut(field) {
                        list.push(value.clone());
                    }
                }
            }
        }
        instance.updated_at = Utc::now();
    }
}

#[async_trait]
impl Storage for RocksDBStorage {
    async fn store_instance(&self, instance: &Instance) -> SmqlResult<()> {
        let id_str = instance.id.as_str();

        // Check for duplicate
        if self.load_instance(&id_str)?.is_some() {
            return Err(SmqlError::Conflict {
                message: format!("Instance '{}' already exists", id_str),
                hint: None,
            });
        }

        let cf_inst = self.db.cf_handle(CF_INSTANCES).unwrap();
        let cf_state = self.db.cf_handle(CF_STATE_INDEX).unwrap();
        let cf_machine = self.db.cf_handle(CF_MACHINE_INDEX).unwrap();
        let cf_id = self.db.cf_handle(CF_ID_INDEX).unwrap();
        let cf_parent = self.db.cf_handle(CF_PARENT_INDEX).unwrap();

        let bytes = Self::serialize_instance(instance)?;

        let mut batch = WriteBatchWithTransaction::<false>::default();
        batch.put_cf(
            &cf_inst,
            Self::instance_key(&instance.machine, &id_str),
            &bytes,
        );
        batch.put_cf(
            &cf_state,
            Self::state_index_key(&instance.machine, &instance.state, &id_str),
            b"",
        );
        batch.put_cf(
            &cf_machine,
            Self::machine_index_key(&instance.machine, &id_str),
            b"",
        );
        batch.put_cf(&cf_id, id_str.as_bytes(), instance.machine.as_bytes());

        if let Some(parent_id) = &instance.parent_id {
            batch.put_cf(
                &cf_parent,
                Self::parent_index_key(&parent_id.as_str(), &instance.machine, &id_str),
                b"",
            );
        }

        self.db
            .write(batch)
            .map_err(|e| SmqlError::storage(e.to_string()))?;

        Ok(())
    }

    async fn get_instance(&self, id: &InstanceId) -> SmqlResult<Option<Instance>> {
        self.load_instance(&id.as_str())
    }

    async fn find_instances(&self, machine: &str, filter: &Filter) -> SmqlResult<Vec<Instance>> {
        let candidate_ids: Vec<String> = if let Some(state) = &filter.state {
            self.scan_state_index(machine, state)?
        } else if let Some(states) = &filter.states {
            let mut ids = Vec::new();
            for state in states {
                ids.extend(self.scan_state_index(machine, state)?);
            }
            ids
        } else {
            self.scan_machine_index(machine)?
        };

        let cf_inst = self.db.cf_handle(CF_INSTANCES).unwrap();
        let mut results: Vec<Instance> = Vec::new();
        for id in &candidate_ids {
            let key = Self::instance_key(machine, id);
            if let Some(bytes) = self
                .db
                .get_cf(&cf_inst, &key)
                .map_err(|e| SmqlError::storage(e.to_string()))?
            {
                let inst = Self::deserialize_instance(&bytes)?;
                if inst.machine == machine {
                    if let Some(pred) = &filter.predicate {
                        if pred.matches(&inst.data) {
                            results.push(inst);
                        }
                    } else {
                        results.push(inst);
                    }
                }
            }
        }

        // Sort by ID for deterministic cursor-based pagination
        results.sort_by(|a, b| a.id.as_str().cmp(&b.id.as_str()));

        // Apply cursor filter: only instances with ID > after_id
        if let Some(after_id) = &filter.after_id {
            results.retain(|inst| inst.id.as_str().as_str() > after_id.as_str());
        }

        // Apply offset and limit
        if let Some(offset) = filter.offset {
            if offset < results.len() {
                results = results.into_iter().skip(offset).collect();
            } else {
                results.clear();
            }
        }
        if let Some(limit) = filter.limit {
            results.truncate(limit);
        }

        Ok(results)
    }

    async fn update_instance(
        &self,
        id: &InstanceId,
        expected_version: u64,
        mutations: &[Mutation],
    ) -> SmqlResult<()> {
        let id_str = id.as_str();
        let mut instance = self
            .load_instance(&id_str)?
            .ok_or_else(|| SmqlError::not_found("Instance", &id_str))?;

        if instance.version != expected_version {
            return Err(SmqlError::Conflict {
                message: format!(
                    "Version conflict for instance '{}': expected {}, got {}",
                    id_str, expected_version, instance.version
                ),
                hint: Some("Re-read the instance and retry".into()),
            });
        }

        Self::apply_mutations(&mut instance, mutations);
        instance.version += 1;

        let cf_inst = self.db.cf_handle(CF_INSTANCES).unwrap();
        let bytes = Self::serialize_instance(&instance)?;
        self.db
            .put_cf(
                &cf_inst,
                Self::instance_key(&instance.machine, &id_str),
                &bytes,
            )
            .map_err(|e| SmqlError::storage(e.to_string()))?;

        Ok(())
    }

    async fn transition_instance(
        &self,
        id: &InstanceId,
        expected_version: u64,
        new_state: &str,
        mutations: &[Mutation],
        trail_entry: TrailEntry,
    ) -> SmqlResult<()> {
        let id_str = id.as_str();
        let mut instance = self
            .load_instance(&id_str)?
            .ok_or_else(|| SmqlError::not_found("Instance", &id_str))?;

        if instance.version != expected_version {
            return Err(SmqlError::Conflict {
                message: format!(
                    "Version conflict for instance '{}': expected {}, got {}",
                    id_str, expected_version, instance.version
                ),
                hint: Some("Re-read the instance and retry".into()),
            });
        }

        let old_state = instance.state.clone();
        let machine = instance.machine.clone();

        Self::apply_mutations(&mut instance, mutations);
        instance.state = new_state.to_string();
        instance.state_entered_at = Utc::now();
        instance.version += 1;
        instance.trail_length += 1;

        let cf_inst = self.db.cf_handle(CF_INSTANCES).unwrap();
        let cf_state = self.db.cf_handle(CF_STATE_INDEX).unwrap();
        let cf_trails = self.db.cf_handle(CF_TRAILS).unwrap();

        let mut batch = WriteBatchWithTransaction::<false>::default();

        // Update instance
        let inst_bytes = Self::serialize_instance(&instance)?;
        batch.put_cf(&cf_inst, Self::instance_key(&machine, &id_str), &inst_bytes);

        // Update state index
        batch.delete_cf(
            &cf_state,
            Self::state_index_key(&machine, &old_state, &id_str),
        );
        batch.put_cf(
            &cf_state,
            Self::state_index_key(&machine, new_state, &id_str),
            b"",
        );

        // Append trail entry
        let trail_bytes = Self::serialize_trail_entry(&trail_entry)?;
        batch.put_cf(
            &cf_trails,
            Self::trail_key(&machine, &id_str, trail_entry.sequence),
            &trail_bytes,
        );

        self.db
            .write(batch)
            .map_err(|e| SmqlError::storage(e.to_string()))?;

        Ok(())
    }

    async fn delete_instance(&self, id: &InstanceId) -> SmqlResult<()> {
        let id_str = id.as_str();
        let instance = self
            .load_instance(&id_str)?
            .ok_or_else(|| SmqlError::not_found("Instance", &id_str))?;

        let cf_inst = self.db.cf_handle(CF_INSTANCES).unwrap();
        let cf_state = self.db.cf_handle(CF_STATE_INDEX).unwrap();
        let cf_machine = self.db.cf_handle(CF_MACHINE_INDEX).unwrap();
        let cf_id = self.db.cf_handle(CF_ID_INDEX).unwrap();
        let cf_parent = self.db.cf_handle(CF_PARENT_INDEX).unwrap();
        let cf_trails = self.db.cf_handle(CF_TRAILS).unwrap();

        let mut batch = WriteBatchWithTransaction::<false>::default();

        batch.delete_cf(&cf_inst, Self::instance_key(&instance.machine, &id_str));
        batch.delete_cf(
            &cf_state,
            Self::state_index_key(&instance.machine, &instance.state, &id_str),
        );
        batch.delete_cf(
            &cf_machine,
            Self::machine_index_key(&instance.machine, &id_str),
        );
        batch.delete_cf(&cf_id, id_str.as_bytes());

        // Delete from parent index if child
        if let Some(parent_id) = &instance.parent_id {
            batch.delete_cf(
                &cf_parent,
                Self::parent_index_key(&parent_id.as_str(), &instance.machine, &id_str),
            );
        }

        // Delete all trail entries for this instance
        let trail_prefix = Self::prefix_key(&[instance.machine.as_bytes(), id_str.as_bytes()]);
        let trail_pairs = self.scan_prefix(CF_TRAILS, &trail_prefix)?;
        for (key, _) in trail_pairs {
            batch.delete_cf(&cf_trails, &key);
        }

        // Delete all timers for this instance
        let cf_timers = self.db.cf_handle(CF_TIMERS).unwrap();
        let timer_prefix = Self::prefix_key(&[id_str.as_bytes()]);
        let timer_pairs = self.scan_prefix(CF_TIMERS, &timer_prefix)?;
        for (key, _) in timer_pairs {
            batch.delete_cf(&cf_timers, &key);
        }

        self.db
            .write(batch)
            .map_err(|e| SmqlError::storage(e.to_string()))?;

        Ok(())
    }

    async fn count_by_state(&self, machine: &str) -> SmqlResult<HashMap<String, usize>> {
        let mut counts: HashMap<String, usize> = HashMap::new();

        // Scan state_index keys directly: format is machine\0state\0id
        // This avoids loading and deserializing every instance.
        let prefix = Self::prefix_key(&[machine.as_bytes()]);
        let pairs = self.scan_prefix(CF_STATE_INDEX, &prefix)?;
        let machine_prefix_len = machine.len() + 1; // machine + SEP

        for (key, _) in pairs {
            // Key: machine\0state\0id — extract the state (middle segment)
            let remainder = &key[machine_prefix_len..];
            if let Some(sep_pos) = remainder.iter().position(|&b| b == SEP) {
                if let Ok(state) = std::str::from_utf8(&remainder[..sep_pos]) {
                    *counts.entry(state.to_string()).or_insert(0) += 1;
                }
            }
        }

        Ok(counts)
    }

    async fn append_trail_entry(&self, entry: &TrailEntry) -> SmqlResult<()> {
        let cf_trails = self.db.cf_handle(CF_TRAILS).unwrap();
        let id_str = entry.instance_id.as_str();
        let key = Self::trail_key(&entry.machine, &id_str, entry.sequence);
        let bytes = Self::serialize_trail_entry(entry)?;
        self.db
            .put_cf(&cf_trails, &key, &bytes)
            .map_err(|e| SmqlError::storage(e.to_string()))?;
        Ok(())
    }

    async fn get_trail(&self, id: &InstanceId) -> SmqlResult<Vec<TrailEntry>> {
        let id_str = id.as_str();

        // We need the machine name to build the trail prefix.
        // Look it up from id_index.
        let cf_id = self.db.cf_handle(CF_ID_INDEX).unwrap();
        let machine = match self
            .db
            .get_cf(&cf_id, id_str.as_bytes())
            .map_err(|e| SmqlError::storage(e.to_string()))?
        {
            Some(bytes) => String::from_utf8(bytes.to_vec())
                .map_err(|e| SmqlError::storage(format!("Invalid UTF-8 in id_index: {}", e)))?,
            None => return Err(SmqlError::not_found("Trail", &id_str)),
        };

        let prefix = Self::prefix_key(&[machine.as_bytes(), id_str.as_bytes()]);
        let pairs = self.scan_prefix(CF_TRAILS, &prefix)?;

        let mut entries = Vec::new();
        for (_, value) in pairs {
            entries.push(Self::deserialize_trail_entry(&value)?);
        }

        Ok(entries)
    }

    async fn query_trails(
        &self,
        machine: &str,
        filter: &TrailFilter,
    ) -> SmqlResult<Vec<TrailEntry>> {
        let ids = self.scan_machine_index(machine)?;
        let mut results = Vec::new();

        for id in &ids {
            let prefix = Self::prefix_key(&[machine.as_bytes(), id.as_bytes()]);
            let pairs = self.scan_prefix(CF_TRAILS, &prefix)?;

            for (_, value) in pairs {
                let entry = Self::deserialize_trail_entry(&value)?;
                let matches = filter
                    .from_state
                    .as_ref()
                    .is_none_or(|s| entry.from_state == *s)
                    && filter
                        .to_state
                        .as_ref()
                        .is_none_or(|s| entry.to_state == *s)
                    && filter
                        .actor
                        .as_ref()
                        .is_none_or(|a| entry.actor.as_ref() == Some(a))
                    && filter.after.is_none_or(|t| entry.timestamp > t)
                    && filter.before.is_none_or(|t| entry.timestamp < t);

                if matches {
                    results.push(entry);
                }
            }
        }

        results.sort_by(|a, b| a.timestamp.cmp(&b.timestamp));

        if let Some(limit) = filter.limit {
            results.truncate(limit);
        }

        Ok(results)
    }

    async fn find_children(
        &self,
        parent_id: &InstanceId,
        child_machine: Option<&str>,
    ) -> SmqlResult<Vec<Instance>> {
        let parent_str = parent_id.as_str();

        let prefix = if let Some(machine) = child_machine {
            Self::prefix_key(&[parent_str.as_bytes(), machine.as_bytes()])
        } else {
            Self::prefix_key(&[parent_str.as_bytes()])
        };

        let pairs = self.scan_prefix(CF_PARENT_INDEX, &prefix)?;
        let mut results = Vec::new();

        for (key, _) in pairs {
            // Extract child_id from key: parent_id\0child_machine\0child_id
            if let Some(child_id) = self.extract_last_segment(&key) {
                if let Some(inst) = self.load_instance(&child_id)? {
                    results.push(inst);
                }
            }
        }

        Ok(results)
    }

    async fn get_parent(&self, child_id: &InstanceId) -> SmqlResult<Option<Instance>> {
        let child = self.get_instance(child_id).await?;
        match child {
            Some(inst) => {
                if let Some(parent_id) = &inst.parent_id {
                    self.get_instance(parent_id).await
                } else {
                    Ok(None)
                }
            }
            None => Ok(None),
        }
    }

    async fn migrate_instances_state(
        &self,
        machine: &str,
        from_state: &str,
        to_state: &str,
    ) -> SmqlResult<u64> {
        let ids = self.scan_state_index(machine, from_state)?;

        let cf_inst = self.db.cf_handle(CF_INSTANCES).unwrap();
        let cf_state = self.db.cf_handle(CF_STATE_INDEX).unwrap();

        let mut batch = WriteBatchWithTransaction::<false>::default();
        let mut count = 0u64;

        for id in &ids {
            let key = Self::instance_key(machine, id);
            if let Some(bytes) = self
                .db
                .get_cf(&cf_inst, &key)
                .map_err(|e| SmqlError::storage(e.to_string()))?
            {
                let mut inst = Self::deserialize_instance(&bytes)?;
                if inst.machine == machine && inst.state == from_state {
                    inst.state = to_state.to_string();
                    inst.state_entered_at = Utc::now();
                    inst.updated_at = Utc::now();
                    inst.version += 1;

                    let new_bytes = Self::serialize_instance(&inst)?;
                    batch.put_cf(&cf_inst, &key, &new_bytes);
                    batch.delete_cf(&cf_state, Self::state_index_key(machine, from_state, id));
                    batch.put_cf(&cf_state, Self::state_index_key(machine, to_state, id), b"");
                    count += 1;
                }
            }
        }

        self.db
            .write(batch)
            .map_err(|e| SmqlError::storage(e.to_string()))?;

        Ok(count)
    }

    async fn bulk_update_instances(
        &self,
        machine: &str,
        mutations: &[Mutation],
    ) -> SmqlResult<u64> {
        let ids = self.scan_machine_index(machine)?;

        let cf_inst = self.db.cf_handle(CF_INSTANCES).unwrap();

        let mut batch = WriteBatchWithTransaction::<false>::default();
        let mut count = 0u64;

        for id in &ids {
            let key = Self::instance_key(machine, id);
            if let Some(bytes) = self
                .db
                .get_cf(&cf_inst, &key)
                .map_err(|e| SmqlError::storage(e.to_string()))?
            {
                let mut inst = Self::deserialize_instance(&bytes)?;
                if inst.machine == machine {
                    Self::apply_mutations(&mut inst, mutations);
                    inst.version += 1;
                    let new_bytes = Self::serialize_instance(&inst)?;
                    batch.put_cf(&cf_inst, &key, &new_bytes);
                    count += 1;
                }
            }
        }

        self.db
            .write(batch)
            .map_err(|e| SmqlError::storage(e.to_string()))?;

        Ok(count)
    }

    async fn store_timer(&self, timer: &StoredTimer) -> SmqlResult<()> {
        let cf = self.db.cf_handle(CF_TIMERS).unwrap();
        let key = Self::make_key(&[timer.instance_id.as_bytes(), timer.from_state.as_bytes()]);
        let bytes = serde_json::to_vec(timer)
            .map_err(|e| SmqlError::storage(format!("Serialize timer: {}", e)))?;
        self.db
            .put_cf(&cf, &key, &bytes)
            .map_err(|e| SmqlError::storage(e.to_string()))?;
        Ok(())
    }

    async fn remove_timer(&self, instance_id: &str, state: &str) -> SmqlResult<()> {
        let cf = self.db.cf_handle(CF_TIMERS).unwrap();
        let key = Self::make_key(&[instance_id.as_bytes(), state.as_bytes()]);
        self.db
            .delete_cf(&cf, &key)
            .map_err(|e| SmqlError::storage(e.to_string()))?;
        Ok(())
    }

    async fn remove_all_timers(&self, instance_id: &str) -> SmqlResult<()> {
        let cf = self.db.cf_handle(CF_TIMERS).unwrap();
        let prefix = Self::prefix_key(&[instance_id.as_bytes()]);
        let pairs = self.scan_prefix(CF_TIMERS, &prefix)?;
        let mut batch = WriteBatchWithTransaction::<false>::default();
        for (key, _) in pairs {
            batch.delete_cf(&cf, &key);
        }
        self.db
            .write(batch)
            .map_err(|e| SmqlError::storage(e.to_string()))?;
        Ok(())
    }

    async fn load_all_timers(&self) -> SmqlResult<Vec<StoredTimer>> {
        let cf = self.db.cf_handle(CF_TIMERS).unwrap();
        let iter = self.db.iterator_cf(&cf, IteratorMode::Start);
        let mut timers = Vec::new();
        for item in iter {
            let (_, value) = item.map_err(|e| SmqlError::storage(e.to_string()))?;
            let timer: StoredTimer = serde_json::from_slice(&value)
                .map_err(|e| SmqlError::storage(format!("Deserialize timer: {}", e)))?;
            timers.push(timer);
        }
        Ok(timers)
    }
}

#[cfg(all(test, feature = "rocksdb"))]
mod rocksdb_storage_tests {
    use crate::instance::*;
    use crate::rocksdb::RocksDBStorage;
    use crate::traits::Storage;
    use chrono::Utc;
    use smql_ast::value::Value;
    use std::collections::HashMap;
    use std::sync::atomic::{AtomicU64, Ordering};

    static COUNTER: AtomicU64 = AtomicU64::new(0);

    fn temp_path() -> String {
        let c = COUNTER.fetch_add(1, Ordering::SeqCst);
        format!("/tmp/smql-test-rocksdb-{}-{}", std::process::id(), c)
    }

    fn open_storage() -> (RocksDBStorage, String) {
        let path = temp_path();
        let storage = RocksDBStorage::open(&path).unwrap();
        (storage, path)
    }

    fn cleanup(path: &str) {
        let _ = RocksDBStorage::destroy(path);
    }

    fn make_instance(machine: &str, state: &str) -> Instance {
        let mut data = HashMap::new();
        data.insert("name".to_string(), Value::Text("test".to_string()));
        Instance::new(machine.to_string(), state.to_string(), data)
    }

    fn make_trail_entry(instance: &Instance, from: &str, to: &str, seq: u64) -> TrailEntry {
        TrailEntry {
            instance_id: instance.id.clone(),
            machine: instance.machine.clone(),
            sequence: seq,
            from_state: from.to_string(),
            to_state: to.to_string(),
            transition_name: None,
            actor: Some("test_user".to_string()),
            memo: None,
            timestamp: Utc::now(),
            data_snapshot: None,
        }
    }

